_RBY1_CHASSIS_MIN_LOCAL_M = (-0.325, -0.250)
_RBY1_CHASSIS_MAX_LOCAL_M = (0.295, 0.250)
_MINIMUM_BASE_STRUCTURE_CLEARANCE_M = 0.03
_MINIMUM_GREENHOUSE_CLEARANCE_M = 0.01
_MINIMUM_FOLIAGE_CLEARANCE_M = 0.0005
_WARM_START_COMFORTABLE_CLEARANCE_M = 0.012
_LOCAL_REQUESTED_BASE_SEARCH_RADIUS_M = 0.020
_LOCAL_REQUESTED_BASE_LATERAL_OFFSETS_M = (
    0.0,
    -0.005,
    0.005,
    -0.010,
    0.010,
    -0.020,
    0.020,
)

# At 240 Hz this impulse ceiling is about 2.4 N average contact force.
# Rigid stem/petiole and greenhouse contacts have no such allowance.
_INCIDENTAL_FOLIAGE_IMPULSE_NS = 0.01


def _probe_capture_interval_steps(
    capture_hz: float,
    physics_hz: float = 240.0,
) -> int:
    """Return the exact physics-step cadence for deterministic probe video."""
    if capture_hz <= 0.0 or physics_hz <= 0.0:
        raise ValueError("probe capture and physics rates must be positive")
    interval = physics_hz / capture_hz
    rounded = int(round(interval))
    if abs(interval - rounded) > 1e-9:
        raise ValueError("probe capture rate must divide the physics rate exactly")
    return max(rounded, 1)


def _planned_route_start_reconciliation_required(
    maximum_error_degrees: float,
    accepted_error_degrees: float,
    *,
    exact_error_degrees: float = 1e-6,
) -> bool:
    """Require a measured connector when an audited route start has drifted."""
    error = float(maximum_error_degrees)
    accepted = float(accepted_error_degrees)
    exact = float(exact_error_degrees)
    if (
        not all(math.isfinite(value) for value in (error, accepted, exact))
        or error < 0.0
        or accepted <= 0.0
        or exact < 0.0
        or exact >= accepted
    ):
        raise ValueError("planned-route start tolerances must be finite and valid")
    if error > accepted:
        raise ValueError("planned-route start exceeds the accepted physical error")
    return error > exact

def _local_requested_base_depth_advances(
    depth_span_m: float,
    maximum_advance_m: float,
) -> tuple[float, ...]:
    """Return an aisle-bounded local Y lattice around a requested base pose."""
    depth_span_m = float(depth_span_m)
    maximum_advance_m = float(maximum_advance_m)
    if not math.isfinite(depth_span_m) or not math.isfinite(maximum_advance_m):
        raise ValueError("local base-search distances must be finite")
    if (
        depth_span_m < 0.0
        or maximum_advance_m < 0.0
        or depth_span_m > maximum_advance_m + 1e-9
    ):
        raise ValueError("requested base pose must lie inside the aisle search interval")
    deltas_m = (0.0, 0.005, -0.005, 0.010, -0.010, 0.020, -0.020)
    return tuple(
        dict.fromkeys(
            min(max(depth_span_m + delta_m, 0.0), maximum_advance_m)
            for delta_m in deltas_m
        )
    )


@dataclasses.dataclass
class VineRuntime:
    """One static greenhouse placement upgraded to a dynamic vine."""

    name: str
    source: pathlib.Path
    root_path: str
    plant: object
    skeletons: dict
    rig: object
    clips: list
    severer: object
    organ_indices: dict[str, int]
    cut_sites: dict[str, tuple[float, float, float]]
    placement_m: tuple[float, float, float]
    rest_positions: object | None = None


_RIGHT_ENDPOINT_WORKER_MODEL = None


def _initialize_right_endpoint_worker() -> None:
    global _RIGHT_ENDPOINT_WORKER_MODEL

    from greenhouse_sim.robot_kinematics import Rby1Kinematics

    _RIGHT_ENDPOINT_WORKER_MODEL = Rby1Kinematics()


def _solve_right_endpoint_worker(job) -> dict:
    if _RIGHT_ENDPOINT_WORKER_MODEL is None:
        _initialize_right_endpoint_worker()
    (
        roll_degrees,
        wing,
        seed_index,
        seed,
        desired,
        base_matrix,
    ) = job
    import numpy as np

    solution = _RIGHT_ENDPOINT_WORKER_MODEL.solve_pose(
        'right',
        np.asarray(desired, dtype=np.float64),
        seed,
        np.asarray(base_matrix, dtype=np.float64),
    )
    return {
        'roll_degrees': float(roll_degrees),
        'edge_wing_local_m': list(wing),
        'seed_index': int(seed_index),
        'solution': dataclasses.asdict(solution),
    }


