def _emit(report: dict, path: pathlib.Path) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    payload = json.dumps(report, indent=2, default=str)
    last_error = None
    for _ in range(200):
        try:
            path.write_text(payload, encoding="utf-8")
            return
        except PermissionError as error:
            last_error = error
            time.sleep(0.01)
    raise last_error


def main() -> int:
    args = parse_args()
    scene_path = args.scene.resolve()
    vine_dir = args.vine_dir.resolve()
    robot_path = args.robot.resolve()
    if not scene_path.exists():
        print(f"scene not found: {scene_path}; run build_scene.py first")
        return 1
    vine_sources = sorted(vine_dir.glob("tomato_*.glb"))
    if not vine_sources:
        print(f"no tomato GLBs found under {vine_dir}")
        return 1
    target_vine_source = (
        None
        if args.target_vine_source is None
        else args.target_vine_source.resolve()
    )
    if target_vine_source is not None and (
        not target_vine_source.is_file()
        or target_vine_source.suffix.lower() != ".glb"
    ):
        print(f"target vine GLB not found: {target_vine_source}")
        return 1
    if args.physics_vines < 1:
        print("--physics-vines must be at least 1")
        return 1
    if args.neighbor_safety_vines < 0:
        print("--neighbor-safety-vines cannot be negative")
        return 1
    if args.left_grasp_approach_yaw is not None and any(
        not math.isfinite(value) or abs(value) > 60.0
        for value in args.left_grasp_approach_yaw
    ):
        print(
            "--left-grasp-approach-yaw values must be finite and within "
            "+/-60 degrees"
        )
        return 1
    if args.left_grasp_axial_offset is not None and any(
        not math.isfinite(value) or abs(value) > 0.02
        for value in args.left_grasp_axial_offset
    ):
        print(
            "--left-grasp-axial-offset values must be finite and within "
            "+/-0.02 m"
        )
        return 1
    if args.left_pretension_pull is not None and (
        not math.isfinite(args.left_pretension_pull)
        or not 0.0 < args.left_pretension_pull <= _LEFT_PRETENSION_PULL_M
    ):
        print(
            "--left-pretension-pull must be finite, positive, and no greater "
            f"than {_LEFT_PRETENSION_PULL_M} m"
        )
        return 1
    if args.right_base_endpoint_roll is not None and any(
        not math.isfinite(value) or abs(value) > 120.0
        for value in args.right_base_endpoint_roll
    ):
        print(
            "--right-base-endpoint-roll values must be finite and within "
            "+/-120 degrees"
        )
        return 1
    if args.teleop_command_file is not None and args.no_robot:
        print("--teleop-command-file requires the fitted robot")
        return 1
    if args.teleop_record_dir is not None and args.teleop_command_file is None:
        print("--teleop-record-dir requires --teleop-command-file")
        return 1
    if args.teleop_watchdog_ms <= 0.0 or args.teleop_max_joint_speed <= 0.0:
        print("teleop watchdog and maximum joint speed must be positive")
        return 1
    if args.teleop_record_hz <= 0.0 or args.teleop_width < 1 or args.teleop_height < 1:
        print("teleop recording rate and dimensions must be positive")
        return 1
    if args.probe_frame_dir is not None and args.bimanual_probe is None:
        print("--probe-frame-dir requires --bimanual-probe")
        return 1
    if args.probe_video_width < 1 or args.probe_video_height < 1:
        print("probe video dimensions must be positive")
        return 1
    try:
        _probe_capture_interval_steps(args.probe_video_hz)
    except ValueError as exc:
        print(str(exc))
        return 1
    if args.rl_server and args.no_robot:
        print("--rl-server requires the fitted robot")
        return 1
    if args.rl_server and args.teleop_command_file is not None:
        print("--rl-server and --teleop-command-file are mutually exclusive")
        return 1
    if args.rl_server and args.bimanual_probe is not None:
        print("--rl-server and --bimanual-probe are mutually exclusive")
        return 1
    if args.rl_server and args.rl_host not in {"127.0.0.1", "localhost", "::1"}:
        print("--rl-host must be loopback; remote control is deliberately disabled")
        return 1
    if not 1 <= args.rl_port <= 65535:
        print("--rl-port must be between 1 and 65535")
        return 1
    if (
        args.rl_control_hz <= 0.0
        or args.rl_max_arm_speed <= 0.0
        or args.rl_max_arm_acceleration <= 0.0
        or args.rl_max_episode_steps < 1
        or args.rl_reset_settle_steps < 0
        or args.rl_reset_joint_noise < 0.0
    ):
        print("RL rates and episode limits must be positive")
        return 1
    if args.rl_frame_dir is not None and not args.rl_server:
        print("--rl-frame-dir requires --rl-server")
        return 1
    if args.rl_initial_left_arm is not None and not args.rl_server:
        print("--rl-initial-left-arm requires --rl-server")
        return 1
    if args.rl_video_width < 1 or args.rl_video_height < 1:
        print("RL video dimensions must be positive")
        return 1
    if abs(240.0 / args.rl_control_hz - round(240.0 / args.rl_control_hz)) > 1e-9:
        print("--rl-control-hz must divide the 240 Hz physics rate exactly")
        return 1
    if not args.no_robot and not robot_path.exists():
        print(f"fitted robot not found: {robot_path}; run build_robot.py first or pass --no-robot")
        return 1

    report: dict = {
        "stage": "starting",
        "scene": str(scene_path),
        "physics_vines_requested": args.physics_vines,
        "collision_mode": args.collision_mode,
        "target_vine_source_override": (
            None if target_vine_source is None else str(target_vine_source)
        ),
        "robot_requested": not args.no_robot,
        "left_grasp_axial_offset_override_m": (
            None
            if args.left_grasp_axial_offset is None
            else list(args.left_grasp_axial_offset)
        ),
        "left_pretension_pull_override_m": args.left_pretension_pull,
        "right_base_endpoint_roll_override_degrees": (
            None
            if args.right_base_endpoint_roll is None
            else list(args.right_base_endpoint_roll)
        ),
    }
    _emit(report, args.report)

    from isaacsim import SimulationApp

    headless = args.headless or args.screenshot is not None
    app = SimulationApp({"headless": headless})

    from greenhouse_sim import base_planner
    from greenhouse_sim import cutting
    from greenhouse_sim import deleaf_task
    from greenhouse_sim import episode
    from greenhouse_sim import glb
    from greenhouse_sim import isaac_rl
    from greenhouse_sim import organs
    from greenhouse_sim import rl_env
    from greenhouse_sim import robot_hardware
    from greenhouse_sim import robot_kinematics
    from greenhouse_sim import robot_scene
    from greenhouse_sim import skeleton as skeleton_module
    from greenhouse_sim import teleop
    from greenhouse_sim import vine_interaction
    from greenhouse_sim import vine_physics
    from greenhouse_sim import vine_usd
    from greenhouse_sim import vine_visuals
    import numpy as np
    import omni.usd
    import time
    from pxr import Gf
    from pxr import Sdf
    from pxr import Usd
    from pxr import UsdGeom

    omni.usd.get_context().open_stage(str(scene_path))
    for _ in range(10):
        app.update()
    stage = omni.usd.get_context().get_stage()
    stage.SetEditTarget(stage.GetSessionLayer())

    robot_placement = None
    teleop_startup_gripper_openness = None

    static_scope = stage.GetPrimAtPath("/World/Vines")
    static_vines = list(static_scope.GetChildren()) if static_scope and static_scope.IsValid() else []
    try:
        selected = _select_physics_vines(
            static_vines,
            args.target_vine,
            args.physics_vines,
        )
    except ValueError as exc:
        report.update(stage="failed", error=str(exc))
        _emit(report, args.report)
        app.close()
        return 1
    if not selected:
        report.update(stage="failed", error="no /World/Vines placements in scene")
        _emit(report, args.report)
        app.close()
        return 1

    vine_physics.apply_scene_physics(stage)
    physics_scene_prim = stage.GetPrimAtPath('/World/PhysicsScene')
    report['physics_scene'] = {
        'path': str(physics_scene_prim.GetPath()),
        'solver_type': physics_scene_prim.GetAttribute(
            'physxScene:solverType'
        ).Get(),
        'ccd_enabled': bool(
            physics_scene_prim.GetAttribute(
                'physxScene:enableCCD'
            ).Get()
        ),
        'enhanced_determinism_enabled': bool(
            physics_scene_prim.GetAttribute(
                'physxScene:enableEnhancedDeterminism'
            ).Get()
        ),
    }
    UsdGeom.Scope.Define(stage, Sdf.Path("/World/InteractiveVines"))

    runtimes: list[VineRuntime] = []
    safety_colliders = []
    placement_centres = []
    for selection_index, static_prim in enumerate(selected):
        placement = UsdGeom.Xformable(static_prim).ComputeLocalToWorldTransform(Usd.TimeCode.Default())
        placement_centre = np.array(placement.ExtractTranslation(), dtype=np.float64)
        placement_centres.append(placement_centre)
        source = (
            target_vine_source
            if selection_index == 0 and target_vine_source is not None
            else _source_for_placement(static_prim.GetName(), vine_sources)
        )
        static_prim.SetActive(False)

        plant = organs.load_plant(source)
        asset = glb.read_glb(source)
        skeletons = skeleton_module.skeletonise_plant(plant, segment_length=args.segment)
        points_to_stage, directions_to_stage = _placement_transforms(placement, vine_usd, Gf, np)

        root_path = f"/World/InteractiveVines/{static_prim.GetName()}"
        UsdGeom.Xform.Define(stage, Sdf.Path(root_path))
        rig = vine_physics.author_plant_physics(
            stage,
            plant,
            root_path,
            skeletons,
            points_to_stage,
            properties=vine_physics.TissueProperties(
                cut_force_n=args.cut_force,
                tear_force_n=args.tear_force,
            ),
            visible_colliders=args.show_colliders,
            collision_mode=args.collision_mode,
        )
        vine_visuals.attach_organ_visuals(
            stage,
            rig,
            plant,
            asset,
            points_to_stage,
            to_stage_directions=directions_to_stage,
        )
        if args.collision_mode == "interaction":
            foliage_colliders = vine_physics.author_foliage_contact_proxies(
                stage,
                rig,
                plant,
                points_to_stage,
                visible=args.show_colliders,
            )
            rig = dataclasses.replace(
                rig,
                collider_paths=rig.collider_paths
                + tuple(info.path for info in foliage_colliders),
                colliders=rig.colliders + foliage_colliders,
            )
        clips = vine_physics.add_trellis_clips(stage, rig, plant.root, spacing=args.clip_spacing)
        # The supplied greenhouse already owns collision ground at the measured
        # cultivation-floor height. A hidden tray at gutter height made an
        # orphan appear deposited while it was still 1.19 m above the aisle.

        organ_indices = {organ.label: organ.index for organ in plant.organs}
        cut_sites = {
            organ.label: tuple(float(value) for value in points_to_stage([organ.attachment])[0])
            for organ in plant.organs
            if organ.label.startswith("SubStem_") and organ.attachment is not None
        }
        runtimes.append(
            VineRuntime(
                name=static_prim.GetName(),
                source=source,
                root_path=root_path,
                plant=plant,
                skeletons=skeletons,
                rig=rig,
                clips=clips,
                severer=cutting.Severer(stage, rig, skeletons, organ_indices),
                organ_indices=organ_indices,
                cut_sites=cut_sites,
                placement_m=tuple(float(value) for value in placement_centre),
            )
        )

    UsdGeom.Scope.Define(stage, Sdf.Path("/World/NeighbourSafety"))
    selected_paths = {str(prim.GetPath()) for prim in selected}
    safety_candidates = []
    for static_prim in static_vines:
        if str(static_prim.GetPath()) in selected_paths:
            continue
        placement = UsdGeom.Xformable(static_prim).ComputeLocalToWorldTransform(
            Usd.TimeCode.Default()
        )
        centre = np.asarray(placement.ExtractTranslation(), dtype=np.float64)
        distance = float(np.linalg.norm(centre[:2] - placement_centres[0][:2]))
        safety_candidates.append((distance, static_prim, placement))
    safety_candidates.sort(key=lambda item: item[0])
    for _, static_prim, placement in safety_candidates[: args.neighbor_safety_vines]:
        source = _source_for_placement(static_prim.GetName(), vine_sources)
        plant = organs.load_plant(source)
        skeletons = skeleton_module.skeletonise_plant(
            plant,
            segment_length=args.segment,
        )
        points_to_stage, _ = _placement_transforms(placement, vine_usd, Gf, np)
        safety_colliders.extend(
            vine_physics.author_safety_proxies(
                stage,
                plant,
                f"/World/NeighbourSafety/{static_prim.GetName()}",
                skeletons,
                points_to_stage,
                vine_name=static_prim.GetName(),
                visible=args.show_colliders,
            )
        )

    camera_path = _author_camera(stage, placement_centres[0], args, Gf, Sdf, UsdGeom)
    try:
        selected_target = episode.resolve_target(
            runtimes,
            vine_name=args.target_vine,
            organ_label=args.target_organ,
            seed=args.episode_seed,
        )
    except ValueError as exc:
        report.update(stage="failed", error=str(exc))
        _emit(report, args.report)
        app.close()
        return 1
    selected_runtime = next(
        runtime for runtime in runtimes if runtime.name == selected_target.vine_name
    )

    planning_foliage_clearance_m = _MINIMUM_FOLIAGE_CLEARANCE_M

    def target_conditioned_base_plan(
        nominal_position_m,
        lateral_offsets_m,
        diagnostics,
        gripper_geometry=None,
        advances_m=(0.0,),
        candidates_override=None,
        advance_direction_xy=None,
    ):
        planning_model = robot_kinematics.Rby1Kinematics()
        multi_target_planning = bool(
            candidates_override is not None
            and len(candidates_override) > 1
        )
        camera_centre_m, camera_radius_m = robot_hardware.wrist_d405_body_sphere(side="left")
        payload_boxes = [
            ("wrist_d405", *robot_hardware.wrist_d405_body_box(side="left")),
            (
                "wrist_camera_bracket",
                *robot_hardware.wrist_camera_bracket_box(side="left"),
            ),
        ]
        planning_gripper_geometry = (
            _LEFT_GRIPPER_PLANNING_GEOMETRY
            if gripper_geometry is None
            else gripper_geometry
        )
        planning_gripper_payload = (
            (
                "ee_left",
                planning_gripper_geometry.get("palm")
                or _LEFT_GRIPPER_PLANNING_GEOMETRY["palm"],
            ),
            *((planning_gripper_geometry.get("fingers") or {}).items()),
        )
        for name, geometry in planning_gripper_payload:
            minimum = np.asarray(
                geometry["collider_min_ee_m"], dtype=np.float64
            )
            maximum = np.asarray(
                geometry["collider_max_ee_m"], dtype=np.float64
            )
            payload_boxes.append(
                (
                    name,
                    0.5 * (minimum + maximum),
                    np.eye(3, dtype=np.float64),
                    0.5 * (maximum - minimum),
                )
            )
        right_camera_box = robot_hardware.wrist_d405_body_box(side="right")
        right_bracket_box = robot_hardware.wrist_camera_bracket_box(
            side="right"
        )
        knife_centre, knife_half_extents = robot_hardware.knife_blade_box()
        right_payload_boxes = [
            ("wrist_d405", *right_camera_box),
            ("wrist_camera_bracket", *right_bracket_box),
            (
                "knife_blade",
                robot_hardware.KNIFE_TRANSLATION_M
                + robot_hardware.KNIFE_ROTATION @ knife_centre,
                robot_hardware.KNIFE_ROTATION,
                knife_half_extents,
            ),
        ]
        right_payload_boxes.extend(
            (
                f"knife_support_{index:02d}",
                robot_hardware.KNIFE_TRANSLATION_M
                + robot_hardware.KNIFE_ROTATION @ support_centre,
                robot_hardware.KNIFE_ROTATION,
                support_half_extents,
            )
            for index, (support_centre, support_half_extents) in enumerate(
                robot_hardware.knife_support_boxes()
            )
        )
        planning_vine_obstacles = _vine_capsule_obstacles(
            stage, robot_kinematics
        )
        planning_foliage_obstacles = _VineFoliageBoxObstacleCache(
            stage,
            robot_kinematics,
        ).snapshot()
        right_endpoint_foliage_clearance_m = (
            planning_foliage_clearance_m
            + _RIGHT_ROUTE_EXECUTION_FOLIAGE_BUFFER_M
        )
        exhaustive_base_planning = args.base_planning_budget == "exhaustive"
        expanded_endpoint_search_enabled = (
            _right_expanded_endpoint_search_enabled(
                exhaustive_base_planning=exhaustive_base_planning,
                multi_target_planning=multi_target_planning,
            )
        )
        expanded_endpoint_roll_candidates = (
            _right_expanded_endpoint_roll_candidates(
                args.right_base_endpoint_roll
            )
        )
        right_endpoint_screen_kwargs = {}
        if not exhaustive_base_planning:
            right_endpoint_screen_kwargs["side_candidates_m"] = (
                _RIGHT_ONLINE_BASE_ENDPOINT_SIDE_CANDIDATES_M
            )
        if args.right_base_endpoint_roll is not None:
            right_endpoint_screen_kwargs["roll_candidates"] = tuple(
                args.right_base_endpoint_roll
            )
        elif not exhaustive_base_planning:
            right_endpoint_screen_kwargs["roll_candidates"] = (
                _RIGHT_ONLINE_BASE_ENDPOINT_ROLLS_DEGREES
            )
        bimanual_endpoint_check = None
        bimanual_position_check = None
        right_endpoint_executor = None
        if args.bimanual_probe is not None or args.rl_server:
            from concurrent.futures import ProcessPoolExecutor
            import multiprocessing

            right_endpoint_executor = ProcessPoolExecutor(
                max_workers=12,
                mp_context=multiprocessing.get_context('spawn'),
                initializer=_initialize_right_endpoint_worker,
            )
            right_endpoint_cache = {}
            right_expanded_endpoint_cache = {}
            right_only_continuation_cache = {}
            left_pretension_cache = {}
            collider_targets = {
                info.path: (runtime, info.organ_label)
                for runtime in runtimes
                for info in runtime.rig.colliders
            }

            def planning_target_cut_path(runtime, organ_label, stub_m):
                cut_path = _authored_target_cut_path(
                    runtime, organ_label, stub_m
                )
                organ_index = runtime.organ_indices[organ_label]
                orphan_organs = {
                    organ_index,
                    *runtime.plant.descendants_of(organ_index),
                }
                orphan_bodies = tuple(
                    link.path
                    for link in runtime.rig.links
                    if link.organ in orphan_organs
                )
                return _right_protected_transverse_cut_geometry(
                    cut_path,
                    planning_vine_obstacles,
                    excluded_obstacle_paths=orphan_bodies,
                )

            def target_endpoint_screen(runtime, organ_label, base):
                cut_path = planning_target_cut_path(
                    runtime, organ_label, _RIGHT_CUT_STUB_M
                )
                base = np.asarray(base, dtype=np.float64)
                forward = base[:3, 0].copy()
                forward /= np.linalg.norm(forward)
                preferred = (
                    np.cos(np.radians(15.0)) * forward
                    + np.sin(np.radians(15.0))
                    * np.asarray([0.0, 0.0, 1.0])
                )
                cache_key = (
                    runtime.name,
                    organ_label,
                    round(_RIGHT_CUT_STUB_M, 6),
                    *tuple(
                        float(value)
                        for value in np.round(cut_path["point_m"], 9)
                    ),
                    *tuple(
                        float(value)
                        for value in np.round(base[:3, 3], 9)
                    ),
                )
                cached = cache_key in right_endpoint_cache
                if not cached:
                    right_endpoint_cache[cache_key] = (
                        _right_reachable_approach_endpoint_ik_screen(
                            planning_model,
                            process_executor=right_endpoint_executor,
                            base_matrix=base,
                            cut_point_m=cut_path['point_m'],
                            cut_axis=cut_path['axis'],
                            preferred_cut_direction=preferred,
                            seeds=(
                                _RIGHT_SAFE_DEGREES,
                                *_RIGHT_MULTISTART_SEEDS_DEGREES,
                            ),
                            stop_at_first_success_batch=False,
                            **right_endpoint_screen_kwargs,
                        )
                    )
                    endpoint_screen = right_endpoint_cache[cache_key]
                    report.setdefault(
                        'bimanual_base_endpoint_screens', []
                    ).append(
                        {
                            'target': f'{runtime.name}/{organ_label}',
                            'base_position_m': base[:3, 3].tolist(),
                            'cut_stub_m': _RIGHT_CUT_STUB_M,
                            'feasible': bool(
                                endpoint_screen['feasible']
                            ),
                            'selected': endpoint_screen.get('selected'),
                            'best': endpoint_screen.get('best'),
                            'attempt_count': int(
                                endpoint_screen['attempt_count']
                            ),
                            'reach_precheck_rejections': int(
                                endpoint_screen[
                                    'reach_precheck_rejections'
                                ]
                            ),
                            'minimum_shoulder_distance_m': (
                                endpoint_screen[
                                    'minimum_shoulder_distance_m'
                                ]
                            ),
                            'maximum_endpoint_reach_m': (
                                endpoint_screen[
                                    'maximum_endpoint_reach_m'
                                ]
                            ),
                        }
                    )
                    _emit(report, args.report)
                screen = dict(right_endpoint_cache[cache_key])
                screen.update(
                    target=f'{runtime.name}/{organ_label}',
                    cut_stub_m=_RIGHT_CUT_STUB_M,
                    cut_collider=cut_path['collider'],
                    cut_segment=cut_path['segment'],
                    cut_transverse_offset_m=cut_path[
                        'transverse_offset_m'
                    ].tolist(),
                    cut_transverse_offset_reference=cut_path[
                        'transverse_offset_reference'
                    ],
                    cached_endpoint_ik=cached,
                )
                return screen

            def bimanual_position_check(**payload):
                base = np.asarray(
                    payload['base_matrix'], dtype=np.float64
                )
                target_records = []
                target_record_by_key = {}
                for candidate in payload['candidates']:
                    identity = collider_targets.get(candidate.collider)
                    if identity is None:
                        continue
                    target_key = (identity[0].name, identity[1])
                    record = target_record_by_key.get(target_key)
                    if record is None:
                        record = {
                            'identity': identity,
                            'candidate_colliders': [],
                        }
                        target_record_by_key[target_key] = record
                        target_records.append(record)
                    record['candidate_colliders'].append(candidate.collider)
                if not target_records:
                    target_records.append(
                        {
                            'identity': (
                                selected_runtime,
                                selected_target.organ_label,
                            ),
                            'candidate_colliders': [
                                candidate.collider
                                for candidate in payload['candidates']
                            ],
                        }
                    )
                screens = []
                feasible_screens = []
                eligible_candidate_colliders = []
                for target_record in target_records:
                    runtime, organ_label = target_record['identity']
                    screen = target_endpoint_screen(
                        runtime, organ_label, base
                    )
                    screens.append(screen)
                    if screen['feasible']:
                        feasible_screens.append(screen)
                        eligible_candidate_colliders.extend(
                            target_record['candidate_colliders']
                        )
                if feasible_screens:
                    selected_screen = dict(feasible_screens[0])
                    selected_screen.update(
                        eligible_candidate_colliders=(
                            eligible_candidate_colliders
                        ),
                        feasible_target_count=len(feasible_screens),
                        target_count=len(screens),
                    )
                    return selected_screen
                if len(screens) == 1:
                    return screens[0]
                return {
                    'feasible': False,
                    'mode': 'right_outer_knife_endpoint_ik_any_target',
                    'target_count': len(screens),
                    'targets': [
                        {
                            'target': screen['target'],
                            'attempt_count': screen['attempt_count'],
                            'reach_precheck_rejections': screen[
                                'reach_precheck_rejections'
                            ],
                            'minimum_shoulder_distance_m': screen[
                                'minimum_shoulder_distance_m'
                            ],
                            'maximum_endpoint_reach_m': screen[
                                'maximum_endpoint_reach_m'
                            ],
                        }
                        for screen in screens
                    ],
                }

            def bimanual_endpoint_check(**payload):
                target_identity = collider_targets.get(
                    payload["candidate"].collider
                )
                if target_identity is None:
                    return {
                        "feasible": False,
                        "mode": "right_outer_knife_endpoint_ik",
                        "reason": "grasp collider has no target identity",
                    }
                runtime, organ_label = target_identity
                cut_stub_m = float(
                    payload.get("_cut_stub_m", _RIGHT_CUT_STUB_M)
                )
                cut_path = planning_target_cut_path(
                    runtime, organ_label, cut_stub_m
                )
                base = np.asarray(
                    payload["base_matrix"], dtype=np.float64
                )
                forward = base[:3, 0].copy()
                forward /= np.linalg.norm(forward)
                preferred = (
                    np.cos(np.radians(15.0)) * forward
                    + np.sin(np.radians(15.0))
                    * np.asarray([0.0, 0.0, 1.0])
                )
                cache_key = (
                    runtime.name,
                    organ_label,
                    round(cut_stub_m, 6),
                    *tuple(
                        float(value)
                        for value in np.round(cut_path["point_m"], 9)
                    ),
                    *tuple(
                        float(value)
                        for value in np.round(base[:3, 3], 9)
                    ),
                )
                cached = cache_key in right_endpoint_cache
                if not cached:
                    right_endpoint_cache[cache_key] = (
                        _right_reachable_approach_endpoint_ik_screen(
                            planning_model,
                            process_executor=right_endpoint_executor,
                            base_matrix=base,
                            cut_point_m=cut_path["point_m"],
                            cut_axis=cut_path["axis"],
                            preferred_cut_direction=preferred,
                            seeds=(
                                _RIGHT_SAFE_DEGREES,
                                *_RIGHT_MULTISTART_SEEDS_DEGREES,
                            ),
                            stop_at_first_success_batch=False,
                            **right_endpoint_screen_kwargs,
                        )
                    )
                    endpoint_screen = right_endpoint_cache[cache_key]
                    report.setdefault(
                        'bimanual_base_endpoint_screens', []
                    ).append(
                        {
                            'target': f'{runtime.name}/{organ_label}',
                            'base_position_m': base[:3, 3].tolist(),
                            'cut_stub_m': cut_stub_m,
                            'feasible': bool(
                                endpoint_screen['feasible']
                            ),
                            'selected': endpoint_screen.get('selected'),
                            'best': endpoint_screen.get('best'),
                            'attempt_count': int(
                                endpoint_screen['attempt_count']
                            ),
                        }
                    )
                    _emit(report, args.report)
                screen = dict(right_endpoint_cache[cache_key])
                screen.update(
                    target=f"{runtime.name}/{organ_label}",
                    cut_stub_m=cut_stub_m,
                    cut_collider=cut_path["collider"],
                    cut_segment=cut_path["segment"],
                    cut_transverse_offset_m=cut_path[
                        "transverse_offset_m"
                    ].tolist(),
                    cut_transverse_offset_reference=cut_path[
                        "transverse_offset_reference"
                    ],
                    cached_endpoint_ik=cached,
                )
                if screen["feasible"]:
                    planning_hold_rotation = _knife_rotation_for_roll(
                        cut_path["axis"],
                        preferred,
                        screen["selected"]["roll_degrees"],
                        robot_hardware,
                    )
                    planning_hold_direction = (
                        planning_hold_rotation
                        @ robot_hardware.KNIFE_CUT_DIRECTION_LOCAL
                    )
                    planning_required_cut_force_n = float(args.cut_force)
                    planning_hold_capacity = (
                        planning_model.point_force_capacity(
                            "left",
                            payload["left_solution"].joint_degrees,
                            base,
                            _LEFT_JAW_CENTRE_M,
                            planning_hold_direction,
                            planning_required_cut_force_n,
                            _RBY1_ARM_EFFORT_LIMITS_NM,
                        )
                    )
                    planning_minimum_hold_capacity_n = (
                        _minimum_left_counterhold_capacity_n(
                            planning_required_cut_force_n
                        )
                    )
                    planning_hold_joint_margin_degrees = (
                        planning_model.arm_joint_limit_margin_degrees(
                            "left",
                            payload["left_solution"].joint_degrees,
                        )
                    )
                    planning_hold_clear = (
                        _left_counterhold_posture_acceptable(
                            planning_hold_capacity.force_capacity_n,
                            planning_minimum_hold_capacity_n,
                            planning_hold_joint_margin_degrees,
                        )
                    )
                    screen.update(
                        left_counterhold_capacity=dataclasses.asdict(
                            planning_hold_capacity
                        ),
                        minimum_left_counterhold_capacity_n=(
                            planning_minimum_hold_capacity_n
                        ),
                        left_counterhold_joint_limit_margin_degrees=(
                            planning_hold_joint_margin_degrees
                        ),
                        minimum_left_counterhold_joint_limit_margin_degrees=(
                            _LEFT_COUNTERHOLD_MINIMUM_JOINT_LIMIT_MARGIN_DEGREES
                        ),
                        left_counterhold_clear=planning_hold_clear,
                        left_counterhold_capacity_pose="unloaded_grasp_telemetry_only",
                    )
                if screen["feasible"]:
                    pretension_pull_m = (
                        _LEFT_PRETENSION_PULL_M
                        if args.left_pretension_pull is None
                        else float(args.left_pretension_pull)
                    )
                    pretension_cache_key = (
                        runtime.name,
                        organ_label,
                        payload["candidate"].collider,
                        round(pretension_pull_m, 6),
                        *tuple(
                            float(value)
                            for value in np.round(base[:3, 3], 9)
                        ),
                        *tuple(
                            round(float(value), 6)
                            for value in payload[
                                "left_solution"
                            ].joint_degrees
                        ),
                    )
                    pretension_cached = (
                        pretension_cache_key in left_pretension_cache
                    )
                    organ_index = runtime.organ_indices[organ_label]
                    orphan_organs = set(
                        runtime.plant.descendants_of(organ_index)
                    )
                    orphan_bodies = tuple(
                        link.path
                        for link in runtime.rig.links
                        if link.organ in orphan_organs
                    )
                    pretension_foliage_obstacles = tuple(
                        obstacle
                        for obstacle in planning_foliage_obstacles
                        if not any(
                            obstacle.path == body
                            or obstacle.path.startswith(f"{body}/")
                            for body in orphan_bodies
                        )
                    )

                    def screen_left_pretension(left_target_degrees):
                        clearances = base_planner._sample_grasp_trajectory(
                            planning_model,
                            start_degrees=payload[
                                "left_solution"
                            ].joint_degrees,
                            waypoint_degrees=(),
                            target_degrees=left_target_degrees,
                            base_matrix=base,
                            obstacles=planning_vine_obstacles,
                            foliage_obstacles=(
                                pretension_foliage_obstacles
                            ),
                            camera_local_centre_m=camera_centre_m,
                            camera_radius_m=camera_radius_m,
                            payload_boxes=payload_boxes,
                            excluded_finger_colliders=payload[
                                "candidate"
                            ].excluded_finger_colliders,
                            right_waiting_degrees=_RIGHT_SAFE_DEGREES,
                            samples=31,
                        )
                        names = (
                            "arm",
                            "camera",
                            "payload",
                            "inter_arm",
                            "arm_foliage",
                            "camera_foliage",
                            "payload_foliage",
                        )
                        records = {
                            name: {
                                "clearance_m": float(result.clearance_m),
                                "nearest_obstacle": (
                                    result.nearest_obstacle
                                ),
                            }
                            for name, result in zip(names, clearances)
                        }
                        minimum = min(
                            record["clearance_m"]
                            for record in records.values()
                        )
                        records.update(
                            feasible=bool(
                                records["arm"]["clearance_m"] >= 0.005
                                and records["camera"]["clearance_m"]
                                >= _MINIMUM_WRIST_CAMERA_CLEARANCE_M
                                and records["payload"]["clearance_m"]
                                >= _MINIMUM_WRIST_CAMERA_CLEARANCE_M
                                and records["inter_arm"]["clearance_m"]
                                >= 0.05
                                and all(
                                    records[name]["clearance_m"]
                                    >= planning_foliage_clearance_m
                                    for name in (
                                        "arm_foliage",
                                        "camera_foliage",
                                        "payload_foliage",
                                    )
                                )
                            ),
                            minimum_clearance_m=float(minimum),
                        )
                        return records

                    def screen_left_counterhold_posture(left_target_degrees):
                        capacity = planning_model.point_force_capacity(
                            "left",
                            left_target_degrees,
                            base,
                            _LEFT_JAW_CENTRE_M,
                            planning_hold_direction,
                            planning_required_cut_force_n,
                            _RBY1_ARM_EFFORT_LIMITS_NM,
                        )
                        joint_margin_degrees = (
                            planning_model.arm_joint_limit_margin_degrees(
                                "left", left_target_degrees
                            )
                        )
                        return {
                            "feasible": (
                                _left_counterhold_posture_acceptable(
                                    capacity.force_capacity_n,
                                    planning_minimum_hold_capacity_n,
                                    joint_margin_degrees,
                                )
                            ),
                            "capacity": dataclasses.asdict(capacity),
                            "minimum_capacity_n": (
                                planning_minimum_hold_capacity_n
                            ),
                            "joint_limit_margin_degrees": (
                                joint_margin_degrees
                            ),
                            "minimum_joint_limit_margin_degrees": (
                                _LEFT_COUNTERHOLD_MINIMUM_JOINT_LIMIT_MARGIN_DEGREES
                            ),
                        }

                    if not pretension_cached:
                        left_pretension_cache[pretension_cache_key] = (
                            _planning_left_pretension_candidates(
                                planning_model,
                                base_matrix=base,
                                left_degrees=payload[
                                    "left_solution"
                                ].joint_degrees,
                                petiole_axis=payload["candidate"].axis,
                                trajectory_screen=(
                                    screen_left_pretension
                                ),
                                posture_screen=(
                                    screen_left_counterhold_posture
                                ),
                                seeds=(
                                    _LEFT_APPROACH_SEEDS_DEGREES[0.0],
                                    *_LEFT_MULTISTART_SEEDS_DEGREES,
                                ),
                                maximum_initial_pull_m=(
                                    pretension_pull_m
                                ),
                            )
                        )
                        pretension_result = left_pretension_cache[
                            pretension_cache_key
                        ]
                        report.setdefault(
                            "bimanual_base_left_pretension_screens", []
                        ).append(
                            {
                                "target": (
                                    f"{runtime.name}/{organ_label}"
                                ),
                                "grasp_collider": payload[
                                    "candidate"
                                ].collider,
                                "base_position_m": (
                                    base[:3, 3].tolist()
                                ),
                                "feasible": bool(
                                    pretension_result["feasible"]
                                ),
                                "mode": pretension_result["mode"],
                                "maximum_initial_pull_m": (
                                    pretension_pull_m
                                ),
                                "initial_distance_m": (
                                    pretension_result[
                                        "initial_distance_m"
                                    ]
                                ),
                                "additional_distance_m": (
                                    pretension_result[
                                        "additional_distance_m"
                                    ]
                                ),
                                "total_distance_m": (
                                    pretension_result[
                                        "total_distance_m"
                                    ]
                                ),
                                "candidate_count": len(
                                    pretension_result["candidates"]
                                ),
                                "attempt_count": len(
                                    pretension_result["attempts"]
                                ),
                            }
                        )
                        _emit(report, args.report)
                    pretension_result = left_pretension_cache[
                        pretension_cache_key
                    ]
                    screen["left_pretension"] = {
                        "cached": pretension_cached,
                        "feasible": bool(
                            pretension_result["feasible"]
                        ),
                        "mode": pretension_result["mode"],
                        "initial_distance_m": pretension_result[
                            "initial_distance_m"
                        ],
                        "additional_distance_m": pretension_result[
                            "additional_distance_m"
                        ],
                        "total_distance_m": pretension_result[
                            "total_distance_m"
                        ],
                        "candidate_count": len(
                            pretension_result["candidates"]
                        ),
                        "attempt_count": len(
                            pretension_result["attempts"]
                        ),
                    }
                    left_hold_candidates = tuple(
                        pretension_result["candidates"]
                    )
                    if not left_hold_candidates:
                        left_hold_candidates = (
                            {
                                "mode": "stationary_counterhold",
                                "initial_distance_m": 0.0,
                                "additional_distance_m": 0.0,
                                "total_distance_m": 0.0,
                                "seed_index": None,
                                "solution": dataclasses.asdict(
                                    payload["left_solution"]
                                ),
                                "posture": (
                                    screen_left_counterhold_posture(
                                        payload["left_solution"].joint_degrees
                                    )
                                ),
                                "trajectory": {
                                    "feasible": True,
                                    "reason": (
                                        "all_nonzero_pull_routes_obstructed"
                                    ),
                                },
                                "acceptable_ik": True,
                                "feasible": True,
                            },
                        )

                    selected_left_hold = left_hold_candidates[0]
                    screen["left_pretension"]["force_screens"] = [
                        candidate["posture"]
                        for candidate in left_hold_candidates
                    ]
                    if not selected_left_hold["posture"]["feasible"]:
                        screen["left_pretension"]["selected"] = None
                        screen.update(
                            feasible=False,
                            reason=(
                                "loaded left counterhold cannot react the "
                                "full force-gated blade load"
                            ),
                            prune_candidate=False,
                        )
                        return screen
                    screen["left_pretension"]["selected"] = {
                        "mode": selected_left_hold["mode"],
                        "initial_distance_m": selected_left_hold[
                            "initial_distance_m"
                        ],
                        "additional_distance_m": selected_left_hold[
                            "additional_distance_m"
                        ],
                        "total_distance_m": selected_left_hold[
                            "total_distance_m"
                        ],
                        "seed_index": selected_left_hold["seed_index"],
                        "joint_degrees": selected_left_hold["solution"][
                            "joint_degrees"
                        ],
                        "force_screen": selected_left_hold["posture"],
                    }

                    target_colliders = tuple(
                        info.path
                        for info in runtime.rig.colliders
                        if info.organ_label == organ_label
                    )
                    clearance_candidates = []
                    assessed_attempt_keys = set()

                    def assess_endpoint_attempt(attempt):
                        solution = attempt["solution"]
                        if not solution["succeeded"]:
                            return False
                        attempt_key = (
                            float(attempt["roll_degrees"]),
                            tuple(
                                float(value)
                                for value in attempt["edge_wing_local_m"]
                            ),
                            tuple(
                                round(float(value), 6)
                                for value in solution["joint_degrees"]
                            ),
                        )
                        if attempt_key in assessed_attempt_keys:
                            return False
                        assessed_attempt_keys.add(attempt_key)
                        clearance = _right_endpoint_clearance_screen(
                            planning_model,
                            right_degrees=solution["joint_degrees"],
                            left_degrees=payload[
                                "left_solution"
                            ].joint_degrees,
                            base_matrix=base,
                            obstacles=planning_vine_obstacles,
                            foliage_obstacles=(
                                planning_foliage_obstacles
                            ),
                            payload_boxes=right_payload_boxes,
                            excluded_blade_colliders=target_colliders,
                            # The pre-grasp flat-blade frame intentionally
                            # pins wrist joint 6 at its authored orientation
                            # stop for every base candidate. The live target
                            # moves after physical capture; enforce the full
                            # 0.5-degree reserve in solve_right(), while this
                            # static gate ranks complete geometry only.
                            minimum_joint_limit_margin_degrees=0.0,
                            minimum_arm_clearance_m=0.005,
                            minimum_payload_clearance_m=(
                                _RIGHT_PLANNING_PAYLOAD_CLEARANCE_M
                            ),
                            minimum_foliage_clearance_m=(
                                right_endpoint_foliage_clearance_m
                            ),
                            minimum_inter_arm_clearance_m=0.05,
                        )

                        if _right_clearance_has_left_independent_failure(
                            clearance
                        ):
                            right_only = {
                                "feasible": False,
                                "start_side_m": float(screen["side_m"]),
                                "final_side_m": None,
                                "waypoints": [],
                                "reason": (
                                    "outer endpoint lost right-only "
                                    "collision reserve"
                                ),
                            }
                        else:
                            right_only_key = (
                                cache_key,
                                attempt_key,
                            )
                            right_only_cached = (
                                right_only_continuation_cache.get(
                                    right_only_key
                                )
                            )
                            if right_only_cached is None:
                                print(
                                    "[base-planner] screening right endpoint "
                                    f"attempt {len(assessed_attempt_keys)} "
                                    "right-only",
                                    flush=True,
                                )
                            right_only = (
                                right_only_cached
                                or _right_only_cut_continuation_screen(
                                planning_model,
                                base_matrix=base,
                                cut_point_m=cut_path["point_m"],
                                cut_axis=cut_path["axis"],
                                preferred_cut_direction=preferred,
                                start_side_m=screen["side_m"],
                                start_attempt=attempt,
                                obstacles=planning_vine_obstacles,
                                foliage_obstacles=(
                                    planning_foliage_obstacles
                                ),
                                payload_boxes=right_payload_boxes,
                                excluded_blade_colliders=target_colliders,
                                seeds=(
                                    _RIGHT_SAFE_DEGREES,
                                    *_RIGHT_MULTISTART_SEEDS_DEGREES,
                                ),
                                process_executor=right_endpoint_executor,
                                stop_side_m=(
                                    _RIGHT_COMMITTED_CUT_EXIT_SIDE_M
                                ),
                                minimum_joint_limit_margin_degrees=0.0,
                                minimum_arm_clearance_m=max(
                                    0.005,
                                    _RIGHT_COMMITTED_CUT_LIVE_REPLAN_GUARD_M,
                                ),
                                minimum_payload_clearance_m=(
                                    _RIGHT_PLANNING_PAYLOAD_CLEARANCE_M
                                ),
                                committed_minimum_payload_clearance_m=(
                                    _RIGHT_COMMITTED_CUT_PLANNING_CLEARANCE_M
                                ),
                                minimum_foliage_clearance_m=(
                                    right_endpoint_foliage_clearance_m
                                ),
                            )
                            )
                            right_only_continuation_cache[
                                right_only_key
                            ] = right_only

                        def screen_continuation(left_hold):
                            return _right_local_cut_continuation_screen(
                                planning_model,
                                base_matrix=base,
                                cut_point_m=cut_path["point_m"],
                                cut_axis=cut_path["axis"],
                                preferred_cut_direction=preferred,
                                start_side_m=screen["side_m"],
                                start_attempt=attempt,
                                left_degrees=left_hold["solution"][
                                    "joint_degrees"
                                ],
                                obstacles=planning_vine_obstacles,
                                foliage_obstacles=(
                                    planning_foliage_obstacles
                                ),
                                payload_boxes=right_payload_boxes,
                                excluded_blade_colliders=(
                                    target_colliders
                                ),
                                seeds=(
                                    _RIGHT_SAFE_DEGREES,
                                    *_RIGHT_MULTISTART_SEEDS_DEGREES,
                                ),
                                process_executor=right_endpoint_executor,
                                stop_side_m=(
                                    _RIGHT_COMMITTED_CUT_EXIT_SIDE_M
                                ),
                                minimum_joint_limit_margin_degrees=0.0,
                                minimum_arm_clearance_m=max(
                                    0.005,
                                    _RIGHT_COMMITTED_CUT_LIVE_REPLAN_GUARD_M,
                                ),
                                minimum_payload_clearance_m=(
                                    _RIGHT_PLANNING_PAYLOAD_CLEARANCE_M
                                ),
                                committed_minimum_payload_clearance_m=(
                                    _RIGHT_COMMITTED_CUT_PLANNING_CLEARANCE_M
                                ),
                                minimum_foliage_clearance_m=(
                                    right_endpoint_foliage_clearance_m
                                ),
                                minimum_inter_arm_clearance_m=0.05,
                            )

                        if clearance["endpoint_feasible"] and right_only["feasible"]:
                            continuation_candidates = []
                            for left_hold in left_hold_candidates:
                                continuation_candidate = (
                                    screen_continuation(left_hold)
                                )
                                continuation_candidate["left_hold"] = {
                                    "mode": left_hold["mode"],
                                    "initial_distance_m": left_hold[
                                        "initial_distance_m"
                                    ],
                                    "additional_distance_m": left_hold[
                                        "additional_distance_m"
                                    ],
                                    "total_distance_m": left_hold[
                                        "total_distance_m"
                                    ],
                                    "seed_index": left_hold["seed_index"],
                                    "joint_degrees": left_hold["solution"][
                                        "joint_degrees"
                                    ],
                                }
                                continuation_candidates.append(
                                    continuation_candidate
                                )
                                if continuation_candidate["feasible"]:
                                    break
                                # A right-side crop/chord rejection cannot be
                                # improved by auditing another left-arm hold.
                                if (
                                    _right_continuation_failure_is_left_independent(
                                        continuation_candidate
                                    )
                                ):
                                    break
                            continuation = max(
                                continuation_candidates,
                                key=lambda candidate: (
                                    bool(candidate["feasible"]),
                                    float(
                                        candidate["final_side_m"]
                                        if candidate["final_side_m"]
                                        is not None
                                        else float("-inf")
                                    ),
                                    len(candidate["waypoints"]),
                                ),
                            )
                            continuation["left_hold_attempts"] = [
                                {
                                    "left_hold": candidate["left_hold"],
                                    "feasible": bool(
                                        candidate["feasible"]
                                    ),
                                    "final_side_m": candidate[
                                        "final_side_m"
                                    ],
                                    "reason": candidate["reason"],
                                }
                                for candidate in continuation_candidates
                            ]
                            screen["left_pretension"]["selected"] = (
                                continuation["left_hold"]
                            )
                        else:
                            continuation = {
                                "feasible": False,
                                "start_side_m": float(screen["side_m"]),
                                "final_side_m": None,
                                "waypoints": [],
                                "reason": (
                                    "right-only cut corridor lost collision "
                                    "reserve"
                                    if not right_only["feasible"]
                                    else (
                                        "outer endpoint lost collision "
                                        "reserve"
                                    )
                                ),
                            }
                        clearance["continuation_feasible"] = bool(
                            continuation["feasible"]
                        )
                        clearance_candidates.append(
                            {
                                "attempt": attempt,
                                "clearance": clearance,
                                "continuation": continuation,
                                "right_only": right_only,
                            }
                        )
                        return _right_base_endpoint_route_feasible(
                            clearance
                        )

                    nominal_continuation_feasible = False
                    for attempt in screen.get("attempts") or (
                        screen["selected"],
                    ):
                        if assess_endpoint_attempt(attempt):
                            nominal_continuation_feasible = True
                            if not exhaustive_base_planning:
                                break

                    screen["multi_target_planning"] = multi_target_planning
                    screen["expanded_endpoint_search_enabled"] = (
                        expanded_endpoint_search_enabled
                    )
                    if (
                        not nominal_continuation_feasible
                        and expanded_endpoint_search_enabled
                    ):
                        expanded_cache_key = (
                            cache_key,
                            float(screen["side_m"]),
                            expanded_endpoint_roll_candidates,
                        )
                        expanded_cached = (
                            expanded_cache_key
                            in right_expanded_endpoint_cache
                        )
                        if not expanded_cached:
                            right_expanded_endpoint_cache[
                                expanded_cache_key
                            ] = _right_outer_endpoint_ik_screen(
                                planning_model,
                                process_executor=right_endpoint_executor,
                                base_matrix=base,
                                cut_point_m=cut_path["point_m"],
                                cut_axis=cut_path["axis"],
                                preferred_cut_direction=preferred,
                                seeds=(
                                    _RIGHT_SAFE_DEGREES,
                                    *_RIGHT_MULTISTART_SEEDS_DEGREES,
                                ),
                                side_m=float(screen["side_m"]),
                                stop_at_first_success_batch=False,
                                roll_candidates=expanded_endpoint_roll_candidates,
                            )
                        expanded_endpoint = (
                            right_expanded_endpoint_cache[
                                expanded_cache_key
                            ]
                        )
                        expanded_attempts = tuple(
                            expanded_endpoint.get("attempts") or ()
                        )
                        screen["expanded_endpoint_ik"] = {
                            "attempt_count": len(expanded_attempts),
                            "successful_attempt_count": sum(
                                int(
                                    attempt["solution"]["succeeded"]
                                )
                                for attempt in expanded_attempts
                            ),
                            "roll_candidates_degrees": list(
                                expanded_endpoint_roll_candidates
                            ),
                            "side_m": float(screen["side_m"]),
                            "cached": expanded_cached,
                        }
                        for attempt in expanded_attempts:
                            if assess_endpoint_attempt(attempt):
                                break
                    feasible_clearances = [
                        record
                        for record in clearance_candidates
                        if _right_base_endpoint_route_feasible(
                            record["clearance"]
                        )
                    ]
                    screen["endpoint_clearance_candidates"] = [
                        {
                            **record["attempt"],
                            "clearance": record["clearance"],
                            "continuation": record["continuation"],
                            "right_only_feasible": (
                                None
                                if record.get("right_only") is None
                                else bool(record["right_only"]["feasible"])
                            ),
                        }
                        for record in clearance_candidates
                    ]
                    screen["feasible"] = bool(feasible_clearances)
                    right_only_records = tuple(
                        record["right_only"]
                        for record in clearance_candidates
                        if record.get("right_only") is not None
                    )
                    screen["right_only_full_corridor_feasible"] = any(
                        bool(record["feasible"])
                        for record in right_only_records
                    )
                    if feasible_clearances:
                        selected_clearance = max(
                            feasible_clearances,
                            key=lambda record: min(
                                record["clearance"][
                                    "arm_clearance_m"
                                ]
                                - 0.005,
                                record["clearance"][
                                    "payload_clearance_m"
                                ]
                                - _RIGHT_PLANNING_PAYLOAD_CLEARANCE_M,
                                record["clearance"][
                                    "arm_foliage_clearance_m"
                                ]
                                - right_endpoint_foliage_clearance_m,
                                record["clearance"][
                                    "payload_foliage_clearance_m"
                                ]
                                - right_endpoint_foliage_clearance_m,
                                record["clearance"][
                                    "inter_arm_clearance_m"
                                ]
                                - 0.05,
                                record["clearance"][
                                    "joint_limit_margin_degrees"
                                ]
                                - _RIGHT_MINIMUM_APPROACH_JOINT_LIMIT_MARGIN_DEGREES,
                                record["clearance"][
                                    "route_minimum_arm"
                                ]["clearance_m"]
                                - 0.005,
                                record["clearance"][
                                    "route_minimum_payload"
                                ]["clearance_m"]
                                - _RIGHT_PLANNING_PAYLOAD_CLEARANCE_M,
                                record["clearance"][
                                    "route_minimum_arm_foliage"
                                ]["clearance_m"]
                                - right_endpoint_foliage_clearance_m,
                                record["clearance"][
                                    "route_minimum_payload_foliage"
                                ]["clearance_m"]
                                - right_endpoint_foliage_clearance_m,
                                record["clearance"][
                                    "route_minimum_inter_arm"
                                ]["clearance_m"]
                                - 0.05,
                            ),
                        )
                        screen["selected"] = selected_clearance[
                            "attempt"
                        ]
                        screen["selected_endpoint_clearance"] = (
                            selected_clearance["clearance"]
                        )
                        screen["selected_local_continuation"] = (
                            selected_clearance["continuation"]
                        )
                        screen.update(
                            endpoint_inter_arm_clearance_m=(
                                selected_clearance["clearance"][
                                    "inter_arm_clearance_m"
                                ]
                            ),
                            endpoint_inter_arm_nearest=(
                                selected_clearance["clearance"][
                                    "inter_arm_nearest"
                                ]
                            ),
                        )
                    else:
                        screen["reason"] = (
                            "right endpoint has no collision-audited local "
                            "continuation through the counterhold boundary "
                            "with arm, payload, foliage, and inter-arm reserve"
                        )
                        screen["prune_candidate"] = bool(
                            clearance_candidates
                            and len(right_only_records)
                            == len(clearance_candidates)
                            and not screen[
                                "right_only_full_corridor_feasible"
                            ]
                        )
                if not bool(screen.get("feasible", False)):
                    screen["prune_candidate"] = (
                        bool(screen.get("prune_candidate", False))
                        or _right_endpoint_failure_is_left_independent(screen)
                    )
                continuation_diagnostics = []
                for record in screen.get(
                    "endpoint_clearance_candidates", ()
                ):
                    continuation = record.get("continuation") or {}
                    waypoints = continuation.get("waypoints") or ()
                    failed_waypoint = waypoints[-1] if waypoints else {}
                    failed_clearance = (
                        failed_waypoint.get("clearance") or {}
                    )
                    continuation_diagnostics.append(
                        {
                            "roll_degrees": record.get("roll_degrees"),
                            "edge_wing_local_m": record.get(
                                "edge_wing_local_m"
                            ),
                            "outer_endpoint_feasible": record.get(
                                "clearance", {}
                            ).get("endpoint_feasible"),
                            "outer_arm_clearance_m": record.get(
                                "clearance", {}
                            ).get("arm_clearance_m"),
                            "outer_payload_clearance_m": record.get(
                                "clearance", {}
                            ).get("payload_clearance_m"),
                            "outer_arm_foliage_clearance_m": record.get(
                                "clearance", {}
                            ).get("arm_foliage_clearance_m"),
                            "outer_payload_foliage_clearance_m": record.get(
                                "clearance", {}
                            ).get("payload_foliage_clearance_m"),
                            "continuation_feasible": continuation.get(
                                "feasible"
                            ),
                            "continuation_reason": continuation.get("reason"),
                            "left_hold": continuation.get("left_hold"),
                            "left_hold_attempts": continuation.get(
                                "left_hold_attempts"
                            ),
                            "failure_side_m": failed_waypoint.get("side_m"),
                            "failure_endpoint_feasible": failed_clearance.get(
                                "endpoint_feasible"
                            ),
                            "failure_route_feasible": failed_clearance.get(
                                "route_feasible"
                            ),
                            "failure_route_first_rejection": (
                                failed_clearance.get("route_first_rejection")
                            ),
                            "failure_arm_nearest": failed_clearance.get(
                                "arm_nearest"
                            ),
                            "failure_payload_nearest": failed_clearance.get(
                                "payload_nearest"
                            ),
                            "failure_arm_foliage_nearest": (
                                failed_clearance.get("arm_foliage_nearest")
                            ),
                            "failure_payload_foliage_nearest": (
                                failed_clearance.get(
                                    "payload_foliage_nearest"
                                )
                            ),
                        }
                    )
                report.setdefault(
                    "bimanual_base_continuation_screens", []
                ).append(
                    {
                        "target": f"{runtime.name}/{organ_label}",
                        "cut_stub_m": cut_stub_m,
                        "base_position_m": base[:3, 3].tolist(),
                        "left_joint_degrees": list(
                            screen.get("left_pretension", {})
                            .get("selected", {})
                            .get(
                                "joint_degrees",
                                payload["left_solution"].joint_degrees,
                            )
                        ),
                        "unloaded_left_joint_degrees": list(
                            payload["left_solution"].joint_degrees
                        ),
                        "feasible": bool(screen.get("feasible", False)),
                        "reason": screen.get("reason"),
                        "multi_target_planning": bool(
                            screen.get("multi_target_planning", False)
                        ),
                        "expanded_endpoint_search_enabled": bool(
                            screen.get(
                                "expanded_endpoint_search_enabled", False
                            )
                        ),
                        "right_only_full_corridor_feasible": screen.get(
                            "right_only_full_corridor_feasible"
                        ),
                        "left_independent_failure": bool(
                            screen.get("prune_candidate", False)
                        ),
                        "candidates": continuation_diagnostics,
                    }
                )
                _emit(report, args.report)
                if (
                    not screen.get("feasible", False)
                    and "_cut_stub_m" not in payload
                    and exhaustive_base_planning
                ):
                    # Alternate stubs repeat the complete endpoint/continuation
                    # lattice. Keep them for explicit exhaustive certification;
                    # online planning first spends its bounded budget on local
                    # base offsets, while live execution retains stub recovery.
                    stub_search = []
                    for candidate_stub_m in _right_cut_stub_search_order(
                        _RIGHT_CUT_STUB_M,
                        _RIGHT_COMMITTED_CUT_STUB_CANDIDATES_M,
                    ):
                        if math.isclose(
                            candidate_stub_m,
                            _RIGHT_CUT_STUB_M,
                            abs_tol=1e-9,
                        ):
                            continue
                        candidate_payload = dict(payload)
                        candidate_payload["_cut_stub_m"] = candidate_stub_m
                        candidate_screen = bimanual_endpoint_check(
                            **candidate_payload
                        )
                        stub_search.append(
                            {
                                "cut_stub_m": candidate_stub_m,
                                "feasible": bool(
                                    candidate_screen.get("feasible", False)
                                ),
                                "reason": candidate_screen.get("reason"),
                            }
                        )
                        if candidate_screen.get("feasible", False):
                            candidate_screen["cut_stub_search"] = (
                                stub_search
                            )
                            return candidate_screen
                    screen["cut_stub_search"] = stub_search
                elif (
                    not screen.get("feasible", False)
                    and "_cut_stub_m" not in payload
                ):
                    screen["cut_stub_search_deferred"] = True
                return screen

        (
            joint_space_search_iterations,
            maximum_joint_space_route_searches,
        ) = _base_planning_joint_space_route_budget(exhaustive_base_planning)
        plan = base_planner.plan_target_conditioned_base(
            planning_model,
            nominal_position_m=nominal_position_m,
            yaw_degrees=args.robot_yaw,
            candidates=(
                _target_grasp_candidates(
                    stage,
                    selected_runtime,
                    selected_target.organ_label,
                    base_planner,
                    axial_offsets_m=args.left_grasp_axial_offset,
                )
                if candidates_override is None
                else tuple(candidates_override)
            ),
            obstacles=planning_vine_obstacles,
            foliage_obstacles=planning_foliage_obstacles,
            jaw_local_point_m=_LEFT_JAW_CENTRE_M,
            camera_local_centre_m=camera_centre_m,
            camera_radius_m=camera_radius_m,
            left_payload_boxes=tuple(payload_boxes),
            minimum_payload_clearance_m=0.005,
            seeds=(
                # Spend the bounded online route search on the force-capable
                # elbow-up branch before weaker endpoint-local minima consume
                # its three-search budget.
                *_LEFT_MULTISTART_SEEDS_DEGREES[1:],
                _LEFT_AISLE_CLEARANCE_WAYPOINTS_DEGREES[-1],
                _LEFT_APPROACH_SEEDS_DEGREES[0.0],
                _LEFT_MULTISTART_SEEDS_DEGREES[0],
            ),
            advances_m=advances_m,
            lateral_offsets_m=lateral_offsets_m,
            advance_direction_xy=advance_direction_xy,
            left_waiting_degrees=_LEFT_GREENHOUSE_WAITING_DEGREES,
            left_approach_start_degrees=_LEFT_GREENHOUSE_WAITING_DEGREES,
            left_approach_waypoint_routes=(
                _LEFT_COUNTERHOLD_APPROACH_WAYPOINTS_DEGREES,
                (),
                (_LEFT_APPROACH_SEEDS_DEGREES[0.10],),
                (_LEFT_APPROACH_SEEDS_DEGREES[0.06],),
                (_LEFT_APPROACH_SEEDS_DEGREES[0.04],),
                (_LEFT_APPROACH_SEEDS_DEGREES[0.02],),
                (_LEFT_MULTISTART_SEEDS_DEGREES[0],),
                tuple(
                    _LEFT_APPROACH_SEEDS_DEGREES[offset]
                    for offset in (0.10, 0.06, 0.04, 0.02)
                ),
            ),
            target_relative_ingress_offsets_m=(0.02, 0.04, 0.08, 0.12, 0.18),
            target_relative_ingress_gateways_m=(
                # Shallow-taper lanes passed pre-authoring and live-refresh
                # foliage screens for the strict SubStem_07 sequence.
                (0.28, 0.14, 0.0, 0.5),
                (0.28, 0.16, 0.0, 0.5),
                (0.28, 0.16, 0.0, 0.75),
                (0.28, 0.18, 0.0, 0.75),
                (0.18, 0.0, 0.12),
                (0.22, -0.10, 0.12),
                (0.22, 0.10, 0.12),
                (0.28, -0.14, 0.16),
                (0.28, 0.14, 0.16),
                (0.28, 0.16, 0.16),
                (0.28, 0.18, 0.16),
                (0.28, 0.20, 0.16),
                (0.28, 0.14, 0.0),
                (0.28, 0.16, 0.0),
                (0.28, 0.18, -0.05),
                (0.28, 0.18, 0.0),
                (0.28, 0.18, 0.05),
            ),
            right_waiting_degrees=_RIGHT_SAFE_DEGREES,
            reach_reserve_m=0.0,
            minimum_trajectory_clearance_m=0.005,
            minimum_foliage_clearance_m=planning_foliage_clearance_m,
            trajectory_samples=31,
            # Try live-screened preset ingress first. When it is blocked,
            # retain a deterministic episode-seeded RRT fallback online with
            # the bounded budget returned above.
            joint_space_search_iterations=joint_space_search_iterations,
            maximum_joint_space_route_searches=(
                maximum_joint_space_route_searches
            ),
            maximum_ik_evaluations=(
                5000 if exhaustive_base_planning else 250
            ),
            grasp_approach_yaw_offsets_degrees=(
                _LEFT_GRASP_APPROACH_YAW_OFFSETS_DEGREES
                if args.left_grasp_approach_yaw is None
                else tuple(args.left_grasp_approach_yaw)
            ),
            # The negative transverse branch physically reached SubStem_02's
            # jaw corridor in 20 servo steps without target-following.  The
            # positive branch remained collision-clear but pushed the compliant
            # petiole ahead of the open jaws.  Preserve both branches while
            # making the stable capture frame the deterministic online default.
            grasp_transverse_signs=(-1.0, 1.0),
            candidates_are_preferred=(candidates_override is not None),
            joint_space_search_seed=args.episode_seed,
            stop_on_first_feasible=not exhaustive_base_planning,
            position_feasibility_check=bimanual_position_check,
            endpoint_feasibility_check=bimanual_endpoint_check,
            minimum_inter_arm_clearance_m=0.05,
            diagnostics=diagnostics,
        )
        if right_endpoint_executor is not None:
            right_endpoint_executor.shutdown()
        return plan
    context = None
    if (
        not args.no_robot
        and args.robot_position_mode
        in {"target-conditioned", "planned-fixed"}
    ):
        # Let gravity and trellis constraints establish the plant geometry
        # before selecting or validating a parked base and arm route. Planning
        # either mode against the imported pose allowed leaves to sag 10--30 mm
        # into an otherwise clear endpoint during normal startup settling.
        from isaacsim.core.api import SimulationContext

        context = SimulationContext(
            physics_dt=1.0 / 240.0,
            rendering_dt=1.0 / 60.0,
            stage_units_in_meters=1.0,
        )
        context.initialize_physics()
        context.get_physics_context().set_gravity(-9.81)
        context.play()
        tracked_paths = [
            path
            for runtime in runtimes
            for path in _base_link_paths(runtime.rig)
        ]
        previous_positions = _positions(stage, tracked_paths)
        settle_window_steps = 120
        minimum_settle_steps = max(args.settle_steps, 240)
        planning_settle_horizon_steps = (
            max(minimum_settle_steps, 1800)
            if args.bimanual_probe is not None or args.rl_server
            else minimum_settle_steps
        )
        maximum_settle_steps = max(
            planning_settle_horizon_steps, 2880
        )
        # A damped live vine should retain bounded natural motion rather than
        # become numerically frozen. Require a repeatable <=2 mm half-second
        # sway envelope, then add that measured envelope to the immutable
        # 0.5 mm collision reserve used by every planning check.
        settle_tolerance_m = 0.002
        required_stable_windows = 3
        stable_windows = 0
        settle_history = []
        settle_steps = 0
        for settle_steps in range(1, maximum_settle_steps + 1):
            context.step(render=False)
            if settle_steps % settle_window_steps:
                continue
            current_positions = _positions(stage, tracked_paths)
            finite = bool(np.isfinite(current_positions).all())
            maximum_displacement_m = (
                float(
                    np.max(
                        np.linalg.norm(
                            current_positions - previous_positions,
                            axis=1,
                        )
                    )
                )
                if finite
                else float("inf")
            )
            stable_windows = (
                stable_windows + 1
                if (
                    finite
                    and settle_steps >= minimum_settle_steps
                    and maximum_displacement_m <= settle_tolerance_m
                )
                else 0
            )
            settle_history.append(
                {
                    "steps": settle_steps,
                    "maximum_window_displacement_mm": (
                        maximum_displacement_m * 1000.0
                    ),
                    "stable_windows": stable_windows,
                }
            )
            previous_positions = current_positions
            if (
                stable_windows >= required_stable_windows
                and settle_steps >= planning_settle_horizon_steps
            ):
                break
        # Pause rather than stop: stop restores authored rigid-body transforms
        # and silently discards the equilibrium geometry we need to plan
        # against. PhysX observes the subsequently authored robot prims while
        # the live vine scene remains paused.
        context.pause()
        measured_sway_m = (
            max(
                record["maximum_window_displacement_mm"]
                for record in settle_history[-required_stable_windows:]
            )
            * 0.001
            if stable_windows >= required_stable_windows
            else float("inf")
        )
        if np.isfinite(measured_sway_m):
            planning_foliage_clearance_m = (
                _MINIMUM_FOLIAGE_CLEARANCE_M + measured_sway_m
            )
        report["preplanning_vine_settle"] = {
            "enabled": True,
            "steps": settle_steps,
            "physics_dt_s": 1.0 / 240.0,
            "robot_authored": False,
            "state_preservation": "paused_live_physics_scene",
            "converged": stable_windows >= required_stable_windows,
            "window_steps": settle_window_steps,
            "minimum_planning_horizon_steps": (
                planning_settle_horizon_steps
            ),
            "tolerance_mm": settle_tolerance_m * 1000.0,
            "required_stable_windows": required_stable_windows,
            "measured_sway_envelope_mm": measured_sway_m * 1000.0,
            "planning_foliage_clearance_mm": (
                planning_foliage_clearance_m * 1000.0
            ),
            "history": settle_history,
        }
        if stable_windows < required_stable_windows:
            report.update(
                stage="failed",
                error=(
                    "vine physics did not enter bounded stationary sway before "
                    "target-conditioned planning"
                ),
            )
            _emit(report, args.report)
            context.stop()
            app.close()
            return 1
    greenhouse_structure_obstacles = ()
    greenhouse_wall_colliders = ()
    if not args.no_robot:
        target_reference = np.asarray(
            selected_runtime.cut_sites[selected_target.organ_label],
            dtype=np.float64,
        )
        aisle_reference = np.asarray(
            selected_runtime.placement_m,
            dtype=np.float64,
        )
        aisle_bounds = _approach_aisle_base_bounds(
            stage,
            aisle_reference,
            args.robot_yaw,
            Usd,
            UsdGeom,
            np,
        )
        requested_robot_position = (
            None
            if args.robot_position is None
            else tuple(float(value) for value in args.robot_position)
        )
        if args.robot_position is None:
            nominal_base_reference = (
                aisle_reference
                if "auto" in (args.target_vine, args.target_organ)
                else target_reference
            )
            args.robot_position = _default_robot_position(
                stage,
                nominal_base_reference,
                args.robot_yaw,
                Usd,
                UsdGeom,
                np,
                aisle_reference=aisle_reference,
            )
        elif not (
            aisle_bounds["minimum_base_y_m"]
            <= float(args.robot_position[1])
            <= aisle_bounds["maximum_base_y_m"]
        ):
            report.update(
                stage="failed",
                error="fixed robot position intersects the gutter or greenhouse wall",
                opposite_aisle=aisle_bounds,
            )
            _emit(report, args.report)
            app.close()
            return 1
        nominal_robot_position = tuple(float(value) for value in args.robot_position)
        base_depth_advances_m = (0.0,)
        requested_local_search = False
        if args.robot_position_mode in {
            "target-conditioned",
            "planned-fixed",
        }:
            # Search from a safely retreated aisle pose toward the crop row.
            # The previous single-depth search parked at y=4.800 m; a distal
            # grasp could be endpoint-clear there while its incoming D405 and
            # bracket chord intersected the main stem. Keep every sample
            # inside the measured aisle and retain the original near-row pose
            # as the final candidate.
            if args.robot_position_mode == "target-conditioned":
                requested_local_search = requested_robot_position is not None
                maximum_retreat_m = (
                    _LOCAL_REQUESTED_BASE_SEARCH_RADIUS_M
                    if requested_local_search
                    else 0.20
                )
                far_y_m = max(
                    float(aisle_bounds["minimum_base_y_m"]) + 0.05,
                    float(nominal_robot_position[1]) - maximum_retreat_m,
                )
                depth_span_m = float(nominal_robot_position[1]) - far_y_m
                nominal_robot_position = (
                    float(nominal_robot_position[0]),
                    far_y_m,
                    float(nominal_robot_position[2]),
                )
                maximum_advance_m = (
                    float(aisle_bounds["maximum_base_y_m"]) - far_y_m
                )
                if requested_local_search:
                    base_depth_advances_m = _local_requested_base_depth_advances(
                        depth_span_m,
                        maximum_advance_m,
                    )
                else:
                    base_depth_advances_m = tuple(
                        dict.fromkeys(
                            float(value)
                            for value in (
                                min(depth_span_m + 0.010, maximum_advance_m),
                                depth_span_m,
                                0.5 * depth_span_m,
                                min(0.03, depth_span_m),
                            )
                            if value >= 0.0
                        )
                    )
            base_diagnostics = {}
            if args.robot_position_mode == "planned-fixed":
                base_lateral_offsets_m = (0.0,)
            elif requested_robot_position is not None:
                base_lateral_offsets_m = _LOCAL_REQUESTED_BASE_LATERAL_OFFSETS_M
            else:
                base_lateral_offsets_m = (
                    0.4425,
                    0.445,
                    0.45,
                    -0.15,
                    0.15,
                    -0.30,
                    0.30,
                    -0.45,
                    0.0,
                    -0.005,
                )
            automatic_target_records = []
            automatic_target_by_collider = {}
            automatic_candidates = None
            if "auto" in (args.target_vine, args.target_organ):
                runtime_by_name = {
                    runtime.name: runtime for runtime in runtimes
                }
                target_options = tuple(
                    (vine_name, organ_label)
                    for vine_name, organ_label in episode.candidate_targets(runtimes)
                    if (
                        args.target_vine == "auto"
                        or vine_name == args.target_vine
                    )
                    and (
                        args.target_organ == "auto"
                        or organ_label == args.target_organ
                    )
                )
                for target_index, (vine_name, organ_label) in enumerate(
                    target_options
                ):
                    runtime = runtime_by_name[vine_name]
                    target_candidates = _target_grasp_candidates(
                        stage,
                        runtime,
                        organ_label,
                        base_planner,
                        axial_offsets_m=args.left_grasp_axial_offset,
                    )
                    if not target_candidates:
                        continue
                    preferred = max(
                        target_candidates,
                        key=lambda candidate: (
                            candidate.role == "petiole_grasp",
                            candidate.segment,
                        ),
                    )
                    height_from_floor_m = (
                        float(preferred.centre_m[2])
                        - float(nominal_robot_position[2])
                    )
                    # Keep a deliberately broad RB-Y1 work-height gate. It
                    # removes obviously unreachable upper/lower branches
                    # before exact IK while retaining every petiole around the
                    # demonstrated 1.1--1.8 m greenhouse work band.
                    work_height_eligible = 0.85 <= height_from_floor_m <= 2.10
                    record = {
                        "candidate_index": target_index,
                        "vine_name": vine_name,
                        "organ_label": organ_label,
                        "key": f"{vine_name}/{organ_label}",
                        "collider": preferred.collider,
                        "body": preferred.body,
                        "segment": preferred.segment,
                        "centre_m": list(preferred.centre_m),
                        "height_from_floor_m": height_from_floor_m,
                        "work_height_eligible": work_height_eligible,
                    }
                    automatic_target_records.append(record)
                    if work_height_eligible:
                        automatic_target_by_collider[preferred.collider] = record
                automatic_target_records.sort(
                    key=lambda record: (
                        not record["work_height_eligible"],
                        abs(record["height_from_floor_m"] - 1.85),
                        record["key"],
                    )
                )
                automatic_candidates = tuple(
                    next(
                        candidate
                        for candidate in _target_grasp_candidates(
                            stage,
                            runtime_by_name[record["vine_name"]],
                            record["organ_label"],
                            base_planner,
                            axial_offsets_m=args.left_grasp_axial_offset,
                        )
                        if candidate.collider == record["collider"]
                    )
                    for record in automatic_target_records
                    if record["work_height_eligible"]
                )
                report["automatic_target_screen"] = {
                    "mode": "joint_feasibility_before_seeded_selection",
                    "requested_vine": args.target_vine,
                    "requested_organ": args.target_organ,
                    "candidate_count": len(target_options),
                    "work_height_candidate_count": len(automatic_candidates),
                    "candidates": automatic_target_records,
                }
            maximum_initial_foliage_retries = 8
            initial_foliage_retry_steps = 30
            initial_planning_history = []
            base_plan = None
            for planning_index in range(
                maximum_initial_foliage_retries + 1
            ):
                attempt_diagnostics = {}
                base_plan = target_conditioned_base_plan(
                    nominal_robot_position,
                    base_lateral_offsets_m,
                    attempt_diagnostics,
                    advances_m=base_depth_advances_m,
                    candidates_override=automatic_candidates,
                    advance_direction_xy=(
                        (0.0, 1.0) if requested_local_search else None
                    ),
                )
                initial_planning_history.append(attempt_diagnostics)
                if base_plan is not None:
                    break
                rejection_reasons = {
                    rejection.get("reason")
                    for rejection in attempt_diagnostics.get(
                        "position_rejections", ()
                    )
                }
                retryable_foliage_rejection = bool(
                    rejection_reasons
                ) and (
                    rejection_reasons
                    <= {
                        "fixed_body_foliage_clearance",
                        "waiting_arm_foliage_clearance",
                    }
                )
                if (
                    automatic_candidates is not None
                    or not retryable_foliage_rejection
                    or planning_index >= maximum_initial_foliage_retries
                ):
                    break
                context.play()
                for _ in range(initial_foliage_retry_steps):
                    context.step(render=False)
                context.pause()
            base_diagnostics = {
                **initial_planning_history[-1],
                "live_foliage_retry": {
                    "attempts": len(initial_planning_history),
                    "maximum_retries": maximum_initial_foliage_retries,
                    "steps_per_retry": initial_foliage_retry_steps,
                    "succeeded": base_plan is not None,
                    "history": initial_planning_history,
                },
            }
            if base_plan is None:
                report.update(
                    stage="failed",
                    error=(
                        "no target-conditioned base pose reaches a distal petiole "
                        "segment with wrist-camera clearance"
                    ),
                    base_planning=base_diagnostics,
                )
                _emit(report, args.report)
                app.close()
                return 1
            if automatic_candidates is not None:
                selected_record = automatic_target_by_collider.get(
                    base_plan.selected_grasp_collider
                )
                if selected_record is None:
                    raise RuntimeError(
                        "automatic base plan lost selected target identity"
                    )
                selected_target = episode.EpisodeTarget(
                    vine_name=selected_record["vine_name"],
                    organ_label=selected_record["organ_label"],
                    candidate_index=selected_record["candidate_index"],
                    candidate_count=len(target_options),
                    seed=int(args.episode_seed),
                )
                selected_runtime = runtime_by_name[selected_target.vine_name]
                target_reference = np.asarray(
                    selected_runtime.cut_sites[selected_target.organ_label],
                    dtype=np.float64,
                )
                aisle_bounds = _approach_aisle_base_bounds(
                    stage,
                    selected_runtime.placement_m,
                    args.robot_yaw,
                    Usd,
                    UsdGeom,
                    np,
                )
                report["automatic_target_screen"].update(
                    selected_target=selected_target.key,
                    selected_grasp_collider=(
                        base_plan.selected_grasp_collider
                    ),
                )
            args.robot_position = base_plan.position_m
            report["robot_preposition"] = {
                "mode": args.robot_position_mode,
                **dataclasses.asdict(base_plan),
                "requested_position_m": requested_robot_position,
                "opposite_aisle": aisle_bounds,
                "aisle_depth_advances_m": base_depth_advances_m,
                "lateral_offsets_m": base_lateral_offsets_m,
            }
        else:
            report["robot_preposition"] = {
                "mode": args.robot_position_mode,
                "nominal_position_m": nominal_robot_position,
                "position_m": nominal_robot_position,
                "offset_m": (0.0, 0.0, 0.0),
                "requested_position_m": requested_robot_position,
                "opposite_aisle": aisle_bounds,
            }
        yaw_radians = np.radians(float(args.robot_yaw))
        robot_forward_xy = np.asarray(
            [np.cos(yaw_radians), np.sin(yaw_radians)],
            dtype=np.float64,
        )
        target_delta_xy = target_reference[:2] - np.asarray(
            args.robot_position[:2], dtype=np.float64
        )
        target_forward_distance_m = float(
            np.dot(target_delta_xy, robot_forward_xy)
        )
        report["robot_preposition"]["target_forward_distance_m"] = (
            target_forward_distance_m
        )
        if target_forward_distance_m <= 0.15:
            report.update(
                stage="failed",
                error="selected tomato petiole is not in front of the robot",
            )
            _emit(report, args.report)
            app.close()
            return 1
        robot_placement = robot_scene.add_fitted_robot(
            stage,
            robot_path,
            position_m=args.robot_position,
            yaw_degrees=args.robot_yaw,
        )
        report["robot_hardware_mount_synchronization"] = (
            robot_hardware.synchronize_fitted_hardware_mounts(
                stage,
                robot_placement.root_path,
            )
        )
        report["robot_presentation_knife"] = (
            robot_hardware.author_runtime_knife_presentation(
                stage,
                robot_placement.root_path,
            )
        )
        if args.teleop_command_file is None:
            startup_arm_targets = _greenhouse_startup_arm_targets(
                args.rl_initial_left_arm
            )
            _set_joint_group_initial_state(
                stage,
                "left",
                startup_arm_targets["left"],
            )
            _set_joint_group_initial_state(
                stage,
                "right",
                startup_arm_targets["right"],
            )
            report["greenhouse_robot_startup_pose"] = {
                "source": (
                    "online_rl_curriculum_override"
                    if args.rl_initial_left_arm is not None
                    else "symmetric_sdk_ready"
                ),
                "left_degrees": list(startup_arm_targets["left"]),
                "right_degrees": list(startup_arm_targets["right"]),
                "task_stow_transition": "planned_on_full_ik_request",
            }
            if args.rl_initial_left_arm is not None:
                report["online_rl_curriculum_start_left_degrees"] = list(
                    args.rl_initial_left_arm
                )
        if args.teleop_command_file is not None:
            startup_arm_targets = _greenhouse_startup_arm_targets(
                task_safe=False
            )
            startup_targets = {
                "left": startup_arm_targets["left"],
                "right": startup_arm_targets["right"],
                "torso": tuple(
                    robot_scene.SDK_READY_POSE_DEGREES[f"torso_{index}"]
                    for index in range(6)
                ),
                "head": tuple(
                    robot_scene.SDK_READY_POSE_DEGREES[f"head_{index}"]
                    for index in range(2)
                ),
            }
            startup_source = "symmetric_sdk_ready_fallback"
            startup_error = None
            startup_age_ms = None
            try:
                startup_payload = json.loads(
                    pathlib.Path(args.teleop_command_file).read_text(
                        encoding="utf-8"
                    )
                )
                startup_command = teleop.parse_command(startup_payload)
                startup_age_s = time.monotonic() - startup_command.monotonic_time_s
                if startup_age_s < -0.050:
                    raise teleop.TeleopCommandError(
                        "startup command timestamp is in the future"
                    )
                if startup_age_s > args.teleop_watchdog_ms / 1000.0:
                    raise teleop.TeleopCommandError(
                        f"startup command is stale ({startup_age_s * 1000.0:.1f} ms)"
                    )
                if startup_command.left.enabled:
                    startup_targets["left"] = startup_command.left.joint_degrees
                if startup_command.right.enabled:
                    startup_targets["right"] = startup_command.right.joint_degrees
                if startup_command.torso is not None and startup_command.torso.enabled:
                    startup_targets["torso"] = startup_command.torso.joint_degrees
                if startup_command.head is not None and startup_command.head.enabled:
                    startup_targets["head"] = startup_command.head.joint_degrees
                if (
                    startup_command.left_gripper is not None
                    and startup_command.left_gripper.enabled
                ):
                    teleop_startup_gripper_openness = (
                        startup_command.left_gripper.openness
                    )
                startup_source = "fresh_measured_robot_mailbox"
                startup_age_ms = max(startup_age_s, 0.0) * 1000.0
            except (
                FileNotFoundError,
                OSError,
                json.JSONDecodeError,
                teleop.TeleopCommandError,
            ) as exc:
                startup_error = str(exc)
            for group, target_degrees in startup_targets.items():
                _set_joint_group_initial_state(stage, group, target_degrees)
            report["teleop_startup_pose"] = {
                "source": startup_source,
                "command_age_ms": startup_age_ms,
                "fallback_reason": startup_error,
                "joint_degrees": {
                    group: list(values)
                    for group, values in startup_targets.items()
                },
                "left_gripper_openness": teleop_startup_gripper_openness,
            }
        greenhouse_structure_obstacles = _greenhouse_structure_obstacles(
            stage,
            robot_kinematics,
            args.robot_position,
        )
        greenhouse_wall_colliders = _author_greenhouse_wall_colliders(
            stage,
            greenhouse_structure_obstacles,
        )
        report["robot"] = dataclasses.asdict(robot_placement)
        report["greenhouse_safety"] = {
            "planning_obstacle_count": len(greenhouse_structure_obstacles),
            "planning_obstacles": [
                dataclasses.asdict(obstacle)
                for obstacle in greenhouse_structure_obstacles
            ],
            "physical_wall_colliders": list(greenhouse_wall_colliders),
        }
    report.update(
        stage="rigged",
        static_vines=len(static_vines),
        physics_vines=len(runtimes),
        links=sum(len(runtime.rig.links) for runtime in runtimes),
        clips=sum(len(runtime.clips) for runtime in runtimes),
        severable=sum(len(runtime.rig.cut_joints) for runtime in runtimes),
        contact_colliders=sum(len(runtime.rig.collider_paths) for runtime in runtimes),
        neighbour_safety_vines=len(
            {collider.vine_name for collider in safety_colliders}
        ),
        neighbour_safety_colliders=len(safety_colliders),
        sources=[str(runtime.source) for runtime in runtimes],
        episode_target={
            **dataclasses.asdict(selected_target),
            "key": selected_target.key,
            "selection_mode": (
                "seeded_auto"
                if "auto" in (args.target_vine, args.target_organ)
                else "exact"
            ),
        },
    )
    _emit(report, args.report)

    for _ in range(10):
        app.update()

    from isaacsim.core.api import SimulationContext

    contact_diagnostics = (
        RobotContactDiagnostics(stage)
        if (
            args.contact_diagnostics
            or args.bimanual_probe is not None
            or args.teleop_command_file is not None
            or args.rl_server
            or (not headless and robot_placement is not None)
        )
        else None
    )
    blade_cutting = None
    grasp_manager = None
    if robot_placement is not None:
        blade_cutting = BladeContactMonitor(
            stage,
            runtimes,
            robot_placement,
            cutting.CutGateParameters(
                minimum_forward_speed_m_s=args.cut_min_speed,
                maximum_axis_dot=float(
                    np.sin(np.radians(args.cut_max_axis_angle))
                ),
            ),
            interaction_cut_enabled=(args.teleop_command_file is not None),
        )
        blade_cutting.add_safety_colliders(safety_colliders)
        blade_cutting.set_active_target(
            selected_target.vine_name,
            selected_target.organ_label,
        )
        report["blade_cutting"] = blade_cutting.summary
        floor_z = float(args.robot_position[2])
        grasp_manager = LeftGraspManager(
            stage,
            runtimes,
            robot_placement,
            deleaf_task.TaskParameters(
                drop_zone_min_m=(
                    float(args.robot_position[0]) - 1.20,
                    float(args.robot_position[1]) - 1.00,
                    floor_z,
                ),
                drop_zone_max_m=(
                    float(args.robot_position[0]) - 0.30,
                    float(args.robot_position[1]) + 0.70,
                    floor_z + 0.60,
                ),
            ),
        )
        grasp_manager.set_active_target(
            selected_target.vine_name,
            selected_target.organ_label,
        )
        if args.bimanual_probe == "full" or args.rl_server:
            grasp_manager.require_structural_counterhold()
        if teleop_startup_gripper_openness is not None:
            grasp_manager.request_openness(teleop_startup_gripper_openness)
        blade_cutting.set_counterhold_provider(grasp_manager.holds_target)
        report["bimanual_task"] = grasp_manager.summary
    if context is None:
        context = SimulationContext(
            physics_dt=1.0 / 240.0,
            rendering_dt=1.0 / 60.0,
            stage_units_in_meters=1.0,
        )
        context.initialize_physics()
    if contact_diagnostics is not None:
        contact_diagnostics.subscribe()
    if blade_cutting is not None:
        blade_cutting.subscribe()
    if grasp_manager is not None:
        grasp_manager.subscribe()
    context.get_physics_context().set_gravity(-9.81)
    for runtime in runtimes:
        runtime.rest_positions = _positions(stage, _base_link_paths(runtime.rig))

    if not headless:
        report["native_transform_selector_disabled"] = _disable_native_mouse_interaction(app)
        _focus_viewport(camera_path)

    context.play()
    for _ in range(args.settle_steps):
        context.step(render=False)
        if grasp_manager is not None:
            grasp_manager.process()
        if blade_cutting is not None:
            _apply_blade_cut_decisions(
                context,
                blade_cutting,
                report,
                grasp_manager=grasp_manager,
            )

    if (
        robot_placement is not None
        and args.robot_position_mode in {
            "target-conditioned",
            "planned-fixed",
        }
    ):
        maximum_live_foliage_retries = 8
        live_foliage_retry_steps = 30
        settled_planning_history = []
        settled_base_plan = None
        for planning_index in range(maximum_live_foliage_retries + 1):
            settled_base_diagnostics = {}
            settled_base_plan = target_conditioned_base_plan(
                tuple(float(value) for value in args.robot_position),
                (0.0,),
                settled_base_diagnostics,
                grasp_manager.summary.get("gripper_geometry"),
            )
            settled_planning_history.append(settled_base_diagnostics)
            if settled_base_plan is not None:
                break
            rejection_reasons = {
                rejection.get("reason")
                for rejection in settled_base_diagnostics.get(
                    "position_rejections", ()
                )
            }
            retryable_foliage_rejection = bool(rejection_reasons) and (
                rejection_reasons
                <= {
                    "fixed_body_foliage_clearance",
                    "waiting_arm_foliage_clearance",
                }
            )
            retryable_foliage_rejection = (
                _retryable_live_base_plan_rejection(
                    settled_base_diagnostics
                )
            )
            if (
                not retryable_foliage_rejection
                or planning_index >= maximum_live_foliage_retries
            ):
                break
            for _ in range(live_foliage_retry_steps):
                context.step(render=False)
                grasp_manager.process()
                _apply_blade_cut_decisions(
                    context,
                    blade_cutting,
                    report,
                    grasp_manager=grasp_manager,
                )
        report["settled_base_planning"] = {
            **settled_planning_history[-1],
            "live_foliage_retry": {
                "attempts": len(settled_planning_history),
                "maximum_retries": maximum_live_foliage_retries,
                "steps_per_retry": live_foliage_retry_steps,
                "succeeded": settled_base_plan is not None,
                "history": settled_planning_history,
            },
        }
        if settled_base_plan is None:
            report.update(
                stage="failed",
                succeeded=False,
                error=(
                    "no collision-clear left grasp route exists at the parked "
                    "robot base after vine settling"
                ),
            )
            _emit(report, args.report)
            context.stop()
            app.close()
            return 1
        previous_preposition = report["robot_preposition"]
        report["robot_preposition"] = {
            "mode": args.robot_position_mode,
            **dataclasses.asdict(settled_base_plan),
            "requested_position_m": previous_preposition.get(
                "requested_position_m"
            ),
            "opposite_aisle": previous_preposition.get("opposite_aisle"),
            "target_forward_distance_m": previous_preposition.get(
                "target_forward_distance_m"
            ),
            "geometry_source": "post_settle_live_vines",
        }
        _emit(report, args.report)
    probe_frame_recorder = None
    if args.probe_frame_dir is not None:
        probe_camera_views = {
            "inspection": camera_path,
            "head": robot_placement.cameras[0],
            "left_wrist": robot_placement.cameras[1],
            "right_wrist": robot_placement.cameras[2],
        }
        args.probe_frame_dir.mkdir(parents=True, exist_ok=True)
        context.pause()
        try:
            probe_frame_recorder = _TeleopCameraRecorder(
                probe_camera_views,
                args.probe_video_cameras,
                (args.probe_video_width, args.probe_video_height),
                args.probe_frame_dir,
            )
        finally:
            context.play()
        report["bimanual_probe_frame_capture"] = {
            "enabled": True,
            "directory": str(args.probe_frame_dir),
            "cameras": list(args.probe_video_cameras),
            "resolution": [args.probe_video_width, args.probe_video_height],
            "frame_rate_hz": args.probe_video_hz,
            "frame_count": 0,
            "capture_errors": {},
        }
        _emit(report, args.report)
    if args.rl_server:
        rl_airflow = vine_interaction.Airflow(
            stage,
            runtimes,
            speed_m_s=args.airflow_speed,
            frequency_hz=args.airflow_frequency,
            direction_deg=args.airflow_direction,
        )
        rl_frame_recorder = None
        if args.rl_frame_dir is not None:
            rl_camera_views = {
                "inspection": camera_path,
                "head": robot_placement.cameras[0],
                "left_wrist": robot_placement.cameras[1],
                "right_wrist": robot_placement.cameras[2],
            }
            args.rl_frame_dir.mkdir(parents=True, exist_ok=True)
            context.pause()
            try:
                rl_frame_recorder = _TeleopCameraRecorder(
                    rl_camera_views,
                    args.rl_video_cameras,
                    (args.rl_video_width, args.rl_video_height),
                    args.rl_frame_dir,
                )
            finally:
                context.play()
        runtime = isaac_rl.IsaacDeleafRuntime(
            stage=stage,
            context=context,
            runtimes=runtimes,
            selected_target=selected_target,
            blade_monitor=blade_cutting,
            grasp_manager=grasp_manager,
            contact_diagnostics=contact_diagnostics,
            report=report,
            apply_cut_decisions=_apply_blade_cut_decisions,
            unsafe_contacts=_probe_unsafe_contacts,
            airflow=rl_airflow,
            frame_recorder=rl_frame_recorder,
            render=args.rl_render or rl_frame_recorder is not None,
            reset_settle_steps=args.rl_reset_settle_steps,
            reset_joint_noise_degrees=args.rl_reset_joint_noise,
        )
        environment = rl_env.OnlineDeleafEnv(
            runtime,
            action_parameters=rl_env.ActionParameters(
                maximum_arm_speed_degrees_s=args.rl_max_arm_speed,
                maximum_arm_acceleration_degrees_s2=(
                    args.rl_max_arm_acceleration
                ),
                control_hz=args.rl_control_hz,
            ),
            maximum_episode_steps=args.rl_max_episode_steps,
            terminal_phase=args.rl_terminal_phase,
        )
        report.update(
            stage="rl_server",
            succeeded=False,
            online_rl_configuration={
                "target": selected_target.key,
                "strict_bimanual_benchmark": True,
                "direct_interaction_cut_enabled": False,
                "teleoperation_enabled": False,
                "control_hz": args.rl_control_hz,
                "physics_hz": 240.0,
                "physics_steps_per_action": (
                    environment.action_parameters.physics_steps_per_action
                ),
                "action": (
                    "normalized left arm joint velocity[7], right arm joint "
                    "velocity[7], left gripper aperture velocity[1]"
                ),
                "observation_size": rl_env.OBSERVATION_SIZE,
                "maximum_episode_steps": args.rl_max_episode_steps,
                "terminal_phase": args.rl_terminal_phase,
                "maximum_arm_speed_degrees_s": args.rl_max_arm_speed,
                "maximum_arm_acceleration_degrees_s2": (
                    args.rl_max_arm_acceleration
                ),
                "initial_left_arm_degrees": args.rl_initial_left_arm,
                "randomization": {
                    "arm_joint_uniform_degrees": args.rl_reset_joint_noise,
                    "airflow_speed_m_s": args.airflow_speed,
                    "seeded_gust_phase": True,
                },
                "frame_capture": {
                    "enabled": rl_frame_recorder is not None,
                    "directory": (
                        str(args.rl_frame_dir) if args.rl_frame_dir is not None else None
                    ),
                    "cameras": list(args.rl_video_cameras),
                    "resolution": [args.rl_video_width, args.rl_video_height],
                },
            },
        )
        _emit(report, args.report)
        try:
            summary = isaac_rl.serve(
                environment,
                host=args.rl_host,
                port=args.rl_port,
                app=app,
                report=report,
                report_path=args.report,
                emit=_emit,
            )
            report["online_rl"] = summary
            report.update(stage="done", succeeded=summary["steps"] > 0)
        finally:
            if blade_cutting is not None:
                report["blade_cutting"] = blade_cutting.summary
                blade_cutting.close()
            if grasp_manager is not None:
                report["bimanual_task"] = grasp_manager.summary
                grasp_manager.close()
            if contact_diagnostics is not None:
                report["robot_contacts"] = contact_diagnostics.summary
                contact_diagnostics.close()
            if rl_frame_recorder is not None:
                rl_frame_recorder.close()
            _emit(report, args.report)
            context.stop()
            app.close()
        return 0
    if headless:
        success = _run_headless_checks(
            stage,
            context,
            runtimes,
            selected_target,
            args,
            report,
        )
        if blade_cutting is not None:
            report["initial_tool_safety_clear"] = blade_cutting.safety_clear
            success = success and blade_cutting.safety_clear

        if args.bimanual_probe is not None:
            probe = _bimanual_probe(
                stage,
                context,
                selected_runtime,
                args,
                report,
                blade_cutting,
                grasp_manager,
                contact_diagnostics,
                robot_hardware,
                robot_kinematics,
                greenhouse_structure_obstacles,
                frame_recorder=probe_frame_recorder,
            )
            report["bimanual_probe"] = probe
            success = success and bool(probe["succeeded"])
        if contact_diagnostics is not None:
            report["robot_contacts"] = contact_diagnostics.summary
            contact_diagnostics.close()
        if args.screenshot is not None:
            capture_camera = camera_path
            if args.capture_camera != "inspection":
                if robot_placement is None:
                    raise ValueError("a fitted robot is required to capture a D405 camera")
                camera_indices = {"head": 0, "left_wrist": 1, "right_wrist": 2}
                capture_camera = robot_placement.cameras[camera_indices[args.capture_camera]]
            _capture(capture_camera, args, app)
            report["screenshot"] = str(args.screenshot)
            report["capture_camera"] = capture_camera
        if probe_frame_recorder is not None:
            probe_frame_recorder.close()
        report.update(stage="done", succeeded=bool(success))
        if blade_cutting is not None:
            report["blade_cutting"] = blade_cutting.summary
            blade_cutting.close()
        if grasp_manager is not None:
            report["bimanual_task"] = grasp_manager.summary
            grasp_manager.close()
        _emit(report, args.report)
        context.stop()
        app.close()
        return 0 if success else 1

    if contact_diagnostics is not None:
        report["robot_contacts"] = contact_diagnostics.summary

    # Render the selected inspection camera before the overlay reads its
    # projection matrices. All settling frames above are deliberately headless.
    for _ in range(4):
        context.step(render=True)
    camera_views = {"inspection": camera_path}
    if robot_placement is not None:
        camera_views.update(
            head=robot_placement.cameras[0],
            left_wrist=robot_placement.cameras[1],
            right_wrist=robot_placement.cameras[2],
        )

    def run_ik_from_ui(mode: str) -> dict:
        if (
            robot_placement is None
            or blade_cutting is None
            or grasp_manager is None
            or contact_diagnostics is None
        ):
            return {
                "mode": mode,
                "succeeded": False,
                "error": "fitted robot and safety monitors are required",
            }
        original_mode = args.bimanual_probe
        original_interaction_cut = blade_cutting.interaction_cut_enabled
        args.bimanual_probe = mode
        blade_cutting.set_interaction_cut_enabled(False)
        try:
            baseline_clear = _run_headless_checks(
                stage,
                context,
                runtimes,
                selected_target,
                args,
                report,
            )
            probe = _bimanual_probe(
                stage,
                context,
                selected_runtime,
                args,
                report,
                blade_cutting,
                grasp_manager,
                contact_diagnostics,
                robot_hardware,
                robot_kinematics,
                greenhouse_structure_obstacles,
                frame_recorder=probe_frame_recorder,
            )
        finally:
            args.bimanual_probe = original_mode
            blade_cutting.set_interaction_cut_enabled(
                original_interaction_cut
            )
        report["bimanual_probe"] = probe
        report["robot_contacts"] = contact_diagnostics.summary
        report["blade_cutting"] = blade_cutting.summary
        report["bimanual_task"] = grasp_manager.summary
        report.update(
            stage="probe_complete",
            succeeded=bool(baseline_clear and probe["succeeded"]),
        )
        _emit(report, args.report)
        return probe

    def run_grasp_ik_from_ui() -> dict:
        return run_ik_from_ui("grasp")

    def run_full_ik_from_ui() -> dict:
        return run_ik_from_ui("full")

    controller = InteractionController(
        stage,
        runtimes,
        report,
        args.report,
        args,
        vine_interaction,
        camera_views,
        blade_cutting,
        grasp_manager,
        selected_target,
        robot_placement=robot_placement,
        run_grasp_ik=run_grasp_ik_from_ui,
        run_full_ik=run_full_ik_from_ui,
    )
    teleop_controller = None
    if args.teleop_command_file is not None:
        # Replicator render products need explicit warmup, but that must not
        # advance unobserved physics or accumulate cut/grasp contacts.
        context.pause()
        try:
            teleop_controller = SimulatorTeleop(
                stage,
                args,
                camera_views,
                selected_target,
                report,
                args.report,
                teleop,
                robot_hardware,
                robot_kinematics,
                blade_cutting,
                grasp_manager,
                contact_diagnostics,
            )
        finally:
            context.play()
    report.update(stage="running", controls=controller.controls)
    _emit(report, args.report)
    if args.bimanual_probe is not None:
        success = _run_headless_checks(
            stage,
            context,
            runtimes,
            selected_target,
            args,
            report,
        )
        probe = _bimanual_probe(
            stage,
            context,
            selected_runtime,
            args,
            report,
            blade_cutting,
            grasp_manager,
            contact_diagnostics,
            robot_hardware,
            robot_kinematics,
            greenhouse_structure_obstacles,
            frame_recorder=probe_frame_recorder,
        )
        report["bimanual_probe"] = probe
        success = success and bool(probe["succeeded"])
        if contact_diagnostics is not None:
            report["robot_contacts"] = contact_diagnostics.summary
        if blade_cutting is not None:
            report["blade_cutting"] = blade_cutting.summary
        if grasp_manager is not None:
            report["bimanual_task"] = grasp_manager.summary
        report.update(stage="probe_complete", succeeded=bool(success))
        _emit(report, args.report)
        print(
            "Visible bimanual probe complete; close the window when inspection "
            "is finished."
        )
    if args.visual_pull_probe:
        visual_probe = controller.run_visual_pull_probe(context, stage, runtimes[0])
        report["visual_pull_probe"] = visual_probe
        report.update(stage="done", succeeded=bool(visual_probe["succeeded"]))
        _emit(report, args.report)
        controller.close()
        context.stop()
        app.close()
        return 0 if visual_probe["succeeded"] else 1
    print(
        "Shift-drag pulls; [ / ] selects; G closes left grasp; O releases; "
        "C DEBUG-force-cuts; V changes vine; 1-4 switches cameras"
    )
    try:
        simulation_step = 0
        while app.is_running():
            if teleop_controller is not None:
                teleop_controller.process(simulation_step)
            context.step(render=True)
            simulation_step += 1
            controller.process(context)
            if args.tear_force > 0.0:
                controller.poll_tears()
    finally:
        if teleop_controller is not None:
            teleop_controller.close()
        if probe_frame_recorder is not None:
            probe_frame_recorder.close()
        controller.close()
        if blade_cutting is not None:
            report["blade_cutting"] = blade_cutting.summary
            blade_cutting.close()
        if grasp_manager is not None:
            report["bimanual_task"] = grasp_manager.summary
            grasp_manager.close()
        if contact_diagnostics is not None:
            report["robot_contacts"] = contact_diagnostics.summary
            contact_diagnostics.close()
        report["stage"] = "closed"
        _emit(report, args.report)
        context.stop()
        app.close()
    return 0


def _source_for_placement(name: str, sources: list[pathlib.Path]) -> pathlib.Path:
    match = re.search(r"(\d+)$", name)
    index = int(match.group(1)) if match else 0
    return sources[index % len(sources)]


def _select_physics_vines(static_vines, target_vine: str, count: int):
    """Select the requested target first, then fill the remaining budget."""
    budget = min(int(count), len(static_vines))
    if target_vine == "auto":
        return list(static_vines[:budget])
    target = next(
        (prim for prim in static_vines if prim.GetName() == target_vine),
        None,
    )
    if target is None:
        available = ", ".join(prim.GetName() for prim in static_vines)
        raise ValueError(
            f"target vine {target_vine!r} is not present; available: {available}"
        )
    return [target, *[prim for prim in static_vines if prim != target]][:budget]


def _opposite_aisle_base_bounds(
    stage,
    placement,
    yaw_degrees: float,
    Usd,
    UsdGeom,
    np,
) -> dict:
    """Return a chassis-clear base interval between the gutter and outer wall."""
    target = np.asarray(placement, dtype=np.float64)
    cache = UsdGeom.BBoxCache(Usd.TimeCode.Default(), [UsdGeom.Tokens.default_])
    bed_candidates = []
    for prim in stage.Traverse():
        path = str(prim.GetPath())
        if not path.endswith("/Bed/Bed_Bed/mesh"):
            continue
        extent = cache.ComputeWorldBound(prim).ComputeAlignedRange()
        lower = np.asarray(extent.GetMin(), dtype=np.float64)
        upper = np.asarray(extent.GetMax(), dtype=np.float64)
        if lower[0] - 1e-6 <= target[0] <= upper[0] + 1e-6:
            bed_candidates.append(
                (
                    abs(float(0.5 * (lower[1] + upper[1]) - target[1])),
                    path,
                    lower,
                    upper,
                )
            )
    if not bed_candidates:
        raise RuntimeError("could not resolve the selected gutter bed bounds")
    _, bed_path, _, bed_upper = min(bed_candidates, key=lambda item: item[0])

    wall_candidates = []
    environment = stage.GetPrimAtPath("/World/Main_Cultivation_Zone/Env")
    for prim in environment.GetChildren() if environment.IsValid() else ():
        if not prim.GetName().startswith("Wall_"):
            continue
        extent = cache.ComputeWorldBound(prim).ComputeAlignedRange()
        lower = np.asarray(extent.GetMin(), dtype=np.float64)
        upper = np.asarray(extent.GetMax(), dtype=np.float64)
        if lower[1] <= target[1] or upper[2] - lower[2] < 2.0:
            continue
        wall_candidates.append((float(lower[1]), str(prim.GetPath()), lower, upper))
    if not wall_candidates:
        raise RuntimeError("could not resolve the positive-Y greenhouse wall")
    wall_inner_y, wall_path, _, _ = min(wall_candidates, key=lambda item: item[0])

    yaw = np.radians(float(yaw_degrees))
    cosine = float(np.cos(yaw))
    sine = float(np.sin(yaw))
    world_y_offsets = [
        sine * local_x + cosine * local_y
        for local_x in (_RBY1_CHASSIS_MIN_LOCAL_M[0], _RBY1_CHASSIS_MAX_LOCAL_M[0])
        for local_y in (_RBY1_CHASSIS_MIN_LOCAL_M[1], _RBY1_CHASSIS_MAX_LOCAL_M[1])
    ]
    minimum_y = (
        float(bed_upper[1])
        + _MINIMUM_BASE_STRUCTURE_CLEARANCE_M
        - min(world_y_offsets)
    )
    maximum_y = (
        wall_inner_y
        - _MINIMUM_BASE_STRUCTURE_CLEARANCE_M
        - max(world_y_offsets)
    )
    if minimum_y > maximum_y:
        raise RuntimeError(
            f"RBY1 chassis does not fit opposite aisle: {minimum_y:.3f}>{maximum_y:.3f}"
        )
    return {
        "minimum_base_y_m": minimum_y,
        "maximum_base_y_m": maximum_y,
        "selected_base_y_m": 0.5 * (minimum_y + maximum_y),
        "gutter_outer_y_m": float(bed_upper[1]),
        "wall_inner_y_m": wall_inner_y,
        "bed_path": bed_path,
        "wall_path": wall_path,
    }


def _approach_aisle_base_bounds(
    stage,
    placement,
    yaw_degrees: float,
    Usd,
    UsdGeom,
    np,
) -> dict:
    """Return the chassis-clear aisle on the robot-facing side of a gutter."""
    target = np.asarray(placement, dtype=np.float64)
    cache = UsdGeom.BBoxCache(
        Usd.TimeCode.Default(), [UsdGeom.Tokens.default_]
    )
    beds = []
    for prim in stage.Traverse():
        path = str(prim.GetPath())
        if not path.endswith("/Bed/Bed_Bed/mesh"):
            continue
        extent = cache.ComputeWorldBound(prim).ComputeAlignedRange()
        lower = np.asarray(extent.GetMin(), dtype=np.float64)
        upper = np.asarray(extent.GetMax(), dtype=np.float64)
        if lower[0] - 1e-6 <= target[0] <= upper[0] + 1e-6:
            beds.append(
                (
                    float(0.5 * (lower[1] + upper[1])),
                    path,
                    lower,
                    upper,
                )
            )
    if not beds:
        raise RuntimeError("could not resolve the selected gutter bed bounds")

    target_bed = min(beds, key=lambda item: abs(item[0] - target[1]))
    target_centre_y, bed_path, bed_lower, bed_upper = target_bed
    yaw = np.radians(float(yaw_degrees))
    cosine = float(np.cos(yaw))
    sine = float(np.sin(yaw))
    if abs(sine) < 0.5:
        raise RuntimeError("greenhouse approach requires the robot to face +/-Y")

    if sine > 0.0:
        neighbours = [
            bed for bed in beds if bed[0] < target_centre_y - 1e-3
        ]
        if not neighbours:
            raise RuntimeError("could not resolve the neighbouring negative-Y gutter")
        neighbour = max(neighbours, key=lambda item: item[0])
        lower_boundary_y = float(neighbour[3][1])
        upper_boundary_y = float(bed_lower[1])
        lower_boundary_path = neighbour[1]
        upper_boundary_path = bed_path
        aisle_side = "inter_gutter_negative_y"
    else:
        walls = []
        environment = stage.GetPrimAtPath("/World/Main_Cultivation_Zone/Env")
        for prim in environment.GetChildren() if environment.IsValid() else ():
            if not prim.GetName().startswith("Wall_"):
                continue
            extent = cache.ComputeWorldBound(prim).ComputeAlignedRange()
            lower = np.asarray(extent.GetMin(), dtype=np.float64)
            upper = np.asarray(extent.GetMax(), dtype=np.float64)
            if lower[1] <= target[1] or upper[2] - lower[2] < 2.0:
                continue
            walls.append((float(lower[1]), str(prim.GetPath())))
        if not walls:
            raise RuntimeError("could not resolve the positive-Y greenhouse wall")
        wall_inner_y, wall_path = min(walls, key=lambda item: item[0])
        lower_boundary_y = float(bed_upper[1])
        upper_boundary_y = wall_inner_y
        lower_boundary_path = bed_path
        upper_boundary_path = wall_path
        aisle_side = "outer_wall_positive_y"

    world_y_offsets = [
        sine * local_x + cosine * local_y
        for local_x in (
            _RBY1_CHASSIS_MIN_LOCAL_M[0],
            _RBY1_CHASSIS_MAX_LOCAL_M[0],
        )
        for local_y in (
            _RBY1_CHASSIS_MIN_LOCAL_M[1],
            _RBY1_CHASSIS_MAX_LOCAL_M[1],
        )
    ]
    minimum_y = (
        lower_boundary_y
        + _MINIMUM_BASE_STRUCTURE_CLEARANCE_M
        - min(world_y_offsets)
    )
    maximum_y = (
        upper_boundary_y
        - _MINIMUM_BASE_STRUCTURE_CLEARANCE_M
        - max(world_y_offsets)
    )
    if minimum_y > maximum_y:
        raise RuntimeError(
            f"RBY1 chassis does not fit {aisle_side}: "
            f"{minimum_y:.3f}>{maximum_y:.3f}"
        )
    target_edge_margin_m = min(0.085, 0.25 * (maximum_y - minimum_y))
    selected_y = (
        maximum_y - target_edge_margin_m
        if sine > 0.0
        else minimum_y + target_edge_margin_m
    )
    return {
        "aisle_side": aisle_side,
        "minimum_base_y_m": minimum_y,
        "maximum_base_y_m": maximum_y,
        "selected_base_y_m": selected_y,
        "lower_boundary_y_m": lower_boundary_y,
        "upper_boundary_y_m": upper_boundary_y,
        "lower_boundary_path": lower_boundary_path,
        "upper_boundary_path": upper_boundary_path,
        "bed_path": bed_path,
        "target_forward_distance_y_m": sine * (target[1] - selected_y),
    }


def _default_robot_position(
    stage,
    placement,
    yaw_degrees,
    Usd,
    UsdGeom,
    np,
    *,
    aisle_reference=None,
) -> tuple[float, float, float]:
    """Place the base beside the selected gutter on its local cultivation floor."""
    target = np.asarray(placement, dtype=np.float64)
    cache = UsdGeom.BBoxCache(Usd.TimeCode.Default(), [UsdGeom.Tokens.default_])
    floor_candidates: list[float] = []
    for prim in stage.Traverse():
        if prim.GetName() != "GroundPlane":
            continue
        extent = cache.ComputeWorldBound(prim).ComputeAlignedRange()
        if extent.IsEmpty():
            continue
        lower = np.asarray(extent.GetMin(), dtype=np.float64)
        upper = np.asarray(extent.GetMax(), dtype=np.float64)
        contains_target = bool(
            np.all(target[:2] >= lower[:2] - 1e-6)
            and np.all(target[:2] <= upper[:2] + 1e-6)
        )
        if contains_target and upper[2] <= target[2] + 1e-6:
            floor_candidates.append(float(upper[2]))
    if not floor_candidates:
        raise RuntimeError(
            f"no ground plane below selected vine placement {tuple(float(v) for v in target)}"
        )
    aisle = _approach_aisle_base_bounds(
        stage,
        placement if aisle_reference is None else aisle_reference,
        yaw_degrees,
        Usd,
        UsdGeom,
        np,
    )
    return (
        float(target[0] + 0.12),
        aisle["selected_base_y_m"],
        max(floor_candidates),
    )


def _placement_transforms(matrix, vine_usd, Gf, np):
    """Position and direction transforms from GLB coordinates to greenhouse world."""

    def points(values):
        converted = vine_usd.gltf_to_usd(values)
        return np.asarray([matrix.Transform(Gf.Vec3d(*row)) for row in converted], dtype=np.float64)

    def directions(values):
        converted = vine_usd.gltf_to_usd(values)
        return np.asarray(
            [matrix.TransformDir(Gf.Vec3d(*row)) for row in converted], dtype=np.float64
        )

    return points, directions


def _default_inspection_camera_pose(placement):
    """Frame the robot-side aisle, RB-Y1 body, and selected crop together."""
    x = float(placement[0])
    y = float(placement[1])
    z = float(placement[2])
    # RB-Y1 is intentionally parked on the negative-Y side of the selected
    # gutter. Aim halfway between its base and the crop and place the camera
    # in that same aisle. The former +Y eye looked through the trough and
    # canopy, visually reducing the robot to its dark camera/tool attachments.
    target = (x, y - 0.15, z + 0.85)
    eye = (target[0] - 1.8, target[1] - 2.6, target[2] + 1.15)
    return eye, target


def _author_camera(stage, placement, args, Gf, Sdf, UsdGeom) -> str:
    default_eye, default_target = _default_inspection_camera_pose(placement)
    target = (
        Gf.Vec3d(*args.camera_target)
        if args.camera_target is not None
        else Gf.Vec3d(*default_target)
    )
    eye = (
        Gf.Vec3d(*args.eye)
        if args.eye is not None
        else Gf.Vec3d(*default_eye)
    )
    path = Sdf.Path("/World/InteractiveInspectionCamera")
    camera = UsdGeom.Camera.Define(stage, path)
    camera.CreateFocalLengthAttr(24.0)
    camera.CreateClippingRangeAttr(Gf.Vec2f(0.01, 1000.0))
    xform = UsdGeom.Xformable(camera.GetPrim())
    xform.ClearXformOpOrder()
    view = Gf.Matrix4d().SetLookAt(eye, target, Gf.Vec3d(0.0, 0.0, 1.0))
    xform.AddTransformOp().Set(view.GetInverse())
    return str(path)


def _disable_native_mouse_interaction(app) -> bool:
    """Give the benchmark's visible-mesh pull exclusive ownership of selection."""
    import carb.settings
    import omni.physx.bindings._physx as physx_bindings

    settings = carb.settings.get_settings()
    settings.set_bool(physx_bindings.SETTING_MOUSE_GRAB, False)
    settings.set_bool(physx_bindings.SETTING_MOUSE_INTERACTION_ENABLED, False)

    # Isaac Sim 5.1's mixed USD/Fabric transform selector can forward a handled
    # selection as None to the next manipulator.  prim.core then indexes that
    # None as a path type and raises KeyError(NoneType).  This environment uses
    # its own renderer raycast and never needs the native transform gizmo, so
    # clear stale selection and unsubscribe only that selector's stage listener.
    selector_disabled = False
    try:
        from omni.kit.manipulator.selector import get_manipulator_selector
        import omni.usd

        omni.usd.get_context().get_selection().set_selected_prim_paths([], False)
        selector = get_manipulator_selector("")
        if selector is not None:
            selector.destroy()
            selector_disabled = True
    except Exception as exc:
        print(f"could not disable native transform selector: {exc}")
    for _ in range(2):
        app.update()
    return selector_disabled


def _focus_viewport(camera_path: str) -> None:
    try:
        from omni.kit.viewport.utility import get_active_viewport

        viewport = get_active_viewport()
        if viewport is not None:
            viewport.set_active_camera(camera_path)
    except Exception as exc:
        print(f"could not focus inspection camera: {exc}")


class RobotContactDiagnostics:
    """Opt-in contact trace for locating unsafe task-pose intersections."""

    def __init__(self, stage):
        from pxr import PhysxSchema
        from pxr import UsdPhysics

        self._pairs: dict[tuple[str, str], dict] = {}
        self._active_pairs: set[tuple[str, str]] = set()
        self._subscription = None
        self._reported_bodies = 0
        self._phase = "settling"
        for prim in stage.Traverse():
            path = str(prim.GetPath())
            if path.startswith("/World/RBY1/") and prim.HasAPI(UsdPhysics.RigidBodyAPI):
                api = PhysxSchema.PhysxContactReportAPI.Apply(prim)
                api.CreateThresholdAttr().Set(0.0)
                self._reported_bodies += 1

    def subscribe(self) -> None:
        from omni.physx import get_physx_simulation_interface

        self._subscription = get_physx_simulation_interface().subscribe_contact_report_events(
            self._on_contacts
        )

    def set_phase(self, phase: str) -> None:
        self._phase = str(phase)

    @staticmethod
    def _vector(value) -> list[float]:
        return [float(value.x), float(value.y), float(value.z)]

    def _on_contacts(self, headers, data) -> None:
        import numpy as np
        from omni.physx.bindings._physx import ContactEventType
        from pxr import PhysicsSchemaTools

        for header in headers:
            collider0 = str(PhysicsSchemaTools.intToSdfPath(header.collider0))
            collider1 = str(PhysicsSchemaTools.intToSdfPath(header.collider1))
            pair_key = tuple(sorted((collider0, collider1)))
            pair = self._pairs.setdefault(
                pair_key,
                {
                    "collider0": pair_key[0],
                    "collider1": pair_key[1],
                    "events": 0,
                    "contacts": 0,
                    "minimum_separation_mm": float("inf"),
                    "maximum_impulse_ns": 0.0,
                    "maximum_impulse_vector_ns": [0.0, 0.0, 0.0],
                    "maximum_impulse_position_m": None,
                    "phases": [],
                    "active": False,
                },
            )
            pair["events"] += 1
            if header.type == ContactEventType.CONTACT_LOST:
                self._active_pairs.discard(pair_key)
                pair["active"] = False
                continue

            self._active_pairs.add(pair_key)
            pair["active"] = True
            if self._phase not in pair["phases"]:
                pair["phases"].append(self._phase)
            start = header.contact_data_offset
            stop = start + header.num_contact_data
            pair["contacts"] += header.num_contact_data
            for contact in data[start:stop]:
                impulse = np.asarray(self._vector(contact.impulse), dtype=np.float64)
                magnitude = float(np.linalg.norm(impulse))
                pair["minimum_separation_mm"] = min(
                    pair["minimum_separation_mm"],
                    float(contact.separation) * 1000.0,
                )
                if magnitude > pair["maximum_impulse_ns"]:
                    pair["maximum_impulse_ns"] = magnitude
                    pair["maximum_impulse_vector_ns"] = impulse.tolist()
                    pair["maximum_impulse_position_m"] = self._vector(
                        contact.position
                    )
    @property
    def summary(self) -> dict:
        pairs = sorted(
            self._pairs.values(),
            key=lambda item: item["maximum_impulse_ns"],
            reverse=True,
        )
        return {"reported_bodies": self._reported_bodies, "pairs": pairs}

    @property
    def active_summary(self) -> dict:
        """Return only contacts that have not emitted CONTACT_LOST."""
        pairs = sorted(
            (
                self._pairs[key]
                for key in self._active_pairs
                if key in self._pairs
            ),
            key=lambda item: item["maximum_impulse_ns"],
            reverse=True,
        )
        return {"reported_bodies": self._reported_bodies, "pairs": pairs}

    def reset_episode(self) -> None:
        """Discard cumulative and active contact history at an RL reset."""
        self._pairs.clear()
        self._active_pairs.clear()
        self._phase = "rl_reset"

    def close(self) -> None:
        self._subscription = None


def _blade_traversal_contact_step(
    contacting: bool,
    commanded_speed_m_s: float,
    previous_steps: int,
    *,
    minimum_speed_m_s: float = 0.01,
    required_steps: int = 2,
) -> tuple[int, bool]:
    """Gate manual blade traversal against idle contact and one-frame noise."""
    import math

    speed = float(commanded_speed_m_s)
    previous = int(previous_steps)
    minimum = float(minimum_speed_m_s)
    required = int(required_steps)
    if (
        not math.isfinite(speed)
        or not math.isfinite(minimum)
        or speed < 0.0
        or minimum < 0.0
        or previous < 0
        or required < 1
    ):
        raise ValueError("invalid blade-traversal contact gate state")
    if not contacting or speed < minimum:
        return 0, False
    steps = previous + 1
    return steps, steps >= required


class BladeContactMonitor:
    """Translate real knife contacts into cut work and safety evidence."""

    _BLOCKING_SAFETY_CATEGORIES = frozenset(
        {
            "neighbouring_vine_contact",
            "main_stem_contact",
            "non_target_organ_contact",
            "protected_structure_contact",
            "robot_self_contact",
        }
    )

    def __init__(
        self,
        stage,
        runtimes,
        robot_placement,
        parameters,
        *,
        interaction_cut_enabled: bool = False,
    ) -> None:
        from greenhouse_sim import cutting as cutting_module
        from greenhouse_sim import robot_hardware
        from greenhouse_sim import robot_kinematics
        import numpy as np
        from pxr import Gf
        from pxr import PhysxSchema
        from pxr import Usd
        from pxr import UsdGeom

        self._cutting = cutting_module
        self._np = np
        self._robot_kinematics = robot_kinematics
        self._cut_direction_local = robot_hardware.KNIFE_CUT_DIRECTION_LOCAL.copy()
        self._edge_axis_local = robot_hardware.KNIFE_EDGE_AXIS_LOCAL.copy()
        _, blade_half_extents = robot_hardware.knife_blade_box()
        self._edge_half_length_m = float(blade_half_extents[1])
        self._geometry_contact_tolerance_m = 0.0015
        self._stage = stage
        self._runtimes = {runtime.name: runtime for runtime in runtimes}
        self._gate = cutting_module.DirectionalCutGate(parameters)
        self._edge_path = robot_placement.knife_cutting_edge
        knife_root = self._edge_path.rsplit("/", 1)[0]
        self._blade_collider = f"{knife_root}/BladeCollision"
        self._arc_collider = f"{knife_root}/ArcCollision"
        self._targets = {}
        self._target_frames = {}
        self._target_colliders = {}
        self._interaction_colliders = {}
        self._collider_target_frames = {}
        self._collider_info = {}
        self._pending: list[dict] = []
        self._subscription = None
        self._previous_edge_centre = None
        self._commanded_edge_velocity = np.zeros(3, dtype=np.float64)
        self._active_target: str | None = None
        self._counterhold_provider = lambda _key: False
        self._violations: dict[tuple[str, str, str], dict] = {}
        self._physical_cuts: list[dict] = []
        self._latest_geometric_contact: dict | None = None
        self._interaction_cut_enabled = bool(interaction_cut_enabled)
        self._interaction_minimum_speed_m_s = 0.01
        self._interaction_required_steps = 2
        self._interaction_contact_steps: dict[str, int] = {}
        self._interaction_completed: set[str] = set()
        self._latest_interaction_contact: dict | None = None
        self._interaction_suppressed_steps = 0

        for runtime in runtimes:
            for info in runtime.rig.colliders:
                self._collider_info[info.path] = {
                    "vine": runtime.name,
                    "label": info.organ_label,
                    "role": info.role,
                }
                key = f"{runtime.name}/{info.organ_label}"
                if (
                    info.organ_label in runtime.rig.cut_joints
                    and info.role != "protected_main_stem"
                    and any(
                        marker in info.role
                        for marker in (
                            "foliage_grasp",
                            "petiole_grasp",
                            "petiole_cut_zone",
                        )
                    )
                ):
                    self._interaction_colliders[info.path] = {
                        "key": key,
                        "runtime": runtime,
                        "organ_label": info.organ_label,
                        "role": info.role,
                    }
                if "petiole_cut_zone" not in info.role:
                    continue
                junction = runtime.rig.junctions.get(info.organ_label)
                if junction is None:
                    continue
                self._target_colliders[info.path] = key
                if key not in self._targets:
                    self._targets[key] = (
                        runtime,
                        cutting_module.CutTarget(
                            key=key,
                            organ_label=info.organ_label,
                            centre_m=junction.cut_position_m,
                            axis=junction.cut_axis,
                            radius_m=junction.cut_radius_m,
                            cut_force_n=junction.cut_force_n,
                        ),
                    )
                    body_matrix = UsdGeom.Xformable(
                        stage.GetPrimAtPath(junction.child_path)
                    ).ComputeLocalToWorldTransform(Usd.TimeCode.Default())
                    self._target_frames[key] = {
                        "body": junction.child_path,
                        "centre_local": body_matrix.GetInverse().Transform(
                            Gf.Vec3d(*junction.cut_position_m.tolist())
                        ),
                        "axis_local": body_matrix.GetInverse().TransformDir(
                            Gf.Vec3d(*junction.cut_axis.tolist())
                        ),
                    }

                # Planning uses the live proximal junction frame above.  Cut
                # scoring follows the exact articulated capsule that produced
                # contact, with projection still expressed as cumulative stub
                # distance from the junction.  One shared frame for all links
                # cannot represent a bent petiole; overwriting it per link is
                # equally wrong because the final collider wins globally.
                virtual_centre, segment_axis, arc_start_m = (
                    runtime.rig.cut_segment_frame(info)
                )
                segment_link = next(
                    (
                        link
                        for link in runtime.rig.links
                        if link.organ == info.organ
                        and link.index == info.segment
                    ),
                    None,
                )
                if segment_link is None:
                    raise ValueError(
                        "cut-zone segment link is missing for collider: "
                        f"{info.path}"
                    )
                body_matrix = UsdGeom.Xformable(
                    stage.GetPrimAtPath(info.body_path)
                ).ComputeLocalToWorldTransform(Usd.TimeCode.Default())
                self._collider_target_frames[info.path] = {
                    "body": info.body_path,
                    "centre_local": body_matrix.GetInverse().Transform(
                        Gf.Vec3d(*virtual_centre.tolist())
                    ),
                    "axis_local": body_matrix.GetInverse().TransformDir(
                        Gf.Vec3d(*segment_axis.tolist())
                    ),
                    "radius_m": float(segment_link.radius),
                    "segment": info.segment,
                    "arc_start_m": arc_start_m,
                }

        ee_right = stage.GetPrimAtPath(f"{robot_placement.root_path}/ee_right")
        if not ee_right.IsValid():
            raise ValueError("right end-effector body is missing for blade contact reporting")
        report_api = PhysxSchema.PhysxContactReportAPI.Apply(ee_right)
        report_api.CreateThresholdAttr().Set(0.0)

    def add_safety_colliders(self, entries) -> None:
        for entry in entries:
            self._collider_info[entry.path] = {
                "vine": entry.vine_name,
                "label": entry.organ_label,
                "role": entry.role,
            }

    def set_active_target(self, vine_name: str, organ_label: str) -> None:
        self._active_target = f"{vine_name}/{organ_label}"

    def reset_episode(self, vine_name: str, organ_label: str) -> None:
        """Clear all cut, contact, and safety evidence between RL episodes."""
        self.set_active_target(vine_name, organ_label)
        self._gate.reset()
        self._pending.clear()
        self._previous_edge_centre = None
        self._commanded_edge_velocity = self._np.zeros(3, dtype=self._np.float64)
        self._violations.clear()
        self._physical_cuts.clear()
        self._latest_geometric_contact = None
        self._interaction_contact_steps.clear()
        self._interaction_completed.clear()
        self._latest_interaction_contact = None
        self._interaction_suppressed_steps = 0
        # Online-RL success always uses the strict bimanual benchmark path.
        self._interaction_cut_enabled = False

    def set_counterhold_provider(self, provider) -> None:
        """Supply verified physical-grasp state for rigid-tissue fracture."""
        self._counterhold_provider = provider

    def set_commanded_edge_velocity(self, velocity_m_s) -> None:
        """Record policy-commanded edge motion for traction separation."""
        velocity = self._np.asarray(velocity_m_s, dtype=self._np.float64)
        if velocity.shape != (3,) or not self._np.isfinite(velocity).all():
            raise ValueError("commanded edge velocity must be a finite three-vector")
        self._commanded_edge_velocity = velocity.copy()

    @property
    def interaction_cut_enabled(self) -> bool:
        return self._interaction_cut_enabled

    def set_interaction_cut_enabled(self, enabled: bool) -> None:
        """Enable direct manual traversal cuts without changing benchmark gates."""
        self._interaction_cut_enabled = bool(enabled)
        self._interaction_contact_steps.clear()

    def suppress_interaction_after_base_teleport(self, steps: int = 4) -> None:
        """Prevent a fixed-base teleport from looking like a knife stroke."""
        count = int(steps)
        if count < 1:
            raise ValueError("base-teleport suppression requires at least one step")
        self._previous_edge_centre = self.edge_centre_m.copy()
        self._commanded_edge_velocity = self._np.zeros(3, dtype=self._np.float64)
        self._interaction_contact_steps.clear()
        self._interaction_suppressed_steps = max(
            self._interaction_suppressed_steps, count
        )

    @property
    def edge_centre_m(self):
        """Return the live cutting-edge centre, including torso motion."""
        from pxr import Gf
        from pxr import Usd
        from pxr import UsdGeom

        matrix = UsdGeom.Xformable(
            self._stage.GetPrimAtPath(self._edge_path)
        ).ComputeLocalToWorldTransform(Usd.TimeCode.Default())
        return self._np.asarray(
            matrix.Transform(Gf.Vec3d(0.0)), dtype=self._np.float64
        )

    def _current_target(self, key: str, collider_path: str | None = None):
        from pxr import Usd
        from pxr import UsdGeom

        runtime, authored = self._targets[key]
        frame = (
            self._collider_target_frames[collider_path]
            if collider_path is not None
            else self._target_frames[key]
        )
        matrix = UsdGeom.Xformable(
            self._stage.GetPrimAtPath(frame["body"])
        ).ComputeLocalToWorldTransform(Usd.TimeCode.Default())
        centre = self._np.asarray(
            matrix.Transform(frame["centre_local"]), dtype=self._np.float64
        )
        axis = self._np.asarray(
            matrix.TransformDir(frame["axis_local"]).GetNormalized(),
            dtype=self._np.float64,
        )
        return runtime, self._cutting.CutTarget(
            key=authored.key,
            organ_label=authored.organ_label,
            centre_m=centre,
            axis=axis,
            radius_m=float(frame.get("radius_m", authored.radius_m)),
            cut_force_n=authored.cut_force_n,
        )

    @property
    def target_geometry(self) -> dict | None:
        key = self._active_target or ""
        if key not in self._targets:
            return None
        _, target = self._current_target(key)
        colliders = [
            path
            for path, key in self._target_colliders.items()
            if key == self._active_target
        ]
        return {
            "key": target.key,
            "centre_m": target.centre_m.copy(),
            "axis": target.axis.copy(),
            "radius_m": target.radius_m,
            "colliders": tuple(colliders),
        }

    @property
    def target_keys(self) -> tuple[str, ...]:
        """Return every severable petiole target authored for the live vines."""
        return tuple(sorted(self._targets))

    @property
    def active_cut_feedback(self) -> dict | None:
        """Return the latest physical contact load for closed-loop motion."""
        key = self._active_target or ""
        if key not in self._targets:
            return None
        _, target = self._current_target(key)
        progress = self._gate.progress_for(key)
        return {
            "target": key,
            "required_force_n": target.cut_force_n,
            "effective_force_n": progress.last_effective_force_n,
            "forward_speed_m_s": progress.last_forward_speed_m_s,
            "contact_valid": progress.last_contact_valid,
            "work_j": progress.work_j,
            "forward_travel_m": progress.forward_travel_m,
            "gap_steps": progress.gap_steps,
        }

    def tool_point_geometry(self, local_point_m) -> dict:
        """Return a knife-local point and tool axes in the live world frame."""
        from pxr import Gf
        from pxr import Usd
        from pxr import UsdGeom

        knife_root = self._edge_path.rsplit("/", 1)[0]
        matrix = UsdGeom.Xformable(
            self._stage.GetPrimAtPath(knife_root)
        ).ComputeLocalToWorldTransform(Usd.TimeCode.Default())
        point = self._np.asarray(
            matrix.Transform(Gf.Vec3d(*local_point_m)), dtype=self._np.float64
        )
        edge_axis = self._np.asarray(
            matrix.TransformDir(
                Gf.Vec3d(*self._edge_axis_local.tolist())
            ).GetNormalized(),
            dtype=self._np.float64,
        )
        cut_direction = self._np.asarray(
            matrix.TransformDir(
                Gf.Vec3d(*self._cut_direction_local.tolist())
            ).GetNormalized(),
            dtype=self._np.float64,
        )
        return {
            "point_m": point,
            "edge_axis": edge_axis,
            "cut_direction": cut_direction,
        }

    def target_path_geometry(self, stub_m: float) -> dict | None:
        """Return the live articulated centreline point/tangent at a stub."""
        key = self._active_target or ""
        if key not in self._targets:
            return None
        candidates = [
            (path, frame)
            for path, frame in self._collider_target_frames.items()
            if self._target_colliders.get(path) == key
        ]
        if not candidates:
            return None
        before = [
            item
            for item in candidates
            if float(item[1]["arc_start_m"]) <= float(stub_m) + 1e-9
        ]
        collider_path, frame = max(
            before or candidates,
            key=lambda item: float(item[1]["arc_start_m"]),
        )
        _, target = self._current_target(key, collider_path)
        point = target.centre_m + target.axis * float(stub_m)
        return {
            "key": key,
            "point_m": point,
            "axis": target.axis.copy(),
            "radius_m": target.radius_m,
            "collider": collider_path,
            "segment": int(frame["segment"]),
            "arc_start_m": float(frame["arc_start_m"]),
            "virtual_junction_m": target.centre_m.copy(),
        }

    def subscribe(self) -> None:
        from omni.physx import get_physx_simulation_interface

        self._subscription = get_physx_simulation_interface().subscribe_contact_report_events(
            self._on_contacts
        )

    def _vector(self, value):
        return self._np.asarray(
            [float(value.x), float(value.y), float(value.z)],
            dtype=self._np.float64,
        )

    def _inside_cutting_edge(self, point_m) -> bool:
        from pxr import Gf
        from pxr import Usd
        from pxr import UsdGeom

        prim = self._stage.GetPrimAtPath(self._edge_path)
        matrix = UsdGeom.Xformable(prim).ComputeLocalToWorldTransform(Usd.TimeCode.Default())
        local = self._np.asarray(
            matrix.GetInverse().Transform(Gf.Vec3d(*point_m.tolist())),
            dtype=self._np.float64,
        )
        return bool(self._np.all(self._np.abs(local) <= 0.60))

    def _on_contacts(self, headers, data) -> None:
        from pxr import PhysicsSchemaTools

        for header in headers:
            collider0 = str(PhysicsSchemaTools.intToSdfPath(header.collider0))
            collider1 = str(PhysicsSchemaTools.intToSdfPath(header.collider1))
            if self._blade_collider in (collider0, collider1):
                tool = "blade"
                other = collider1 if collider0 == self._blade_collider else collider0
            elif self._arc_collider in (collider0, collider1):
                tool = "arc"
                other = collider1 if collider0 == self._arc_collider else collider0
            else:
                continue

            start = header.contact_data_offset
            stop = start + header.num_contact_data
            for contact in data[start:stop]:
                point = self._vector(contact.position)
                impulse = self._vector(contact.impulse)
                # PhysX also emits contact-offset proximity points with
                # positive separation and exactly zero impulse. They remain in
                # RobotContactDiagnostics, but are not physical tool contact.
                if float(self._np.linalg.norm(impulse)) <= 1e-12:
                    continue
                self._pending.append(
                    {
                        "tool": tool,
                        "other": other,
                        "point": point,
                        "impulse": impulse,
                        "inside_edge": (
                            tool == "blade" and self._inside_cutting_edge(point)
                        ),
                        "source": "physx",
                    }
                )

    def _edge_kinematics(self, dt_s: float) -> tuple[np.ndarray, ...]:
        from pxr import Gf
        from pxr import Usd
        from pxr import UsdGeom

        matrix = UsdGeom.Xformable(
            self._stage.GetPrimAtPath(self._edge_path)
        ).ComputeLocalToWorldTransform(Usd.TimeCode.Default())
        centre = self._np.asarray(
            matrix.Transform(Gf.Vec3d(0.0)), dtype=self._np.float64
        )
        edge_axis = self._np.asarray(
            matrix.TransformDir(
                Gf.Vec3d(*self._edge_axis_local.tolist())
            ).GetNormalized(),
            dtype=self._np.float64,
        )
        cut_direction = self._np.asarray(
            matrix.TransformDir(
                Gf.Vec3d(*self._cut_direction_local.tolist())
            ).GetNormalized(),
            dtype=self._np.float64,
        )
        velocity = (
            self._np.zeros(3, dtype=self._np.float64)
            if self._previous_edge_centre is None
            else (centre - self._previous_edge_centre) / dt_s
        )
        self._previous_edge_centre = centre.copy()
        return centre, edge_axis, cut_direction, velocity

    def _geometric_counterheld_contact(
        self,
        centre,
        edge_axis,
        cut_direction,
        dt_s: float,
    ) -> tuple[str, dict] | None:
        """Model thin rigid-tissue reaction only for the grasp-held target."""
        key = self._active_target or ""
        if key not in self._targets:
            self._latest_geometric_contact = None
            return None

        edge_start = centre - edge_axis * self._edge_half_length_m
        edge_end = centre + edge_axis * self._edge_half_length_m
        nearest = None
        for collider_path, target_key in self._target_colliders.items():
            if target_key != key:
                continue
            runtime, target = self._current_target(key, collider_path)
            target_start = (
                target.centre_m
                - target.axis * self._gate.parameters.cut_zone_before_m
            )
            target_end = (
                target.centre_m
                + target.axis * self._gate.parameters.cut_zone_after_m
            )
            distance = self._robot_kinematics._segment_segment_distance(
                edge_start,
                edge_end,
                target_start,
                target_end,
            )
            candidate = (distance, collider_path, runtime, target)
            if nearest is None or candidate[0] < nearest[0]:
                nearest = candidate

        if nearest is None:
            self._latest_geometric_contact = None
            return None
        distance, collider_path, runtime, target = nearest
        counterhold_active = bool(self._counterhold_provider(key))
        reaction_force = _geometric_cut_reaction_force(
            distance,
            target.radius_m,
            target.cut_force_n,
            self._geometry_contact_tolerance_m,
            self._gate.parameters.force_cap_multiple,
        )
        stub_m = float(
            self._np.clip(
                self._np.dot(centre - target.centre_m, target.axis),
                -self._gate.parameters.cut_zone_before_m,
                self._gate.parameters.cut_zone_after_m,
            )
        )
        point = target.centre_m + target.axis * stub_m
        self._latest_geometric_contact = {
            "target": key,
            "collider": collider_path,
            "edge_segment_m": [edge_start.tolist(), edge_end.tolist()],
            "target_segment_m": [target_start.tolist(), target_end.tolist()],
            "clearance_to_centreline_m": float(distance),
            "contact_limit_m": float(
                target.radius_m + self._geometry_contact_tolerance_m
            ),
            "reaction_force_n": float(reaction_force),
            "counterhold_active": counterhold_active,
            "evidence_active": bool(counterhold_active and reaction_force > 0.0),
            "source": "counterheld_rigid_tissue_geometry",
        }
        if not counterhold_active or reaction_force <= 0.0:
            return None

        impulse = cut_direction * reaction_force * dt_s
        weight = max(float(self._np.linalg.norm(impulse)), 1e-12)
        return key, {
            "point_sum": weight * point,
            "weight": weight,
            "impulse": impulse,
            "collider_weights": {collider_path: weight},
            "sources": {"counterheld_rigid_tissue_geometry"},
        }

    def _record_violation(self, event: dict, dt_s: float) -> None:
        info = self._collider_info.get(event["other"])
        target_key = self._target_colliders.get(event["other"])
        interaction = self._interaction_colliders.get(event["other"])
        if target_key is None and interaction is not None:
            target_key = interaction["key"]
        if info is None:
            if event["other"].startswith("/World/RBY1/"):
                category = "robot_self_contact"
            else:
                category = "protected_structure_contact"
            vine = ""
            label = event["other"]
        else:
            vine = info["vine"]
            label = info["label"]
            if vine != (self._active_target or "").partition("/")[0]:
                category = "neighbouring_vine_contact"
            elif info["role"] == "protected_main_stem":
                category = "main_stem_contact"
            elif target_key != self._active_target:
                category = "non_target_organ_contact"
            elif event["tool"] == "arc":
                category = "support_arc_target_contact"
            else:
                category = "blade_face_target_contact"

        impulse = float(self._np.linalg.norm(event["impulse"]))
        force = impulse / max(dt_s, 1e-12)
        key = (category, event["tool"], event["other"])
        record = self._violations.setdefault(
            key,
            {
                "category": category,
                "tool": event["tool"],
                "collider": event["other"],
                "vine": vine,
                "organ": label,
                "events": 0,
                "maximum_impulse_ns": 0.0,
                "maximum_force_n": 0.0,
            },
        )
        record["events"] += 1
        record["maximum_impulse_ns"] = max(record["maximum_impulse_ns"], impulse)
        record["maximum_force_n"] = max(record["maximum_force_n"], force)

    def process(self, dt_s: float = 1.0 / 240.0) -> list[dict]:
        centre, edge_axis, cut_direction, velocity = self._edge_kinematics(dt_s)
        interaction_suppressed = self._interaction_suppressed_steps > 0
        if interaction_suppressed:
            self._interaction_suppressed_steps -= 1
        aggregates: dict[str, dict] = {}
        interaction_aggregates: dict[str, dict] = {}
        for event in self._pending:
            target_key = self._target_colliders.get(event["other"])
            interaction = self._interaction_colliders.get(event["other"])
            if (
                self._interaction_cut_enabled
                and not interaction_suppressed
                and event["tool"] == "blade"
                and interaction is not None
                and interaction["key"] not in self._interaction_completed
            ):
                direct = interaction_aggregates.setdefault(
                    interaction["key"],
                    {
                        **interaction,
                        "point_sum": self._np.zeros(3),
                        "weight": 0.0,
                        "collider_weights": {},
                        "sources": set(),
                    },
                )
                direct_weight = max(
                    float(self._np.linalg.norm(event["impulse"])), 1e-12
                )
                direct["point_sum"] += direct_weight * event["point"]
                direct["weight"] += direct_weight
                direct["collider_weights"][event["other"]] = (
                    direct["collider_weights"].get(event["other"], 0.0)
                    + direct_weight
                )
                direct["sources"].add(event.get("source", "physx"))
            if event["tool"] == "blade" and event["inside_edge"] and target_key is not None:
                aggregate = aggregates.setdefault(
                    target_key,
                    {
                        "point_sum": self._np.zeros(3),
                        "weight": 0.0,
                        "impulse": self._np.zeros(3),
                        "collider_weights": {},
                        "sources": set(),
                    },
                )
                weight = max(float(self._np.linalg.norm(event["impulse"])), 1e-12)
                aggregate["point_sum"] += weight * event["point"]
                aggregate["weight"] += weight
                aggregate["impulse"] += event["impulse"]
                aggregate["collider_weights"][event["other"]] = (
                    aggregate["collider_weights"].get(event["other"], 0.0)
                    + weight
                )
                aggregate["sources"].add(event.get("source", "physx"))
            else:
                self._record_violation(event, dt_s)
        self._pending.clear()

        geometric = self._geometric_counterheld_contact(
            centre,
            edge_axis,
            cut_direction,
            dt_s,
        )
        if geometric is not None:
            key, aggregate = geometric
            # A real edge callback remains the preferred evidence. The
            # geometry path only fills the thin-collider callback gap.
            aggregates.setdefault(key, aggregate)

        decisions = []
        contacted = set(aggregates)
        for key, aggregate in aggregates.items():
            dominant_collider = max(
                aggregate["collider_weights"],
                key=aggregate["collider_weights"].get,
            )
            runtime, target = self._current_target(key, dominant_collider)
            sample = self._cutting.BladeContactSample(
                point_m=aggregate["point_sum"] / aggregate["weight"],
                impulse_ns=aggregate["impulse"],
                edge_centre_m=centre,
                edge_axis=edge_axis,
                cutting_direction=cut_direction,
                edge_velocity_m_s=velocity,
                dt_s=dt_s,
                counterhold_active=bool(self._counterhold_provider(key)),
                commanded_edge_velocity_m_s=(
                    self._commanded_edge_velocity.copy()
                ),
            )
            decision = self._gate.observe(target, sample)
            if decision is not None:
                decisions.append(
                    {
                        "runtime": runtime,
                        "decision": decision,
                        "intended_target": key == self._active_target,
                        "contact_sources": sorted(aggregate["sources"]),
                    }
                )
        self._gate.finish_step(contacted)
        strict_decision_keys = {
            event["decision"].target_key for event in decisions
        }

        commanded_speed = float(
            self._np.linalg.norm(self._commanded_edge_velocity)
        )
        interaction_decisions = []
        contacted_interactions = set(interaction_aggregates)
        for key, aggregate in interaction_aggregates.items():
            if key in strict_decision_keys:
                self._interaction_contact_steps.pop(key, None)
                continue
            steps, ready = _blade_traversal_contact_step(
                True,
                commanded_speed,
                self._interaction_contact_steps.get(key, 0),
                minimum_speed_m_s=self._interaction_minimum_speed_m_s,
                required_steps=self._interaction_required_steps,
            )
            self._interaction_contact_steps[key] = steps
            dominant_collider = max(
                aggregate["collider_weights"],
                key=aggregate["collider_weights"].get,
            )
            latest = {
                "target": key,
                "collider": dominant_collider,
                "role": aggregate["role"],
                "point_m": (
                    aggregate["point_sum"] / aggregate["weight"]
                ).tolist(),
                "commanded_speed_m_s": commanded_speed,
                "contact_steps": steps,
                "required_steps": self._interaction_required_steps,
                "minimum_speed_m_s": self._interaction_minimum_speed_m_s,
                "ready": ready,
                "source": "physx_flat_blade_traversal",
            }
            self._latest_interaction_contact = latest
            if ready:
                interaction_decisions.append(
                    {
                        "runtime": aggregate["runtime"],
                        "interaction_cut": True,
                        "target_key": key,
                        "organ_label": aggregate["organ_label"],
                        "collider": dominant_collider,
                        "point_m": list(latest["point_m"]),
                        "commanded_speed_m_s": commanded_speed,
                        "contact_steps": steps,
                        "intended_target": key == self._active_target,
                        "contact_sources": sorted(aggregate["sources"]),
                    }
                )
        for key in list(self._interaction_contact_steps):
            if key in contacted_interactions:
                continue
            steps, _ = _blade_traversal_contact_step(
                False,
                commanded_speed,
                self._interaction_contact_steps[key],
                minimum_speed_m_s=self._interaction_minimum_speed_m_s,
                required_steps=self._interaction_required_steps,
            )
            if steps:
                self._interaction_contact_steps[key] = steps
            else:
                self._interaction_contact_steps.pop(key, None)
        decisions.extend(interaction_decisions)
        return decisions

    def record_cut(self, event: dict) -> None:
        self._physical_cuts.append(event)
        if event.get("interaction_cut"):
            self._interaction_completed.add(event["target_key"])
            self._interaction_contact_steps.pop(event["target_key"], None)

    @property
    def blocking_safety_violations(self) -> list[dict]:
        return [
            dict(record)
            for record in self._violations.values()
            if record["category"] in self._BLOCKING_SAFETY_CATEGORIES
        ]

    @property
    def safety_clear(self) -> bool:
        return not self.blocking_safety_violations

    @property
    def summary(self) -> dict:
        active_target = (
            self._current_target(self._active_target)[1]
            if self._active_target in self._targets
            else None
        )
        return {
            "model": (
                "directional leading-edge force/work gate with "
                "counterheld rigid-tissue reaction + force/work fracture"
            ),
            "cutting_edge": self._edge_path,
            "physical_blade_collider": self._blade_collider,
            "active_target": self._active_target,
            "active_target_geometry": (
                {
                    "centre_m": active_target.centre_m.tolist(),
                    "axis": active_target.axis.tolist(),
                    "radius_m": active_target.radius_m,
                    "cut_force_n": active_target.cut_force_n,
                }
                if active_target is not None
                else None
            ),
            "targets": len(self._targets),
            "parameters": dataclasses.asdict(self._gate.parameters),
            "progress": self._gate.summary(),
            "physical_cuts": list(self._physical_cuts),
            "latest_geometric_contact": self._latest_geometric_contact,
            "interaction_cut": {
                "enabled": self._interaction_cut_enabled,
                "model": (
                    "moving flat-blade contact severs the associated pre-authored "
                    "branch joint; never benchmark-valid"
                ),
                "eligible_colliders": len(self._interaction_colliders),
                "minimum_speed_m_s": self._interaction_minimum_speed_m_s,
                "required_consecutive_steps": self._interaction_required_steps,
                "suppressed_steps_remaining": self._interaction_suppressed_steps,
                "latest_contact": self._latest_interaction_contact,
                "completed_targets": sorted(self._interaction_completed),
            },
            "safety_clear": self.safety_clear,
            "blocking_safety_violations": sorted(
                self.blocking_safety_violations,
                key=lambda item: item["maximum_impulse_ns"],
                reverse=True,
            ),
            "safety_violations": sorted(
                self._violations.values(),
                key=lambda item: item["maximum_impulse_ns"],
                reverse=True,
            ),
        }

    def close(self) -> None:
        self._subscription = None


_NON_CAPSULE_GRASP_PROXY_RADIUS_M = 0.008


class LeftGraspManager:
    """Drive the retained left tongs and hold an orphan branch after cutting."""

    def __init__(
        self,
        stage,
        runtimes,
        robot_placement,
        task_parameters,
        *,
        open_width_m: float = 0.050,
        close_overtravel_m: float = 0.006,
    ) -> None:
        from greenhouse_sim import deleaf_task as task_module
        import numpy as np
        from pxr import Gf
        from pxr import PhysxSchema
        from pxr import Sdf
        from pxr import Usd
        from pxr import UsdGeom
        from pxr import UsdPhysics

        self._task_module = task_module
        self._np = np
        self._Gf = Gf
        self._Sdf = Sdf
        self._Usd = Usd
        self._UsdGeom = UsdGeom
        self._UsdPhysics = UsdPhysics
        self._stage = stage
        self._runtimes = {runtime.name: runtime for runtime in runtimes}
        self._root_path = robot_placement.root_path
        self._task_parameters = task_parameters
        self._open_width_m = float(open_width_m)
        self._close_overtravel_m = float(close_overtravel_m)
        self._close_requested = False
        self._requested_openness = 1.0
        self._requested_finger_openness = {
            "left_finger_1": 1.0,
            "left_finger_2": 1.0,
        }
        # A pinch is eligible only near the mechanically closed position. The
        # previous 0.95 threshold accepted a branch while the jaws were almost
        # fully open and made visual grasp placement inherently inaccurate.
        self._close_request_threshold = 0.20
        self._release_threshold = 0.65
        self._pending: list[dict] = []
        self._subscription = None
        self._active_target: str | None = None
        self._task = None
        self._grasp_colliders: dict[str, dict] = {}
        self._grasp_colliders_for_key: dict[str, list[str]] = {}
        self._grasp_collider_for_key: dict[str, str] = {}
        self._grasp_bodies: dict[str, str] = {}
        self._joint_paths: dict[str, str] = {}
        self._orphan_paths: dict[str, list[str]] = {}
        self._active_joint_key: str | None = None
        self._active_grasp_body: str | None = None
        self._active_grasp_collider: str | None = None
        self._active_grasp_point_local = None
        self._cut_grasp_position = None
        self._previous_orphan_centroid = None
        self._latest_orphan_state = None
        self._latest_finger_contact: dict | None = None
        self._current_finger_contact: dict | None = None
        self._finger_contact_serial = 0
        self._latest_geometric_jaw: dict | None = None
        self._held_branch_palm_filtered_pairs: list[
            tuple[str, str]
        ] = []
        self._structural_counterhold_required = False

        self._finger_colliders = {
            f"{self._root_path}/ee_finger_l1/restored_collisions/contact_proxy":
                "left_finger_1",
            f"{self._root_path}/ee_finger_l2/restored_collisions/contact_proxy":
                "left_finger_2",
        }
        for link in ("ee_finger_l1", "ee_finger_l2"):
            prim = stage.GetPrimAtPath(f"{self._root_path}/{link}")
            report_api = PhysxSchema.PhysxContactReportAPI.Apply(prim)
            report_api.CreateThresholdAttr().Set(0.0)

        grasp_scope = Sdf.Path(
            f"{self._root_path}/ee_left/BenchmarkGrasps"
        )
        UsdGeom.Scope.Define(stage, grasp_scope)
        for runtime in runtimes:
            for info in runtime.rig.colliders:
                key = f"{runtime.name}/{info.organ_label}"
                if (
                    "grasp" not in info.role
                    and "petiole_cut_zone" not in info.role
                ):
                    continue
                self._grasp_colliders[info.path] = {
                    'radius_m': float(
                        UsdGeom.Capsule(
                            stage.GetPrimAtPath(info.path)
                        ).GetRadiusAttr().Get()
                        or _NON_CAPSULE_GRASP_PROXY_RADIUS_M
                    ),
                    "key": key,
                    "vine": runtime.name,
                    "organ": info.organ_label,
                    "body": info.body_path,
                    "collider": info.path,
                    "segment": int(info.segment),
                    "role": info.role,
                }
                self._grasp_colliders_for_key.setdefault(key, []).append(
                    info.path
                )
                if (
                    key not in self._grasp_collider_for_key
                    or "petiole_grasp" in info.role
                ):
                    self._grasp_collider_for_key[key] = info.path
                    self._grasp_bodies[key] = info.body_path
            for label in runtime.rig.junctions:
                key = f"{runtime.name}/{label}"
                body = self._grasp_bodies.get(key)
                if body is None:
                    continue
                safe_name = f"{runtime.name}_{label}".replace("-", "_")
                joint_path = str(grasp_scope.AppendChild(safe_name))
                joint = UsdPhysics.FixedJoint.Define(stage, joint_path)
                body0_path = f"{self._root_path}/ee_left"
                joint.CreateBody0Rel().SetTargets([body0_path])
                joint.CreateBody1Rel().SetTargets([body])
                body0_matrix = UsdGeom.Xformable(
                    stage.GetPrimAtPath(body0_path)
                ).ComputeLocalToWorldTransform(Usd.TimeCode.Default())
                body1_matrix = UsdGeom.Xformable(
                    stage.GetPrimAtPath(body)
                ).ComputeLocalToWorldTransform(Usd.TimeCode.Default())
                anchor = body1_matrix.ExtractTranslation()
                joint.CreateLocalPos0Attr().Set(
                    Gf.Vec3f(body0_matrix.GetInverse().Transform(anchor))
                )
                joint.CreateLocalPos1Attr().Set(Gf.Vec3f(0.0))
                relative = (
                    body0_matrix.ExtractRotationQuat().GetInverse()
                    * body1_matrix.ExtractRotationQuat()
                )
                joint.CreateLocalRot0Attr().Set(Gf.Quatf(relative))
                joint.CreateLocalRot1Attr().Set(Gf.Quatf(1.0))
                joint.CreateExcludeFromArticulationAttr(defaultValue=True)
                joint.CreateJointEnabledAttr(defaultValue=False)
                self._joint_paths[key] = joint_path

                organ_index = runtime.organ_indices[label]
                descendants = set(runtime.plant.descendants_of(organ_index))
                self._orphan_paths[key] = [
                    link.path
                    for link in runtime.rig.links
                    if link.organ in descendants
                ]

        self._finger_drives = (
            (
                UsdPhysics.DriveAPI.Get(
                    stage.GetPrimAtPath(
                        f"{self._root_path}/joints/gripper_finger_l1"
                    ),
                    "linear",
                ),
                -self._open_width_m,
            ),
            (
                UsdPhysics.DriveAPI.Get(
                    stage.GetPrimAtPath(
                        f"{self._root_path}/joints/gripper_finger_l2"
                    ),
                    "linear",
                ),
                self._open_width_m,
            ),
        )
        if not all(drive for drive, _ in self._finger_drives):
            raise ValueError("left gripper linear drives are missing")
        self._finger_drive_configuration = {
            "type": "force",
            "stiffness_n_m": 800.0,
            "damping_n_s_m": 10.0,
            "maximum_force_n": 40.0,
        }
        for drive, _ in self._finger_drives:
            drive.CreateTypeAttr(self._finger_drive_configuration["type"])
            drive.CreateStiffnessAttr(
                self._finger_drive_configuration["stiffness_n_m"]
            )
            drive.CreateDampingAttr(
                self._finger_drive_configuration["damping_n_s_m"]
            )
            drive.CreateMaxForceAttr(
                self._finger_drive_configuration["maximum_force_n"]
            )
        self._set_finger_targets(opened=True)

    def _set_finger_openness_pair(
        self,
        finger_1_openness: float,
        finger_2_openness: float,
    ) -> None:
        for (drive, open_target), openness in zip(
            self._finger_drives,
            (finger_1_openness, finger_2_openness),
        ):
            closed_target = (
                -self._np.sign(open_target) * self._close_overtravel_m
            )
            target = closed_target + openness * (open_target - closed_target)
            drive.CreateTargetPositionAttr(float(target))
            drive.CreateTargetVelocityAttr(0.0)

    def _set_finger_openness(self, openness: float) -> None:
        self._set_finger_openness_pair(openness, openness)

    def _set_finger_targets(self, *, opened: bool) -> None:
        self._set_finger_openness(1.0 if opened else 0.0)

    def set_active_target(self, vine_name: str, organ_label: str) -> None:
        key = f"{vine_name}/{organ_label}"
        if key not in self._joint_paths:
            return
        if self._active_target == key:
            return
        if self._task is not None and self._task.phase is not self._task_module.Phase.SEEK_GRASP:
            return
        self._active_target = key
        self._task = self._task_module.BimanualDeleafTask(
            vine_name,
            organ_label,
            self._task_parameters,
        )

    def reset_episode(self, vine_name: str, organ_label: str) -> None:
        """Open the fingers and create a fresh strict bimanual task."""
        key = f"{vine_name}/{organ_label}"
        if key not in self._joint_paths:
            raise ValueError(f"target is not graspable: {key}")
        if self._active_joint_key is not None:
            self._set_joint_enabled(self._active_joint_key, False)
        self._set_held_branch_palm_collision_filter(False)
        self._active_joint_key = None
        self._active_grasp_body = None
        self._active_grasp_collider = None
        self._active_grasp_point_local = None
        self._cut_grasp_position = None
        self._previous_orphan_centroid = None
        self._latest_orphan_state = None
        self._latest_finger_contact = None
        self._current_finger_contact = None
        self._latest_geometric_jaw = None
        self._pending.clear()
        self._active_target = key
        self._task = self._task_module.BimanualDeleafTask(
            vine_name,
            organ_label,
            self._task_parameters,
        )
        self._requested_openness = 1.0
        self._requested_finger_openness = {
            "left_finger_1": 1.0,
            "left_finger_2": 1.0,
        }
        self._close_requested = False
        self._set_finger_targets(opened=True)

    @property
    def target_candidates(self) -> list[dict]:
        """Return live physical colliders eligible for the selected grasp."""
        from pxr import Gf

        key = self._active_target or ""
        candidates = []
        for path in self._grasp_colliders_for_key.get(key, ()):
            info = self._grasp_colliders[path]
            # Foliage proxies are valid physical pinch contacts, but automated
            # IK remains benchmarked against the repeatable petiole corridor.
            if info["role"] == "foliage_grasp":
                continue
            body_matrix = self._body_matrix(info["body"])
            collider_matrix = self._body_matrix(path)
            candidates.append(
                {
                    **info,
                    "centre_m": self._np.asarray(
                        collider_matrix.ExtractTranslation(), dtype=self._np.float64
                    ),
                    "axis": self._np.asarray(
                        body_matrix.TransformDir(Gf.Vec3d(0.0, 0.0, 1.0)).GetNormalized(),
                        dtype=self._np.float64,
                    ),
                    "preferred": path == self._grasp_collider_for_key.get(key),
                }
            )
        return candidates

    def set_planned_grasp_collider(self, collider_path: str) -> None:
        """Plan against one eligible collider; opposed contact chooses the final body."""
        info = self._grasp_colliders.get(collider_path)
        if info is None or info["key"] != self._active_target:
            raise ValueError(f"collider is not eligible for active target: {collider_path}")
        key = info["key"]
        self._grasp_collider_for_key[key] = collider_path
        self._grasp_bodies[key] = info["body"]

    @property
    def target_geometry(self) -> dict | None:
        from pxr import Gf

        key = self._active_target or ""
        path = (
            self._active_grasp_collider
            or self._grasp_collider_for_key.get(key)
        )
        if path is None:
            return None
        body = self._active_grasp_body or self._grasp_bodies[key]
        matrix = self._body_matrix(body)
        centre = (
            self._np.asarray(
                matrix.Transform(self._active_grasp_point_local),
                dtype=self._np.float64,
            )
            if self._active_grasp_point_local is not None
            else self._np.asarray(
                self._body_matrix(path).ExtractTranslation(),
                dtype=self._np.float64,
            )
        )
        axis = self._np.asarray(
            matrix.TransformDir(Gf.Vec3d(0.0, 0.0, 1.0)).GetNormalized(),
            dtype=self._np.float64,
        )
        tool_local_point = None
        if self._active_grasp_point_local is not None:
            ee_inverse = self._body_matrix(
                f"{self._root_path}/ee_left"
            ).GetInverse()
            tool_local_point = self._np.asarray(
                ee_inverse.Transform(Gf.Vec3d(*centre.tolist())),
                dtype=self._np.float64,
            )
        physics_organ = path.partition("/Link_")[0]
        organ_prim = self._stage.GetPrimAtPath(physics_organ)
        organ_colliders = tuple(
            str(prim.GetPath())
            for prim in self._Usd.PrimRange(organ_prim)
            if prim.GetName() == "Collider"
        )
        orphan_colliders = tuple(
            str(prim.GetPath())
            for link_path in self._orphan_paths.get(key, ())
            for prim in self._Usd.PrimRange(
                self._stage.GetPrimAtPath(link_path)
            )
            if prim.GetName() == "Collider"
        )
        branch_contact_colliders = tuple(
            self._grasp_colliders_for_key.get(key, ())
        )
        return {
            'radius_m': float(
                self._grasp_colliders[path]['radius_m']
            ),
            "key": key,
            "collider": path,
            "colliders": tuple(
                organ_colliders or (path,)
            ),
            # The selected petiole and all of its descendants form the branch
            # that the left fingers are expected to handle and remove. Keep
            # this separate from ``colliders``: the wrist camera and bracket
            # must still clear the branch, while finger contact with it is an
            # intended task interaction rather than a neighbouring-organ hit.
            "orphan_colliders": tuple(
                dict.fromkeys(
                    orphan_colliders
                    + organ_colliders
                    + branch_contact_colliders
                    + (path,)
                )
            ),
            "body": body,
            "centre_m": centre,
            "axis": axis,
            "tool_local_point_m": tool_local_point,
        }

    @property
    def task_succeeded(self) -> bool:
        return bool(self._task is not None and self._task.succeeded)

    @property
    def task_phase(self) -> str | None:
        return self._task.phase.value if self._task is not None else None

    def holds_target(self, key: str) -> bool:
        """Report a live, opposed-finger physical hold on exactly ``key``."""
        return bool(
            key == self._active_target
            and self._active_joint_key == key
            and self._task is not None
            and self._task.grasp_active
        )

    @property
    def latest_finger_contact(self) -> dict | None:
        """Return the latest graspable branch touched by either left finger."""
        return (
            None
            if self._latest_finger_contact is None
            else dict(self._latest_finger_contact)
        )

    @property
    def current_finger_contact(self) -> dict | None:
        """Return target contact observed during the current physics step."""
        return (
            None
            if self._current_finger_contact is None
            else dict(self._current_finger_contact)
        )

    @property
    def target_capture_geometry(self) -> dict | None:
        """Return selected structural tissue currently between the open jaws."""
        return self.capture_geometry()

    def capture_geometry(self, body_path: str | None = None) -> dict | None:
        """Return structural tissue in the jaw, optionally locked to one body."""
        candidates = []
        for path in self._grasp_colliders_for_key.get(
            self._active_target or "", ()
        ):
            info = self._grasp_colliders[path]
            if body_path is not None and info["body"] != body_path:
                continue
            if info["role"] not in {
                "petiole_grasp",
                "petiole_cut_zone",
            }:
                continue
            geometry = self._grasp_collider_geometry(path)
            if geometry is None or not _open_jaw_capture_corridor_overlap(
                geometry["minimum_ee_m"],
                geometry["maximum_ee_m"],
            ):
                continue
            candidates.append(
                (
                    geometry["distance_to_jaw_centre_m"],
                    path,
                    info,
                    geometry,
                )
            )
        if not candidates:
            return None
        _, path, info, geometry = min(
            candidates, key=lambda item: item[0]
        )
        return {
            "key": info["key"],
            "collider": path,
            "body": info["body"],
            "role": info["role"],
            "minimum_ee_m": geometry["minimum_ee_m"].tolist(),
            "maximum_ee_m": geometry["maximum_ee_m"].tolist(),
            "anchor_ee_m": geometry["anchor_ee_m"].tolist(),
            "anchor_world_m": geometry["anchor_world_m"].tolist(),
            "distance_to_jaw_centre_m": geometry[
                "distance_to_jaw_centre_m"
            ],
        }

    @property
    def close_requested(self) -> bool:
        """Return whether the measured physical aperture requests a pinch."""
        return self._close_requested

    def subscribe(self) -> None:
        from omni.physx import get_physx_simulation_interface

        self._subscription = get_physx_simulation_interface().subscribe_contact_report_events(
            self._on_contacts
        )

    def _vector(self, value):
        return self._np.asarray(
            [float(value.x), float(value.y), float(value.z)],
            dtype=self._np.float64,
        )

    def _on_contacts(self, headers, data) -> None:
        from pxr import PhysicsSchemaTools

        for header in headers:
            collider0 = str(PhysicsSchemaTools.intToSdfPath(header.collider0))
            collider1 = str(PhysicsSchemaTools.intToSdfPath(header.collider1))
            if collider0 in self._finger_colliders:
                finger = self._finger_colliders[collider0]
                other = collider1
            elif collider1 in self._finger_colliders:
                finger = self._finger_colliders[collider1]
                other = collider0
            else:
                continue
            target = self._grasp_colliders.get(other)
            if target is None:
                continue
            start = header.contact_data_offset
            stop = start + header.num_contact_data
            for contact in data[start:stop]:
                impulse = self._vector(contact.impulse)
                # CONTACT_LOST/contact-offset records can carry the same
                # collider pair with exactly zero load. They must not replace
                # the latest physical pinch or count toward grasp persistence.
                if float(self._np.linalg.norm(impulse)) <= 1e-12:
                    continue
                self._pending.append(
                    {
                        **target,
                        "finger": finger,
                        "point": self._vector(contact.position),
                        "impulse": impulse,
                        "source": "physx",
                    }
                )

    def _release_active_grasp(self) -> None:
        if self._active_joint_key is None or self._task is None:
            return
        self._task.observe_release()
        self._previous_orphan_centroid = None
        self._latest_orphan_state = None
        self._set_joint_enabled(self._active_joint_key, False)
        self._active_joint_key = None
        self._active_grasp_body = None
        self._active_grasp_collider = None
        self._active_grasp_point_local = None

    def request_openness(self, openness: float) -> None:
        """Track the measured physical aperture and preserve contact semantics."""
        self.request_finger_openness(openness, openness)

    def request_finger_openness(
        self,
        finger_1_openness: float,
        finger_2_openness: float,
    ) -> None:
        """Set each jaw independently while preserving strict grasp semantics."""
        values = (
            float(finger_1_openness),
            float(finger_2_openness),
        )
        if (
            not all(self._np.isfinite(value) for value in values)
            or not all(0.0 <= value <= 1.0 for value in values)
        ):
            raise ValueError("left gripper openness must be between 0 and 1")
        openness = max(values)
        if (
            self._active_joint_key is not None
            and openness >= self._release_threshold
        ):
            self._release_active_grasp()
        self._requested_openness = openness
        self._requested_finger_openness = {
            "left_finger_1": values[0],
            "left_finger_2": values[1],
        }
        self._close_requested = openness <= self._close_request_threshold
        self._set_finger_openness_pair(*values)

    def request_close(self) -> None:
        self.request_openness(0.0)

    def request_open(self) -> None:
        self.request_openness(1.0)

    def require_structural_counterhold(self, required: bool = True) -> None:
        """Restrict automated counterhold to petiole tissue, not leaf proxies."""
        if self._active_joint_key is not None:
            raise RuntimeError("counterhold mode cannot change during an active grasp")
        self._structural_counterhold_required = bool(required)

    def _set_joint_enabled(self, key: str, enabled: bool) -> None:
        joint = self._UsdPhysics.Joint(
            self._stage.GetPrimAtPath(self._joint_paths[key])
        )
        joint.GetJointEnabledAttr().Set(bool(enabled))

    def _set_held_branch_palm_collision_filter(self, enabled: bool) -> None:
        """Prevent a fixed held branch from fighting its own palm contact."""
        if not enabled:
            for collider_path, palm_path in self._held_branch_palm_filtered_pairs:
                prim = self._stage.GetPrimAtPath(collider_path)
                if not prim.IsValid():
                    continue
                relation = self._UsdPhysics.FilteredPairsAPI.Apply(
                    prim
                ).CreateFilteredPairsRel()
                relation.RemoveTarget(self._Sdf.Path(palm_path))
            self._held_branch_palm_filtered_pairs.clear()
            return

        if self._held_branch_palm_filtered_pairs:
            return
        geometry = self.target_geometry
        if geometry is None:
            raise RuntimeError(
                "held branch geometry is unavailable for palm collision filtering"
            )
        pairs = _held_branch_palm_collision_filter_pairs(
            geometry.get("orphan_colliders", ()),
            self._root_path,
        )
        for collider_path, palm_path in pairs:
            collider = self._stage.GetPrimAtPath(collider_path)
            palm = self._stage.GetPrimAtPath(palm_path)
            if not collider.IsValid() or not palm.IsValid():
                raise RuntimeError(
                    "held branch palm collision filter references a missing prim: "
                    f"{collider_path} <-> {palm_path}"
                )
            relation = self._UsdPhysics.FilteredPairsAPI.Apply(
                collider
            ).CreateFilteredPairsRel()
            palm_target = self._Sdf.Path(palm_path)
            if palm_target in relation.GetTargets():
                continue
            relation.AddTarget(palm_target)
            self._held_branch_palm_filtered_pairs.append(
                (collider_path, palm_path)
            )

    def _body_matrix(self, path: str):
        from pxr import Usd

        return self._UsdGeom.Xformable(
            self._stage.GetPrimAtPath(path)
        ).ComputeLocalToWorldTransform(Usd.TimeCode.Default())

    def _body_position(self, path: str):
        return self._np.asarray(
            self._body_matrix(path).ExtractTranslation(),
            dtype=self._np.float64,
        )

    def _gripper_geometry(self, target_position) -> dict:
        """Report live finger contact volumes in the left-EE frame."""
        ee = self._body_matrix(f"{self._root_path}/ee_left")
        ee_inverse = ee.GetInverse()
        target_local = (
            self._np.asarray(
                ee_inverse.Transform(self._Gf.Vec3d(*target_position)),
                dtype=self._np.float64,
            ).tolist()
            if target_position is not None
            else None
        )
        fingers = {}
        for name in ("ee_finger_l1", "ee_finger_l2"):
            body_path = f"{self._root_path}/{name}"
            collider_path = f"{body_path}/restored_collisions/contact_proxy"
            body_world = self._body_matrix(body_path)
            collider_world = self._body_matrix(collider_path)
            corners = []
            for x in (-0.5, 0.5):
                for y in (-0.5, 0.5):
                    for z in (-0.5, 0.5):
                        world = collider_world.Transform(self._Gf.Vec3d(x, y, z))
                        corners.append(
                            self._np.asarray(
                                ee_inverse.Transform(world), dtype=self._np.float64
                            )
                        )
            corners = self._np.asarray(corners)
            fingers[name] = {
                "body_origin_ee_m": self._np.asarray(
                    ee_inverse.Transform(body_world.ExtractTranslation()),
                    dtype=self._np.float64,
                ).tolist(),
                "collider_min_ee_m": self._np.min(corners, axis=0).tolist(),
                "collider_max_ee_m": self._np.max(corners, axis=0).tolist(),
            }
        return {"target_position_ee_m": target_local, "fingers": fingers}

    def _grasp_collider_geometry(self, path: str) -> dict | None:
        """Return one target proxy's exact EE bounds and jaw anchor point."""
        prim = self._stage.GetPrimAtPath(path)
        if not prim.IsValid():
            return None
        ee = self._body_matrix(f"{self._root_path}/ee_left")
        ee_inverse = ee.GetInverse()
        collider_world = self._body_matrix(path)
        jaw_centre = self._np.asarray(
            [0.0, 0.0, -0.1025], dtype=self._np.float64
        )
        jaw_world = ee.Transform(self._Gf.Vec3d(*jaw_centre.tolist()))

        if prim.IsA(self._UsdGeom.Cube):
            size = float(self._UsdGeom.Cube(prim).GetSizeAttr().Get() or 2.0)
            half = 0.5 * size
            corners = []
            for x in (-half, half):
                for y in (-half, half):
                    for z in (-half, half):
                        world = collider_world.Transform(self._Gf.Vec3d(x, y, z))
                        corners.append(
                            self._np.asarray(
                                ee_inverse.Transform(world), dtype=self._np.float64
                            )
                        )
            local_jaw = collider_world.GetInverse().Transform(jaw_world)
            local_anchor = self._Gf.Vec3d(
                *self._np.clip(
                    self._np.asarray(local_jaw, dtype=self._np.float64),
                    -half,
                    half,
                ).tolist()
            )
            anchor_world = collider_world.Transform(local_anchor)
        elif prim.IsA(self._UsdGeom.Capsule):
            capsule = self._UsdGeom.Capsule(prim)
            height = float(capsule.GetHeightAttr().Get() or 0.0)
            radius = float(capsule.GetRadiusAttr().Get() or 0.0)
            endpoints = []
            for z in (-0.5 * height, 0.5 * height):
                world = collider_world.Transform(self._Gf.Vec3d(0.0, 0.0, z))
                endpoints.append(
                    self._np.asarray(
                        ee_inverse.Transform(world), dtype=self._np.float64
                    )
                )
            endpoints = self._np.asarray(endpoints)
            radius_point = collider_world.Transform(self._Gf.Vec3d(radius, 0.0, 0.0))
            origin = collider_world.Transform(self._Gf.Vec3d(0.0))
            radius_ee = float(
                self._np.linalg.norm(
                    self._np.asarray(ee_inverse.Transform(radius_point))
                    - self._np.asarray(ee_inverse.Transform(origin))
                )
            )
            minimum = self._np.min(endpoints, axis=0) - radius_ee
            maximum = self._np.max(endpoints, axis=0) + radius_ee
            direction = endpoints[1] - endpoints[0]
            denominator = float(self._np.dot(direction, direction))
            fraction = (
                0.0
                if denominator <= 1e-15
                else float(
                    self._np.clip(
                        self._np.dot(jaw_centre - endpoints[0], direction)
                        / denominator,
                        0.0,
                        1.0,
                    )
                )
            )
            centreline_ee = endpoints[0] + fraction * direction
            radial = jaw_centre - centreline_ee
            radial_distance = float(self._np.linalg.norm(radial))
            anchor_ee = (
                jaw_centre.copy()
                if radial_distance <= radius_ee
                else centreline_ee + radial * (radius_ee / radial_distance)
            )
            anchor_world = ee.Transform(self._Gf.Vec3d(*anchor_ee.tolist()))
            return {
                "minimum_ee_m": minimum,
                "maximum_ee_m": maximum,
                "anchor_world_m": self._np.asarray(
                    anchor_world, dtype=self._np.float64
                ),
                "anchor_ee_m": anchor_ee,
                "distance_to_jaw_centre_m": float(
                    self._np.linalg.norm(anchor_ee - jaw_centre)
                ),
            }
        else:
            return None

        corners = self._np.asarray(corners)
        anchor_ee = self._np.asarray(
            ee_inverse.Transform(anchor_world), dtype=self._np.float64
        )
        return {
            "minimum_ee_m": self._np.min(corners, axis=0),
            "maximum_ee_m": self._np.max(corners, axis=0),
            "anchor_world_m": self._np.asarray(
                anchor_world, dtype=self._np.float64
            ),
            "anchor_ee_m": anchor_ee,
            "distance_to_jaw_centre_m": float(
                self._np.linalg.norm(anchor_ee - jaw_centre)
            ),
        }

    def _geometric_jaw_events(self, dt_s: float) -> list[dict]:
        """Confirm that visible target geometry lies inside the closed jaws."""
        candidates = []
        for path, info in self._grasp_colliders.items():
            if (
                self._structural_counterhold_required
                and info["role"] == "foliage_grasp"
            ):
                continue
            geometry = self._grasp_collider_geometry(path)
            if geometry is None or not _closing_jaw_corridor_overlap(
                geometry["minimum_ee_m"],
                geometry["maximum_ee_m"],
                self._requested_openness,
                self._close_request_threshold,
            ):
                continue
            # The broad-phase AABB can overlap the channel while a rotated
            # foliage OBB does not. Its exact closest point must also lie in
            # the visible channel before a grasp can be synthesized.
            if not _closing_jaw_corridor_overlap(
                geometry["anchor_ee_m"],
                geometry["anchor_ee_m"],
                self._requested_openness,
                self._close_request_threshold,
            ):
                continue
            candidates.append(
                (
                    geometry["distance_to_jaw_centre_m"],
                    path,
                    info,
                    geometry,
                )
            )

        if not candidates:
            self._latest_geometric_jaw = {
                "evidence_active": False,
                "requested_openness": self._requested_openness,
                "source": "closing_jaw_geometry",
            }
            return []
        active_candidates = [
            candidate
            for candidate in candidates
            if candidate[2]["key"] == (self._active_target or "")
        ]
        # When the selected branch and incidental foliage overlap the closing
        # jaw channel, preserve target evidence for the task state machine.
        # The contact ledger still records and rejects protected non-target
        # collisions; a nearer leaf must not starve a valid target pinch.
        _, path, info, geometry = min(
            active_candidates or candidates,
            key=lambda item: item[0],
        )
        closure = 1.0 - self._requested_openness / self._close_request_threshold
        force_n = 4.0 + 20.0 * float(self._np.clip(closure, 0.0, 1.0))
        impulse_per_finger = 0.5 * force_n * dt_s
        self._latest_geometric_jaw = {
            "evidence_active": True,
            "key": info["key"],
            "collider": path,
            "collider_minimum_ee_m": geometry["minimum_ee_m"].tolist(),
            "collider_maximum_ee_m": geometry["maximum_ee_m"].tolist(),
            "anchor_world_m": geometry["anchor_world_m"].tolist(),
            "anchor_ee_m": geometry["anchor_ee_m"].tolist(),
            "distance_to_jaw_centre_m": geometry["distance_to_jaw_centre_m"],
            "requested_openness": self._requested_openness,
            "requested_finger_openness": dict(
                self._requested_finger_openness
            ),
            "modeled_force_n": force_n,
            "source": "closing_jaw_geometry",
        }
        events = []
        for finger, sign in (("left_finger_1", -1.0), ("left_finger_2", 1.0)):
            events.append(
                {
                    **info,
                    "finger": finger,
                    "point": geometry["anchor_world_m"].copy(),
                    "impulse": self._np.asarray(
                        [sign * impulse_per_finger, 0.0, 0.0],
                        dtype=self._np.float64,
                    ),
                    "source": "closing_jaw_geometry",
                }
            )
        return events

    def _activate_joint(
        self,
        key: str,
        point_m,
        body1_path: str,
        collider_path: str,
    ) -> None:
        joint = self._UsdPhysics.FixedJoint.Get(
            self._stage,
            self._joint_paths[key],
        )
        body0_path = f"{self._root_path}/ee_left"
        joint.GetBody1Rel().SetTargets([body1_path])
        body0 = self._body_matrix(body0_path)
        body1 = self._body_matrix(body1_path)
        point = self._Gf.Vec3d(*point_m.tolist())
        joint.GetLocalPos0Attr().Set(
            self._Gf.Vec3f(body0.GetInverse().Transform(point))
        )
        local_point = body1.GetInverse().Transform(point)
        joint.GetLocalPos1Attr().Set(self._Gf.Vec3f(local_point))
        child_rotation = body1.ExtractRotationQuat()
        relative = body0.ExtractRotationQuat().GetInverse() * child_rotation
        joint.GetLocalRot0Attr().Set(self._Gf.Quatf(relative))
        joint.GetLocalRot1Attr().Set(self._Gf.Quatf(1.0))
        self._active_joint_key = key
        self._active_grasp_body = body1_path
        self._active_grasp_collider = collider_path
        self._active_grasp_point_local = self._Gf.Vec3d(local_point)
        self._set_held_branch_palm_collision_filter(True)
        joint.GetJointEnabledAttr().Set(True)

    def notify_cut(self, event: dict) -> bool:
        if self._task is None:
            return False
        accepted = self._task.observe_cut(
            vine=event["vine"],
            organ=event["organ_label"],
            physical_blade=event.get("trigger") == "physical_blade",
            intended_target=bool(event.get("intended_target")),
            safe_path=bool(event.get("safety_clear", False)),
        )
        if accepted and self._active_joint_key is not None:
            self._cut_grasp_position = self._body_position(
                self._active_grasp_body
                or self._grasp_bodies[self._active_joint_key]
            )
        return accepted

    def process(self, dt_s: float = 1.0 / 240.0) -> None:
        if self._task is None:
            self._pending.clear()
            return
        self._task.advance()
        if self._close_requested and self._active_joint_key is None:
            self._pending.extend(self._geometric_jaw_events(dt_s))
        elif not self._close_requested:
            self._latest_geometric_jaw = None
        grouped: dict[tuple[str, str], dict] = {}
        for event in self._pending:
            aggregate = grouped.setdefault(
                (event["key"], event["body"]),
                {
                    "key": event["key"],
                    "vine": event["vine"],
                    "organ": event["organ"],
                    "body": event["body"],
                    "collider": event["collider"],
                    "role": event["role"],
                    "fingers": set(),
                    "impulse": 0.0,
                    "point_sum": self._np.zeros(3),
                    "weight": 0.0,
                    "sources": set(),
                },
            )
            magnitude = float(self._np.linalg.norm(event["impulse"]))
            aggregate["fingers"].add(event["finger"])
            aggregate["impulse"] += magnitude
            aggregate["point_sum"] += max(magnitude, 1e-12) * event["point"]
            aggregate["weight"] += max(magnitude, 1e-12)
            aggregate["sources"].add(event.get("source", "physx"))
        self._pending.clear()

        self._current_finger_contact = None
        if grouped:
            contacted = max(
                grouped.values(),
                key=lambda aggregate: (
                    {"left_finger_1", "left_finger_2"}.issubset(
                        aggregate["fingers"]
                    ),
                    aggregate["impulse"],
                ),
            )
            self._finger_contact_serial += 1
            self._latest_finger_contact = {
                "serial": self._finger_contact_serial,
                "key": contacted["key"],
                "vine": contacted["vine"],
                "organ": contacted["organ"],
                "body": contacted["body"],
                "collider": contacted["collider"],
                "role": contacted["role"],
                "fingers": sorted(contacted["fingers"]),
                "force_n": contacted["impulse"] / max(dt_s, 1e-12),
                "point_m": (
                    contacted["point_sum"] / max(contacted["weight"], 1e-12)
                ).tolist(),
                "sources": sorted(contacted["sources"]),
            }
            self._current_finger_contact = dict(
                self._latest_finger_contact
            )

        active_candidates = [
            aggregate
            for (key, _), aggregate in grouped.items()
            if key == (self._active_target or "")
            and (
                not self._structural_counterhold_required
                or aggregate["role"] != "foliage_grasp"
            )
        ]
        active = (
            max(
                active_candidates,
                key=lambda aggregate: (
                    {"left_finger_1", "left_finger_2"}.issubset(
                        aggregate["fingers"]
                    ),
                    aggregate["impulse"],
                ),
            )
            if active_candidates
            else None
        )
        if (
            self._close_requested
            and self._active_joint_key is None
            and active is not None
        ):
            established = self._task.observe_grasp(
                vine=active["vine"],
                organ=active["organ"],
                body_path=active["body"],
                finger_contacts=active["fingers"],
                force_n=active["impulse"] / max(dt_s, 1e-12),
            )
            if established and self._active_joint_key is None:
                point = active["point_sum"] / active["weight"]
                self._activate_joint(
                    self._active_target,
                    point,
                    active["body"],
                    active["collider"],
                )
        elif self._close_requested and self._active_joint_key is None:
            # Required grasp steps are consecutive physical-contact steps;
            # proximity reports or a contact gap must restart the sequence.
            planned = self._grasp_colliders.get(
                self._grasp_collider_for_key.get(self._active_target or "", "")
            )
            if planned is not None:
                self._task.observe_grasp(
                    vine=planned["vine"],
                    organ=planned["organ"],
                    body_path=planned["body"],
                    finger_contacts=set(),
                    force_n=0.0,
                )

        if self._active_joint_key is not None:
            self._task.observe_hold(grasp_active=True)
            if (
                self._cut_grasp_position is not None
                and self._task.phase
                in {
                    self._task_module.Phase.ORPHAN_RETAINED,
                    self._task_module.Phase.TRANSPORTED,
                }
            ):
                current = self._body_position(
                    self._active_grasp_body
                    or self._grasp_bodies[self._active_joint_key]
                )
                self._task.observe_transport(
                    float(self._np.linalg.norm(current - self._cut_grasp_position))
                )
        elif self._task.phase in {
            self._task_module.Phase.ORPHAN_RETAINED,
            self._task_module.Phase.TRANSPORTED,
        }:
            self._task.observe_hold(grasp_active=False)

        if self._task.phase is self._task_module.Phase.RELEASED:
            paths = self._orphan_paths.get(self._active_target or "", [])
            if paths:
                positions = _positions(self._stage, paths)
                centroid = self._np.mean(positions, axis=0)
                speed = 0.0
                if self._previous_orphan_centroid is not None:
                    speed = float(
                        self._np.linalg.norm(
                            centroid - self._previous_orphan_centroid
                        )
                        / dt_s
                    )
                self._previous_orphan_centroid = centroid.copy()
                floor = self._task.parameters.drop_zone_min_m[2]
                lowest = float(self._np.min(positions[:, 2]))
                floor_contact = bool(
                    lowest
                    <= floor + self._task.parameters.floor_tolerance_m
                )
                self._latest_orphan_state = {
                    "centroid_m": centroid.tolist(),
                    "speed_m_s": speed,
                    "lowest_height_m": lowest,
                    "floor_contact": floor_contact,
                    "body_count": len(paths),
                }
                self._task.observe_deposit(
                    centroid_m=centroid,
                    lowest_height_m=lowest,
                    speed_m_s=speed,
                    floor_contact=floor_contact,
                )
                if (
                    floor_contact
                    and speed <= self._task.parameters.maximum_drop_speed_m_s
                ):
                    self._set_held_branch_palm_collision_filter(False)

    @property
    def summary(self) -> dict:
        target_body = self._active_grasp_body
        planned_body = self._grasp_bodies.get(self._active_target or "")
        target_position = (
            self._body_position(target_body).tolist()
            if target_body is not None
            else None
        )
        left_ee_position = self._body_position(
            f"{self._root_path}/ee_left"
        ).tolist()
        target_distance_mm = (
            float(
                self._np.linalg.norm(
                    self._np.asarray(left_ee_position) - target_position
                )
                * 1000.0
            )
            if target_position is not None
            else None
        )
        return {
            "model": "visible closed-jaw corridor + opposed-finger fixed-joint grasp",
            "active_target": self._active_target,
            "planned_grasp_body": planned_body,
            "active_grasp_body": target_body,
            "active_grasp_position_m": target_position,
            "left_ee_position_m": left_ee_position,
            "left_ee_distance_to_grasp_mm": target_distance_mm,
            "gripper_geometry": self._gripper_geometry(target_position),
            "close_requested": self._close_requested,
            "requested_openness": self._requested_openness,
            "latest_finger_contact": self.latest_finger_contact,
            "current_finger_contact": self.current_finger_contact,
            "target_capture_geometry": self.target_capture_geometry,
            "latest_geometric_jaw": self._latest_geometric_jaw,
            "close_request_threshold": self._close_request_threshold,
            "active_joint": (
                self._joint_paths.get(self._active_joint_key)
                if self._active_joint_key is not None
                else None
            ),
            "graspable_targets": len(self._joint_paths),
            "target_candidates": [
                {
                    **{
                        key: value
                        for key, value in candidate.items()
                        if key not in {"centre_m", "axis"}
                    },
                    "centre_m": candidate["centre_m"].tolist(),
                    "axis": candidate["axis"].tolist(),
                }
                for candidate in self.target_candidates
            ],
            "finger_drive_configuration": dict(self._finger_drive_configuration),
            "finger_close_overtravel_m": self._close_overtravel_m,
            "structural_counterhold_required": (
                self._structural_counterhold_required
            ),
            "held_branch_palm_collision_filter": {
                "active": bool(self._held_branch_palm_filtered_pairs),
                "pairs": [
                    {
                        "foliage_collider": collider,
                        "palm_collider": palm,
                    }
                    for collider, palm in self._held_branch_palm_filtered_pairs
                ],
            },
            "orphan_state": self._latest_orphan_state,
            "task": self._task.summary if self._task is not None else None,
        }

    def close(self) -> None:
        self._subscription = None


def _apply_blade_cut_decisions(
    context,
    monitor: BladeContactMonitor,
    report: dict,
    report_path: pathlib.Path | None = None,
    grasp_manager: LeftGraspManager | None = None,
) -> list[dict]:
    applied = []
    for event in monitor.process():
        runtime = event["runtime"]
        if event.get("interaction_cut"):
            context.pause()
            try:
                record = runtime.severer.cut(
                    event["organ_label"],
                    trigger="blade_traversal_interaction",
                )
            except Exception as exc:
                report.setdefault("blade_cut_errors", []).append(
                    {
                        "target": event["target_key"],
                        "mode": "blade_traversal_interaction",
                        "error": str(exc),
                    }
                )
            else:
                persisted = {
                    **dataclasses.asdict(record),
                    "vine": runtime.name,
                    "interaction_cut": True,
                    "interaction_valid": True,
                    "benchmark_valid": False,
                    "benchmark_invalid_reason": (
                        "direct_interaction_not_bimanual_benchmark"
                    ),
                    "bimanual_sequence_valid": False,
                    "target_key": event["target_key"],
                    "intended_target": bool(event["intended_target"]),
                    "contact_collider": event["collider"],
                    "contact_point_m": list(event["point_m"]),
                    "commanded_speed_m_s": float(
                        event["commanded_speed_m_s"]
                    ),
                    "contact_steps": int(event["contact_steps"]),
                    "contact_sources": list(
                        event.get("contact_sources", ())
                    ),
                    "topology_note": (
                        "contact severs the foliage/petiole proxy's associated "
                        "pre-authored SubStem joint; the mesh is not split at "
                        "the arbitrary contact point"
                    ),
                }
                report.setdefault("blade_traversal_cuts", []).append(
                    persisted
                )
                monitor.record_cut(persisted)
                applied.append(persisted)
            finally:
                context.play()
            continue
        decision = event["decision"]
        context.pause()
        try:
            record = runtime.severer.cut(
                decision.organ_label,
                decision=decision,
            )
        except Exception as exc:
            report.setdefault("blade_cut_errors", []).append(
                {
                    "target": decision.target_key,
                    "error": str(exc),
                }
            )
        else:
            persisted = {
                **dataclasses.asdict(record),
                "vine": runtime.name,
                "intended_target": bool(event["intended_target"]),
                "contact_sources": list(event.get("contact_sources", ())),
                "safety_clear": monitor.safety_clear,
                "blocking_safety_violations": monitor.blocking_safety_violations,
            }
            bimanual_valid = (
                grasp_manager.notify_cut(persisted)
                if grasp_manager is not None
                else False
            )
            persisted["bimanual_sequence_valid"] = bimanual_valid
            persisted["benchmark_valid"] = bool(
                event["intended_target"]
                and persisted["safety_clear"]
                and bimanual_valid
            )
            report.setdefault("physical_blade_cuts", []).append(persisted)
            if not event["intended_target"]:
                report.setdefault("benchmark_failures", []).append(
                    {
                        "reason": "unintended_organ_cut",
                        "vine": runtime.name,
                        "organ": decision.organ_label,
                    }
                )
            if not persisted["safety_clear"]:
                report.setdefault("benchmark_failures", []).append(
                    {
                        "reason": "protected_contact_before_cut",
                        "vine": runtime.name,
                        "organ": decision.organ_label,
                        "violations": persisted[
                            "blocking_safety_violations"
                        ],
                    }
                )
            monitor.record_cut(persisted)
            applied.append(persisted)
        finally:
            context.play()
    if applied or report.get("blade_cut_errors"):
        report["blade_cutting"] = monitor.summary
        if grasp_manager is not None:
            report["bimanual_task"] = grasp_manager.summary
        if report_path is not None:
            _emit(report, report_path)
    return applied


def _closing_jaw_corridor_overlap(
    bounds_minimum_ee_m,
    bounds_maximum_ee_m,
    openness: float,
    maximum_openness: float = 0.20,
) -> bool:
    """Return whether geometry crosses the visible channel of near-closed jaws."""
    import numpy as np

    minimum = np.asarray(bounds_minimum_ee_m, dtype=np.float64)
    maximum = np.asarray(bounds_maximum_ee_m, dtype=np.float64)
    if (
        minimum.shape != (3,)
        or maximum.shape != (3,)
        or not np.isfinite(minimum).all()
        or not np.isfinite(maximum).all()
        or np.any(minimum > maximum)
        or not 0.0 <= float(openness) <= float(maximum_openness)
    ):
        return False
    channel_minimum = np.asarray([-0.0015, -0.0180, -0.1340])
    channel_maximum = np.asarray([0.0015, 0.0180, -0.0710])
    return bool(
        np.all(maximum >= channel_minimum)
        and np.all(minimum <= channel_maximum)
    )


def _open_jaw_capture_corridor_overlap(
    bounds_minimum_ee_m,
    bounds_maximum_ee_m,
    half_opening_m: float = 0.052,
) -> bool:
    """Return whether target tissue lies between the open finger envelopes."""
    import numpy as np

    minimum = np.asarray(bounds_minimum_ee_m, dtype=np.float64)
    maximum = np.asarray(bounds_maximum_ee_m, dtype=np.float64)
    half_opening = float(half_opening_m)
    if (
        minimum.shape != (3,)
        or maximum.shape != (3,)
        or not np.isfinite(minimum).all()
        or not np.isfinite(maximum).all()
        or np.any(minimum > maximum)
        or not np.isfinite(half_opening)
        or half_opening <= 0.0
    ):
        return False
    channel_minimum = np.asarray(
        [-half_opening, -0.0180, -0.1340]
    )
    channel_maximum = np.asarray(
        [half_opening, 0.0180, -0.0710]
    )
    return bool(
        np.all(maximum >= channel_minimum)
        and np.all(minimum <= channel_maximum)
    )


def _tangential_jaw_capture_target(
    ee_world_matrix,
    jaw_local_point_m,
    contact_world_m,
    maximum_correction_m: float = 0.025,
) -> dict:
    """Centre a finger contact along the jaw without crossing the tissue."""
    import numpy as np

    ee = np.asarray(ee_world_matrix, dtype=np.float64)
    jaw = np.asarray(jaw_local_point_m, dtype=np.float64)
    contact = np.asarray(contact_world_m, dtype=np.float64)
    maximum = float(maximum_correction_m)
    if (
        ee.shape != (4, 4)
        or jaw.shape != (3,)
        or contact.shape != (3,)
        or not np.isfinite(ee).all()
        or not np.isfinite(jaw).all()
        or not np.isfinite(contact).all()
        or not np.isfinite(maximum)
        or maximum <= 0.0
    ):
        raise ValueError("capture geometry must be finite with a positive limit")
    contact_ee = (
        np.linalg.inv(ee) @ np.append(contact, 1.0)
    )[:3]
    correction_ee = contact_ee - jaw
    # Local X spans the two fingers.  Preserving that offset prevents the
    # wrist from crossing a one-finger contact and pushing the petiole ahead
    # of the closing jaw.  Only centre along the finger length/depth (Y/Z).
    correction_ee[0] = 0.0
    requested = float(np.linalg.norm(correction_ee))
    limited = requested > maximum
    if limited:
        correction_ee *= maximum / requested
    target_local = jaw + correction_ee
    target_world = (ee @ np.append(target_local, 1.0))[:3]
    return {
        "target_point_m": target_world,
        "contact_point_ee_m": contact_ee,
        "correction_ee_m": correction_ee,
        "requested_correction_m": requested,
        "applied_correction_m": float(np.linalg.norm(correction_ee)),
        "lateral_contact_offset_m": float(contact_ee[0] - jaw[0]),
        "limited": limited,
    }


def _lateral_jaw_disengage_target(
    ee_world_matrix,
    jaw_local_point_m,
    contact_world_m,
    clearance_m: float = 0.012,
    open_finger_inner_offset_m: float | None = None,
    central_gap_m: float = 0.002,
) -> dict:
    """Move the touching finger outward before centring compliant tissue."""
    import numpy as np

    ee = np.asarray(ee_world_matrix, dtype=np.float64)
    jaw = np.asarray(jaw_local_point_m, dtype=np.float64)
    contact = np.asarray(contact_world_m, dtype=np.float64)
    clearance = float(clearance_m)
    finger_inner = float(
        _LEFT_GRIPPER_OPEN_WIDTH_M
        if open_finger_inner_offset_m is None
        else open_finger_inner_offset_m
    )
    central_gap = float(central_gap_m)
    if (
        ee.shape != (4, 4)
        or jaw.shape != (3,)
        or contact.shape != (3,)
        or not np.isfinite(ee).all()
        or not np.isfinite(jaw).all()
        or not np.isfinite(contact).all()
        or not np.isfinite(clearance)
        or clearance <= 0.0
        or not np.isfinite(finger_inner)
        or finger_inner <= 0.0
        or not np.isfinite(central_gap)
        or central_gap < 0.0
    ):
        raise ValueError("disengage geometry must be finite with positive clearance")
    contact_ee = (
        np.linalg.inv(ee) @ np.append(contact, 1.0)
    )[:3]
    lateral_offset = float(contact_ee[0] - jaw[0])
    if abs(lateral_offset) <= 1e-6:
        raise ValueError("finger contact has no resolvable lateral side")
    # A fixed 12 mm shift is insufficient when contact lies near the outer
    # face of a fully open finger. Move at least far enough that the stationary
    # tissue is central_gap inside the jaw's open central channel.
    requested_translation = max(
        clearance,
        abs(lateral_offset) - finger_inner + central_gap,
    )
    translation_ee = np.asarray(
        [np.copysign(requested_translation, lateral_offset), 0.0, 0.0],
        dtype=np.float64,
    )
    target_pose = ee.copy()
    target_pose[:3, 3] += ee[:3, :3] @ translation_ee
    return {
        "target_pose": target_pose,
        "contact_point_ee_m": contact_ee,
        "translation_ee_m": translation_ee,
        "lateral_contact_offset_m": lateral_offset,
        "clearance_m": clearance,
        "open_finger_inner_offset_m": finger_inner,
        "central_gap_m": central_gap,
        "requested_translation_m": requested_translation,
        "predicted_contact_offset_after_m": (
            lateral_offset - translation_ee[0]
        ),
    }


def _contact_avoiding_jaw_reentry_targets(
    ee_world_matrix,
    jaw_local_point_m,
    contact_world_m,
    *,
    finger_tangential_half_extent_m: float = 0.016,
    detour_clearance_m: float = 0.010,
    minimum_detour_translation_m: float = 0.030,
    central_corridor_clearance_m: float = 0.020,
    return_overshoot_m: float = 0.010,
) -> dict:
    '''Route an open jaw around an external one-finger contact.'''
    import numpy as np

    ee = np.asarray(ee_world_matrix, dtype=np.float64)
    jaw = np.asarray(jaw_local_point_m, dtype=np.float64)
    contact = np.asarray(contact_world_m, dtype=np.float64)
    half_extent = float(finger_tangential_half_extent_m)
    detour_clearance = float(detour_clearance_m)
    minimum_detour = float(minimum_detour_translation_m)
    corridor_clearance = float(central_corridor_clearance_m)
    return_overshoot = float(return_overshoot_m)
    values = (
        half_extent,
        detour_clearance,
        minimum_detour,
        corridor_clearance,
        return_overshoot,
    )
    if (
        ee.shape != (4, 4)
        or jaw.shape != (3,)
        or contact.shape != (3,)
        or not np.isfinite(ee).all()
        or not np.isfinite(jaw).all()
        or not np.isfinite(contact).all()
        or not all(math.isfinite(value) and value > 0.0 for value in values)
    ):
        raise ValueError('jaw re-entry geometry must be finite and positive')

    # Leave the touched finger's outer Y corner before crossing in local X.
    lateral = _lateral_jaw_disengage_target(
        ee, jaw, contact, central_gap_m=corridor_clearance
    )
    contact_ee = np.asarray(lateral['contact_point_ee_m'], dtype=np.float64)
    tangential_sign = -1.0 if contact_ee[1] >= 0.0 else 1.0
    tangential_distance = max(
        minimum_detour,
        half_extent + detour_clearance - abs(float(contact_ee[1])),
    )
    tangential = np.asarray(
        [0.0, tangential_sign * tangential_distance, 0.0],
        dtype=np.float64,
    )
    lateral_translation = np.asarray(
        lateral['translation_ee_m'], dtype=np.float64
    )
    return_offset = -tangential * (
        return_overshoot / float(np.linalg.norm(tangential))
    )
    cumulative = (
        tangential,
        tangential + lateral_translation,
        lateral_translation + return_offset,
    )
    segments = (
        tangential,
        lateral_translation,
        return_offset - tangential,
    )
    phases = []
    for name, offset, segment in zip(
        (
            'tangential_depart',
            'separated_lateral_transfer',
            'corridor_return',
        ),
        cumulative,
        segments,
        strict=True,
    ):
        target_pose = ee.copy()
        target_pose[:3, 3] += ee[:3, :3] @ offset
        phases.append(
            {
                'stage': name,
                'target_pose': target_pose,
                'cumulative_translation_ee_m': offset.copy(),
                'segment_translation_ee_m': segment.copy(),
            }
        )
    return {
        'contact_point_ee_m': contact_ee,
        'tangential_translation_ee_m': tangential,
        'lateral_translation_ee_m': lateral_translation,
        'finger_tangential_half_extent_m': half_extent,
        'detour_clearance_m': detour_clearance,
        'minimum_detour_translation_m': minimum_detour,
        'central_corridor_clearance_m': corridor_clearance,
        'return_overshoot_m': return_overshoot,
        'predicted_contact_offset_after_m': lateral[
            'predicted_contact_offset_after_m'
        ],
        'phases': phases,
    }


def _guarded_reentry_pose_acceptable(
    *,
    succeeded: bool,
    position_error_m: float,
    orientation_error_rad: float,
    maximum_position_error_m: float = 0.001,
    maximum_orientation_error_rad: float = 0.017453292519943295,
) -> bool:
    '''Accept a bounded open-jaw pose before live corridor recapture.'''
    values = tuple(
        float(value)
        for value in (
            position_error_m,
            orientation_error_rad,
            maximum_position_error_m,
            maximum_orientation_error_rad,
        )
    )
    if not all(math.isfinite(value) for value in values):
        return False
    if values[2] < 0.0 or values[3] < 0.0:
        raise ValueError('guarded re-entry residual limits cannot be negative')
    # This never establishes a grasp: the fingers remain fully open and the
    # live jaw-corridor geometry is re-read immediately after the move.
    return bool(
        succeeded or (values[0] <= values[2] and values[1] <= values[3])
    )


def _bounded_disengage_ik_acceptable(
    *,
    succeeded: bool,
    position_error_m: float,
    orientation_error_rad: float,
    commanded_translation_m: float,
    contact_radius_m: float,
    minimum_guaranteed_translation_m: float = 0.010,
) -> tuple[bool, float]:
    """Accept a near-exact unload only when its worst-case motion is enough."""
    values = tuple(
        float(value)
        for value in (
            position_error_m,
            orientation_error_rad,
            commanded_translation_m,
            contact_radius_m,
            minimum_guaranteed_translation_m,
        )
    )
    if (
        not all(math.isfinite(value) for value in values)
        or any(value < 0.0 for value in values)
        or values[2] <= 0.0
        or values[4] <= 0.0
    ):
        raise ValueError("bounded disengage values must be finite and positive")
    guaranteed = max(
        values[2] - values[0] - values[3] * values[1],
        0.0,
    )
    return bool(succeeded or guaranteed >= values[4]), guaranteed


def _lateral_backstop_seat_target(
    ee_world_matrix,
    bounds_minimum_ee_m,
    bounds_maximum_ee_m,
    loaded_finger: str,
    seating_overlap_m: float = 0.001,
    maximum_correction_m: float = 0.012,
) -> dict:
    """Seat structural tissue against the closed opposite jaw in local X."""
    import numpy as np

    ee = np.asarray(ee_world_matrix, dtype=np.float64)
    minimum = np.asarray(bounds_minimum_ee_m, dtype=np.float64)
    maximum = np.asarray(bounds_maximum_ee_m, dtype=np.float64)
    overlap = float(seating_overlap_m)
    limit = float(maximum_correction_m)
    if (
        ee.shape != (4, 4)
        or minimum.shape != (3,)
        or maximum.shape != (3,)
        or not np.isfinite(ee).all()
        or not np.isfinite(minimum).all()
        or not np.isfinite(maximum).all()
        or np.any(minimum > maximum)
        or loaded_finger not in {"left_finger_1", "left_finger_2"}
        or not np.isfinite(overlap)
        or overlap < 0.0
        or not np.isfinite(limit)
        or limit <= 0.0
    ):
        raise ValueError("backstop seating geometry must be finite and valid")
    # Finger 1 occupies +X and finger 2 occupies -X when closed.  If finger
    # 1 made the original contact, translate +X until the target's near side
    # reaches the finger-2 centre plane (and mirror for finger 2 contact).
    requested = (
        float(minimum[0] + overlap)
        if loaded_finger == "left_finger_1"
        else float(maximum[0] - overlap)
    )
    correction = float(np.clip(requested, -limit, limit))
    target_pose = ee.copy()
    translation_ee = np.asarray([correction, 0.0, 0.0])
    target_pose[:3, 3] += ee[:3, :3] @ translation_ee
    predicted_minimum = minimum.copy()
    predicted_maximum = maximum.copy()
    predicted_minimum[0] -= correction
    predicted_maximum[0] -= correction
    return {
        "target_pose": target_pose,
        "translation_ee_m": translation_ee,
        "requested_correction_m": requested,
        "applied_correction_m": correction,
        "limited": not np.isclose(correction, requested),
        "loaded_finger": loaded_finger,
        "predicted_minimum_ee_m": predicted_minimum,
        "predicted_maximum_ee_m": predicted_maximum,
    }


def _jaw_anchor_microseat_target(
    ee_world_matrix,
    anchor_ee_m,
    loaded_finger: str,
    backstop_overlap_m: float = 0.0015,
    longitudinal_inner_limit_m: float = 0.014,
    maximum_lateral_correction_m: float = 0.006,
    maximum_longitudinal_correction_m: float = 0.006,
) -> dict:
    """Move the exact tissue anchor into the opposed finger's centre strip."""
    import numpy as np

    ee = np.asarray(ee_world_matrix, dtype=np.float64)
    anchor = np.asarray(anchor_ee_m, dtype=np.float64)
    overlap = float(backstop_overlap_m)
    inner = float(longitudinal_inner_limit_m)
    lateral_limit = float(maximum_lateral_correction_m)
    longitudinal_limit = float(maximum_longitudinal_correction_m)
    if (
        ee.shape != (4, 4)
        or anchor.shape != (3,)
        or not np.isfinite(ee).all()
        or not np.isfinite(anchor).all()
        or loaded_finger not in {"left_finger_1", "left_finger_2"}
        or not all(
            np.isfinite(value) and value > 0.0
            for value in (
                overlap,
                inner,
                lateral_limit,
                longitudinal_limit,
            )
        )
    ):
        raise ValueError("jaw-anchor micro-seat geometry must be finite and valid")
    desired = anchor.copy()
    desired[0] = (
        -overlap if loaded_finger == "left_finger_1" else overlap
    )
    desired[1] = float(np.clip(anchor[1], -inner, inner))
    requested = anchor - desired
    requested[2] = 0.0
    correction = requested.copy()
    correction[0] = float(
        np.clip(correction[0], -lateral_limit, lateral_limit)
    )
    correction[1] = float(
        np.clip(correction[1], -longitudinal_limit, longitudinal_limit)
    )
    target_pose = ee.copy()
    target_pose[:3, 3] += ee[:3, :3] @ correction
    predicted = anchor - correction
    return {
        "target_pose": target_pose,
        "anchor_ee_m": anchor,
        "desired_anchor_ee_m": desired,
        "translation_ee_m": correction,
        "requested_translation_ee_m": requested,
        "requested_correction_m": float(np.linalg.norm(requested)),
        "applied_correction_m": float(np.linalg.norm(correction)),
        "predicted_anchor_ee_m": predicted,
        "limited": not np.allclose(correction, requested),
        "loaded_finger": loaded_finger,
    }


def _open_finger_reseat_allowed(
    closure_stage: str,
    before_gap_m: float,
    after_gap_m: float,
) -> bool:
    """Allow one second open-jaw seat only after useful first-seat progress."""
    import math

    before = float(before_gap_m)
    after = float(after_gap_m)
    return bool(
        closure_stage == "opposite_finger_backstop"
        and math.isfinite(before)
        and math.isfinite(after)
        and before >= 0.0
        and after > 0.005
        and before - after >= 0.001
    )


def _geometric_cut_reaction_force(
    centreline_distance_m: float,
    tissue_radius_m: float,
    cut_force_n: float,
    tolerance_m: float = 0.0015,
    force_cap_multiple: float = 3.0,
) -> float:
    """Return a compliant reaction for an edge entering counter-held tissue."""
    import numpy as np

    distance = float(centreline_distance_m)
    radius = float(tissue_radius_m)
    required_force = float(cut_force_n)
    tolerance = float(tolerance_m)
    cap = float(force_cap_multiple)
    if (
        not all(
            np.isfinite(value)
            for value in (distance, radius, required_force, tolerance, cap)
        )
        or distance < 0.0
        or radius <= 0.0
        or required_force <= 0.0
        or tolerance < 0.0
        or cap <= 0.0
    ):
        return 0.0
    penetration = radius + tolerance - distance
    if penetration <= 0.0:
        return 0.0
    stiffness_n_m = required_force / max(0.5 * radius, 1e-4)
    reaction = stiffness_n_m * penetration
    if penetration >= 0.5 * radius - 1e-12:
        reaction = max(reaction, required_force)
    return float(min(required_force * cap, reaction))


def _opposed_finger_contact(contact: dict | None) -> bool:
    """Return whether a nonzero contact loads both left fingers."""
    if contact is None or float(contact.get("force_n", 0.0)) <= 0.0:
        return False
    return {"left_finger_1", "left_finger_2"}.issubset(
        set(contact.get("fingers", ()))
    )


def _opposed_backstop_closure_schedule(
    contact: dict | None,
) -> tuple[dict, ...]:
    """Close the free finger first, then advance the contacting finger."""
    if contact is None:
        return ()
    fingers = set(contact.get("fingers", ()))
    known = {"left_finger_1", "left_finger_2"}
    loaded = fingers & known
    if len(loaded) != 1:
        return ()
    loaded_finger = next(iter(loaded))
    backstop_finger = next(iter(known - loaded))
    records = []
    for name, loaded_openness in (
        ("opposite_finger_backstop", 1.0),
        ("loaded_finger_65_percent", 0.65),
        ("loaded_finger_40_percent", 0.40),
        ("loaded_finger_20_percent", 0.20),
        ("loaded_finger_closed", 0.0),
    ):
        openness = {
            loaded_finger: loaded_openness,
            backstop_finger: 0.0,
        }
        records.append(
            {
                "stage": name,
                "loaded_finger": loaded_finger,
                "backstop_finger": backstop_finger,
                "left_finger_1": openness["left_finger_1"],
                "left_finger_2": openness["left_finger_2"],
            }
        )
    return tuple(records)


def _target_contact_supports_guarded_close(
    contact: dict | None,
    target_key: str,
    *,
    structural_only: bool = False,
) -> bool:
    """Allow closure after one loaded finger touches the selected branch."""
    return bool(
        contact is not None
        and contact.get("key") == target_key
        and (
            not structural_only
            or contact.get("role") in {"petiole_grasp", "petiole_cut_zone"}
        )
        and contact.get("fingers")
        and float(contact.get("force_n", 0.0)) > 0.0
    )


def _target_contact_point(
    contact: dict | None,
    target_key: str,
    *,
    structural_only: bool = False,
) -> tuple[float, float, float] | None:
    """Return a finite live contact point for the selected branch."""
    import math

    if not _target_contact_supports_guarded_close(
        contact,
        target_key,
        structural_only=structural_only,
    ):
        return None
    point = contact.get("point_m")
    if not isinstance(point, (list, tuple)) or len(point) != 3:
        return None
    values = tuple(float(value) for value in point)
    return values if all(math.isfinite(value) for value in values) else None


def _measured_state_reconstruction_acceptable(
    position_error_m: float,
    orientation_error_rad: float,
    *,
    maximum_position_error_m: float = 0.003,
    maximum_orientation_error_rad: float = 0.017453292519943295,
) -> bool:
    """Accept a bounded PhysX-to-rigid-kinematics reconstruction residual.

    Commanded-pose IK keeps its stricter solver gate. This helper is only for
    reconstructing a planning seed from a physically settled wrist whose
    compliant articulation can differ slightly from the rigid URDF model.
    """
    import math

    values = (
        float(position_error_m),
        float(orientation_error_rad),
        float(maximum_position_error_m),
        float(maximum_orientation_error_rad),
    )
    if not all(math.isfinite(value) for value in values):
        return False
    if values[2] < 0.0 or values[3] < 0.0:
        raise ValueError("measured-state reconstruction limits cannot be negative")
    return values[0] <= values[2] and values[1] <= values[3]


def _measured_state_reconstruction_limits(
    synchronization_translation_m: float,
    synchronization_orientation_rad: float,
    *,
    settled_position_limit_m: float = 0.003,
    settled_orientation_limit_rad: float = 0.017453292519943295,
    maximum_position_limit_m: float = 0.010,
    maximum_orientation_limit_rad: float = 0.05235987755982989,
) -> tuple[float, float]:
    """Bound a moving PhysX/Usd wrist sample without weakening task safety."""
    import math

    values = tuple(
        float(value)
        for value in (
            synchronization_translation_m,
            synchronization_orientation_rad,
            settled_position_limit_m,
            settled_orientation_limit_rad,
            maximum_position_limit_m,
            maximum_orientation_limit_rad,
        )
    )
    if not all(math.isfinite(value) for value in values):
        raise ValueError("measured-state synchronization limits must be finite")
    if any(value < 0.0 for value in values):
        raise ValueError("measured-state synchronization limits cannot be negative")
    if values[4] < values[2] or values[5] < values[3]:
        raise ValueError("measured-state synchronization caps cannot shrink settled limits")
    return (
        min(values[4], values[2] + 1.25 * values[0]),
        min(values[5], values[3] + 1.25 * values[1]),
    )


def _measured_state_settled_position_limit_m(
    side: str,
    task_phase: str,
) -> float:
    """Allow bounded PhysX articulation compliance under a held crop load."""
    if side not in {"left", "right"}:
        raise ValueError(f"unknown arm side: {side!r}")
    if side == "left" and task_phase in {
        "grasped",
        "orphan_retained",
        "transported",
    }:
        # PhysX constraint compliance can displace the force-driven live link
        # a few millimetres from ideal rigid-chain FK under counterhold load.
        # This is diagnostic only; live-USD payload/contact guards retain
        # their original physical safety clearances.
        return 0.005
    if side == "right" and task_phase == "grasped":
        # The held branch can impose a small repeatable compliance offset on
        # the force-driven cutter wrist near the inner approach. A stationary
        # physical trial measured 3.51 mm with only 0.17 degrees of angular
        # error, so keep a bounded 4 mm diagnostic seed gate; live physical
        # safety is unchanged.
        return 0.004
    # Keep a bounded 0.5 mm numerical reserve above the nominal 3 mm rigid-FK
    # reconstruction check. Repeated unloaded physical trials measured up to
    # 3.28 mm on both arms despite sub-degree orientation agreement. This is a
    # seed-reconstruction diagnostic only; payload, contact, and cut safety
    # continue to use their unchanged physical guards.
    return 0.0035



def _bounded_robot_forward_nudge(
    current_position_m,
    origin_position_m,
    yaw_degrees: float,
    requested_delta_m: float,
    minimum_base_y_m: float,
    maximum_base_y_m: float,
    *,
    maximum_forward_offset_m: float = 0.10,
    maximum_backward_offset_m: float = 0.05,
) -> dict:
    """Return a forward nudge clipped to both session and aisle limits."""
    import numpy as np

    current = np.asarray(current_position_m, dtype=np.float64)
    origin = np.asarray(origin_position_m, dtype=np.float64)
    values = np.asarray(
        [
            yaw_degrees,
            requested_delta_m,
            minimum_base_y_m,
            maximum_base_y_m,
            maximum_forward_offset_m,
            maximum_backward_offset_m,
        ],
        dtype=np.float64,
    )
    if (
        current.shape != (3,)
        or origin.shape != (3,)
        or not np.isfinite(current).all()
        or not np.isfinite(origin).all()
        or not np.isfinite(values).all()
        or minimum_base_y_m > maximum_base_y_m
        or maximum_forward_offset_m < 0.0
        or maximum_backward_offset_m < 0.0
    ):
        raise ValueError("invalid bounded robot nudge geometry")

    yaw = np.radians(float(yaw_degrees))
    forward = np.asarray([np.cos(yaw), np.sin(yaw), 0.0])
    if abs(float(forward[1])) < 0.5:
        raise ValueError("bounded greenhouse nudging requires a +/-Y heading")
    aisle_offsets = sorted(
        (
            (float(minimum_base_y_m) - origin[1]) / forward[1],
            (float(maximum_base_y_m) - origin[1]) / forward[1],
        )
    )
    minimum_offset = max(-float(maximum_backward_offset_m), aisle_offsets[0])
    maximum_offset = min(float(maximum_forward_offset_m), aisle_offsets[1])
    if minimum_offset > maximum_offset:
        raise ValueError("robot nudge origin lies outside the bounded aisle")

    current_offset = float(np.dot(current - origin, forward))
    requested_offset = current_offset + float(requested_delta_m)
    offset = float(np.clip(requested_offset, minimum_offset, maximum_offset))
    applied = offset - current_offset
    position = current + forward * applied
    position[1] = float(
        np.clip(position[1], minimum_base_y_m, maximum_base_y_m)
    )
    return {
        "position_m": position,
        "applied_delta_m": applied,
        "forward_offset_m": offset,
        "minimum_forward_offset_m": minimum_offset,
        "maximum_forward_offset_m": maximum_offset,
        "limited": bool(abs(offset - requested_offset) > 1e-9),
    }


class InteractionController:
    """Queue UI/input actions and apply them between simulation steps."""

    controls = {
        "mouse": "Shift + left-drag visible stem, petiole, or leaf geometry",
        "previous_target": "[",
        "next_target": "]",
        "next_vine": "V",
        "debug_force_cut": "C (not benchmark-valid)",
        "physical_cut": "right leading-edge contact + direction + force + work",
        "left_grasp_close": "G",
        "left_grasp_open_release": "O",
        "target_pinched_leaf": "T (explicit manual target change)",
        "run_full_ik": "Run Full IK Sequence button",
        "run_grasp_ik": "Run Grasp IK Sequence button",
        "robot_forward": "bounded +10 mm fixed-base preposition button",
        "robot_backward": "bounded -10 mm fixed-base preposition button",
        "camera_views": "1 inspection, 2 head, 3 left wrist, 4 right wrist",
    }

    def __init__(
        self,
        stage,
        runtimes: list[VineRuntime],
        report: dict,
        report_path: pathlib.Path,
        args,
        vine_interaction,
        camera_views: dict[str, str],
        blade_cutting: BladeContactMonitor | None,
        grasp_manager: LeftGraspManager | None,
        selected_target,
        robot_placement=None,
        run_full_ik=None,
        run_grasp_ik=None,
    ):
        import carb
        import omni.appwindow
        import omni.ui as ui

        self._carb = carb
        self._stage = stage
        self._runtimes = runtimes
        self._report = report
        self._report_path = report_path
        self._pending: list[str] = []
        self._camera_views = camera_views
        self._blade_cutting = blade_cutting
        self._grasp_manager = grasp_manager
        self._robot_placement = robot_placement
        self._robot_base_articulation = None
        self._robot_base_origin_m = None
        preposition = report.get("robot_preposition") or {}
        self._robot_aisle_bounds = preposition.get("opposite_aisle")
        self._active_camera = "inspection"
        self._targets = [self._target_labels(runtime) for runtime in runtimes]
        self._vine = next(
            index
            for index, runtime in enumerate(runtimes)
            if runtime.name == selected_target.vine_name
        )
        self._target = self._targets[self._vine].index(selected_target.organ_label)
        self._run_full_ik = run_full_ik
        self._run_grasp_ik = run_grasp_ik
        self._ik_running = False
        self._reported_contact_serial = None

        self._window = ui.Window("Vine Interaction", width=420, height=590)
        with self._window.frame:
            with ui.VStack(spacing=6):
                ui.Label("Pull: Shift + left-drag visible vine geometry", height=24)
                self._target_label = ui.Label("", height=24)
                self._status_label = ui.Label("Ready; gentle airflow enabled", height=48, word_wrap=True)
                with ui.HStack(spacing=6, height=34):
                    ui.Button("Previous [", clicked_fn=lambda: self._queue("previous"))
                    ui.Button("Next ]", clicked_fn=lambda: self._queue("next"))
                with ui.HStack(spacing=6, height=34):
                    ui.Button("Next vine V", clicked_fn=lambda: self._queue("vine"))
                    ui.Button("DEBUG FORCE CUT C", clicked_fn=lambda: self._queue("cut"))
                with ui.HStack(spacing=6, height=34):
                    ui.Button("Close left grasp G", clicked_fn=lambda: self._queue("grasp"))
                    ui.Button("Open / release O", clicked_fn=lambda: self._queue("release"))
                ui.Button(
                    "Target pinched leaf T",
                    clicked_fn=lambda: self._queue("target_contact"),
                    height=34,
                )
                self._run_grasp_ik_button = ui.Button(
                    "Run Grasp IK Sequence",
                    clicked_fn=lambda: self._queue("run_grasp_ik"),
                    height=38,
                )
                self._run_full_ik_button = ui.Button(
                    "Run Full IK Sequence",
                    clicked_fn=lambda: self._queue("run_full_ik"),
                    height=38,
                )
                with ui.HStack(spacing=6, height=34):
                    self._robot_forward_button = ui.Button(
                        "Robot forward +10 mm",
                        clicked_fn=lambda: self._queue("robot_forward"),
                    )
                    self._robot_backward_button = ui.Button(
                        "Robot back -10 mm",
                        clicked_fn=lambda: self._queue("robot_backward"),
                    )
                robot_move_available = bool(
                    self._robot_placement is not None
                    and self._robot_aisle_bounds is not None
                )
                self._robot_forward_button.enabled = robot_move_available
                self._robot_backward_button.enabled = robot_move_available
                ui.Label("Viewport camera / video observation", height=22)
                with ui.HStack(spacing=6, height=34):
                    ui.Button("Inspection 1", clicked_fn=lambda: self._queue("camera:inspection"))
                    ui.Button("Head D405 2", clicked_fn=lambda: self._queue("camera:head"))
                with ui.HStack(spacing=6, height=34):
                    ui.Button("Left D405 3", clicked_fn=lambda: self._queue("camera:left_wrist"))
                    ui.Button("Right D405 4", clicked_fn=lambda: self._queue("camera:right_wrist"))

        appwindow = omni.appwindow.get_default_app_window()
        self._input = carb.input.acquire_input_interface()
        self._keyboard = appwindow.get_keyboard()
        self._keyboard_sub = self._input.subscribe_to_keyboard_events(self._keyboard, self._on_key)
        self._airflow = vine_interaction.Airflow(
            stage,
            runtimes,
            speed_m_s=args.airflow_speed,
            frequency_hz=args.airflow_frequency,
            direction_deg=args.airflow_direction,
        )
        report["airflow"] = self._airflow.summary
        body_paths = [link.path for runtime in runtimes for link in runtime.rig.links]
        self._visual_pull = vine_interaction.VisualPull(
            stage,
            body_paths,
            report,
            persist=lambda: _emit(self._report, self._report_path),
            status=lambda message: setattr(self._status_label, "text", message),
            stiffness_n_m=args.drag_stiffness,
            damping_n_s_m=args.drag_damping,
            max_force_n=args.drag_max_force,
        )
        self._refresh()

    def _target_labels(self, runtime: VineRuntime) -> list[str]:
        labelled = [
            organ
            for organ in runtime.plant.organs
            if organ.label.startswith("SubStem_") and organ.label in runtime.rig.cut_joints
        ]
        labelled.sort(
            key=lambda organ: float(organ.attachment[1])
            if organ.attachment is not None
            else float("inf")
        )
        return [organ.label for organ in labelled]

    def _queue(self, action: str) -> None:
        self._pending.append(action)

    def _on_key(self, event, *args, **kwargs) -> bool:
        if event.type != self._carb.input.KeyboardEventType.KEY_PRESS:
            return True
        action = {
            "LEFT_BRACKET": "previous",
            "RIGHT_BRACKET": "next",
            "V": "vine",
            "C": "cut",
            "G": "grasp",
            "O": "release",
            "T": "target_contact",
            "KEY_1": "camera:inspection",
            "KEY_2": "camera:head",
            "KEY_3": "camera:left_wrist",
            "KEY_4": "camera:right_wrist",
        }.get(event.input.name)
        if action is not None:
            self._queue(action)
        return True


    def process(self, context) -> None:
        if self._grasp_manager is not None:
            self._grasp_manager.process()
            contact = self._grasp_manager.latest_finger_contact
            if (
                contact is not None
                and contact["serial"] != self._reported_contact_serial
            ):
                self._reported_contact_serial = contact["serial"]
                current = (
                    f"{self._runtimes[self._vine].name}/"
                    f"{self._targets[self._vine][self._target]}"
                )
                if contact["key"] != current:
                    if (
                        self._grasp_manager.close_requested
                        and _opposed_finger_contact(contact)
                    ):
                        self._pending.insert(0, "target_contact:auto")
                        self._status_label.text = (
                            f"Opposed physical pinch detected on {contact['key']}; "
                            "selecting that branch"
                        )
                    else:
                        self._status_label.text = (
                            f"Finger contact is {contact['key']}, not selected {current}. "
                            "Press T or click Target pinched leaf."
                        )
        if self._blade_cutting is not None:
            applied = _apply_blade_cut_decisions(
                context,
                self._blade_cutting,
                self._report,
                self._report_path,
                self._grasp_manager,
            )
            if applied:
                latest = applied[-1]
                qualifier = "intended" if latest["intended_target"] else "UNINTENDED"
                if latest.get("interaction_cut"):
                    self._status_label.text = (
                        f"Blade traversal cut "
                        f"{latest['vine']}/{latest['organ_label']} "
                        f"({qualifier}; interaction mode, not benchmark-valid)"
                    )
                else:
                    self._status_label.text = (
                        f"Physical blade cut "
                        f"{latest['vine']}/{latest['organ_label']} "
                        f"({qualifier}, {latest['peak_force_n']:.1f} N)"
                    )
        self._airflow.step()
        self._visual_pull.step()
        while self._pending:
            action = self._pending.pop(0)
            if action.startswith("camera:"):
                self._set_camera(action.partition(":")[2])
                continue
            if action == "robot_forward":
                self._nudge_robot(context, 0.01)
                continue
            if action == "robot_backward":
                self._nudge_robot(context, -0.01)
                continue
            targets = self._targets[self._vine]
            if not targets:
                self._status_label.text = "No deleafing targets on this vine"
                continue
            if action == "previous":
                self._target = (self._target - 1) % len(targets)
            elif action == "next":
                self._target = (self._target + 1) % len(targets)
            elif action == "vine":
                self._vine = (self._vine + 1) % len(self._runtimes)
                self._target = 0
            elif action == "grasp" and self._grasp_manager is not None:
                self._grasp_manager.request_close()
                self._status_label.text = (
                    "Left gripper closing; two-finger target contact is required"
                )
                self._report["bimanual_task"] = self._grasp_manager.summary
                _emit(self._report, self._report_path)
            elif action == "release" and self._grasp_manager is not None:
                self._grasp_manager.request_open()
                self._status_label.text = (
                    "Left gripper opened; release is valid only after safe transport"
                )
                self._report["bimanual_task"] = self._grasp_manager.summary
                _emit(self._report, self._report_path)
            elif action.startswith("target_contact") and self._grasp_manager is not None:
                automatic = action.endswith(":auto")
                contact = self._grasp_manager.latest_finger_contact
                if contact is None:
                    self._status_label.text = (
                        "No left-finger leaf contact has been detected yet"
                    )
                else:
                    vine_index = next(
                        (
                            index
                            for index, runtime in enumerate(self._runtimes)
                            if runtime.name == contact["vine"]
                        ),
                        None,
                    )
                    target_index = (
                        self._targets[vine_index].index(contact["organ"])
                        if vine_index is not None
                        and contact["organ"] in self._targets[vine_index]
                        else None
                    )
                    if vine_index is None or target_index is None:
                        self._status_label.text = (
                            f"Contacted {contact['key']} is not a severable target"
                        )
                    else:
                        previous = (
                            f"{self._runtimes[self._vine].name}/"
                            f"{self._targets[self._vine][self._target]}"
                        )
                        self._vine = vine_index
                        self._target = target_index
                        change = {
                            "from": previous,
                            "to": contact["key"],
                            "trigger": (
                                "opposed_finger_physical_pinch"
                                if automatic
                                else "explicit_pinched_leaf_selection"
                            ),
                        }
                        self._report.setdefault(
                            "contact_target_changes", []
                        ).append(change)
                        if not automatic:
                            self._report.setdefault(
                                "manual_target_changes", []
                            ).append(change)
                        qualifier = "Automatically" if automatic else "Manually"
                        self._status_label.text = (
                            f"{qualifier} selected {contact['key']} from physical contact; "
                            "maintain the opposed pinch"
                        )
            elif action in {
                "run_grasp_ik",
                "run_full_ik",
                "execute_grasp_ik",
                "execute_full_ik",
            }:
                grasp_only = action.endswith("grasp_ik")
                callback = (
                    self._run_grasp_ik if grasp_only else self._run_full_ik
                )
                sequence_name = "Grasp IK" if grasp_only else "Full IK"
                if callback is None:
                    self._status_label.text = (
                        f"{sequence_name} sequence is unavailable"
                    )
                elif self._ik_running and not action.startswith("execute_"):
                    self._status_label.text = (
                        f"{sequence_name} sequence is already running"
                    )
                else:
                    self._ik_running = True
                    self._run_grasp_ik_button.enabled = False
                    self._run_full_ik_button.enabled = False
                    self._status_label.text = (
                        (
                            "Running left approach, opposed grasp, and "
                            "counterhold validation..."
                        )
                        if grasp_only
                        else (
                            "Running grasp, cut, retract, and deposit "
                            "sequence..."
                        )
                    )
                    if not action.startswith("execute_"):
                        self._status_label.text = (
                            f"{sequence_name} planning collision-safe approach; "
                            "first visible motion may take several minutes..."
                        )
                        self._report["ui_ik_sequence"] = {
                            "mode": "grasp" if grasp_only else "full",
                            "stage": "planning",
                            "succeeded": None,
                        }
                        _emit(self._report, self._report_path)
                        self._pending.insert(
                            0, f"execute_{action.removeprefix('run_')}"
                        )
                        break
                    try:
                        result = callback()
                    except Exception as exc:
                        self._status_label.text = (
                            f"{sequence_name} sequence failed: {exc}"
                        )
                        error_key = (
                            "ui_grasp_ik_error"
                            if grasp_only
                            else "ui_full_ik_error"
                        )
                        self._report[error_key] = str(exc)
                        self._report["ui_ik_sequence"] = {
                            "mode": "grasp" if grasp_only else "full",
                            "stage": "failed",
                            "succeeded": False,
                            "error": str(exc),
                        }
                    else:
                        self._status_label.text = (
                            f"{sequence_name} sequence passed"
                            if result["succeeded"]
                            else f"{sequence_name} sequence failed: "
                            + result.get("error", "acceptance gate")
                        )
                        succeeded = bool(result["succeeded"])
                        self._report["ui_ik_sequence"] = {
                            "mode": "grasp" if grasp_only else "full",
                            "stage": "complete" if succeeded else "failed",
                            "succeeded": succeeded,
                        }
                        if not succeeded:
                            self._report["ui_ik_sequence"]["error"] = result.get("error")
                    finally:
                        self._ik_running = False
                        self._run_grasp_ik_button.enabled = True
                        self._run_full_ik_button.enabled = True
                        _emit(self._report, self._report_path)
            elif action == "cut":
                self._cut(context)
            self._refresh()

    def _nudge_robot(self, context, requested_delta_m: float) -> None:
        if self._robot_placement is None or self._robot_aisle_bounds is None:
            self._status_label.text = "Bounded robot base movement is unavailable"
            return
        if self._ik_running:
            self._status_label.text = "Wait for the IK sequence before moving the base"
            return
        grasp = self._grasp_manager.summary if self._grasp_manager is not None else {}
        if grasp.get("active_joint") is not None:
            self._status_label.text = "Release the grasped branch before moving the base"
            return

        import numpy as np
        from isaacsim.core.prims import Articulation
        from pxr import Gf
        from pxr import UsdPhysics

        try:
            if self._robot_base_articulation is None:
                self._robot_base_articulation = Articulation(
                    prim_paths_expr=self._robot_placement.root_path,
                    name="greenhouse_ui_base_nudge",
                    reset_xform_properties=False,
                )
                self._robot_base_articulation.initialize()
            positions, orientations = (
                self._robot_base_articulation.get_world_poses()
            )
            positions = np.asarray(positions, dtype=np.float64).copy()
            orientations = np.asarray(orientations, dtype=np.float64).copy()
            if positions.shape != (1, 3) or orientations.shape != (1, 4):
                raise RuntimeError(
                    "RB-Y1 articulation returned an unexpected root-pose shape"
                )
            current = positions[0].copy()
            if self._robot_base_origin_m is None:
                self._robot_base_origin_m = current.copy()
            result = _bounded_robot_forward_nudge(
                current,
                self._robot_base_origin_m,
                self._robot_placement.yaw_degrees,
                requested_delta_m,
                self._robot_aisle_bounds["minimum_base_y_m"],
                self._robot_aisle_bounds["maximum_base_y_m"],
            )
            applied = float(result["applied_delta_m"])
            if abs(applied) <= 1e-9:
                self._status_label.text = "Robot base is at its bounded movement limit"
                return
            target = np.asarray(result["position_m"], dtype=np.float64)

            fixed_path = (
                f"{self._robot_placement.root_path}/joints/"
                "benchmark_world_fixed"
            )
            fixed = UsdPhysics.FixedJoint.Get(self._stage, fixed_path)
            if not fixed.GetPrim().IsValid():
                raise RuntimeError(f"fixed RB-Y1 base joint is missing: {fixed_path}")
            anchor = fixed.GetLocalPos0Attr()
            previous_anchor = anchor.Get()
            context.pause()
            try:
                anchor.Set(Gf.Vec3f(*target.tolist()))
                positions[0] = target
                self._robot_base_articulation.set_world_poses(
                    positions=positions,
                    orientations=orientations,
                )
                zero_velocity = np.zeros((1, 3), dtype=np.float64)
                self._robot_base_articulation.set_linear_velocities(
                    zero_velocity
                )
                self._robot_base_articulation.set_angular_velocities(
                    zero_velocity
                )
                if self._blade_cutting is not None:
                    self._blade_cutting.suppress_interaction_after_base_teleport()
            except Exception:
                anchor.Set(previous_anchor)
                raise
            finally:
                context.play()
        except Exception as exc:
            error = {
                "requested_delta_m": float(requested_delta_m),
                "error": str(exc),
            }
            self._report.setdefault("robot_base_ui_errors", []).append(error)
            self._status_label.text = f"Robot base movement failed: {exc}"
            _emit(self._report, self._report_path)
            return

        entry = {
            "requested_delta_m": float(requested_delta_m),
            "applied_delta_m": applied,
            "position_m": target.tolist(),
            "forward_offset_m": float(result["forward_offset_m"]),
            "limited": bool(result["limited"]),
            "fixed_joint": fixed_path,
            "cut_suppression_steps": 4,
        }
        self._report.setdefault("robot_base_ui_nudges", []).append(entry)
        self._report.setdefault("robot_preposition", {})[
            "ui_position_m"
        ] = entry["position_m"]
        qualifier = " (limit reached)" if entry["limited"] else ""
        self._status_label.text = (
            f"Robot base moved {applied * 1000.0:+.0f} mm; "
            f"session offset {entry['forward_offset_m'] * 1000.0:+.0f} mm"
            f"{qualifier}"
        )
        _emit(self._report, self._report_path)

    def _set_camera(self, name: str) -> None:
        camera_path = self._camera_views.get(name)
        if camera_path is None:
            self._status_label.text = f"Camera view is unavailable: {name}"
            return
        self._visual_pull.end()
        _focus_viewport(camera_path)
        self._active_camera = name
        self._report["active_camera_view"] = name
        self._report["active_camera_path"] = camera_path
        self._status_label.text = f"Viewport: {name} ({camera_path})"
        _emit(self._report, self._report_path)

    def run_visual_pull_probe(self, context, stage, runtime: VineRuntime) -> dict:
        import numpy as np
        from pxr import Usd
        from pxr import UsdGeom

        cache = UsdGeom.BBoxCache(Usd.TimeCode.Default(), [UsdGeom.Tokens.default_])
        candidates = []
        projected_samples = []
        visual_count = 0
        for prim in Usd.PrimRange(stage.GetPrimAtPath(runtime.root_path)):
            if not prim.IsA(UsdGeom.Mesh) or not prim.GetName().startswith("Visual_"):
                continue
            visual_count += 1
            centre = cache.ComputeWorldBound(prim).ComputeCentroid()
            ndc = self._visual_pull.project_world(centre)
            if len(projected_samples) < 8:
                projected_samples.append(
                    {"visual": str(prim.GetPath()), "world": list(centre), "ndc": list(ndc)}
                )
            if np.isfinite(ndc).all() and abs(ndc[0]) < 0.95 and abs(ndc[1]) < 0.95:
                candidates.append((ndc[0] ** 2 + ndc[1] ** 2, ndc, str(prim.GetPath())))
        candidates.sort(key=lambda row: row[0])

        selected = None
        for _, ndc, visual in candidates[:24]:
            self._visual_pull.begin(ndc[:2])
            for _ in range(16):
                context.step(render=True)
                self._airflow.step()
                self._visual_pull.step()
            if self._visual_pull.active_body is not None:
                selected = (ndc, visual, self._visual_pull.active_body)
                break
            self._visual_pull.end()
        if selected is None:
            return {
                "succeeded": False,
                "error": "renderer raycast did not resolve dynamic visible geometry",
                "visual_meshes": visual_count,
                "on_screen_candidates": len(candidates),
                "projected_samples": projected_samples,
            }

        ndc, visual, body = selected
        start = _positions(stage, [body])[0]
        peak = 0.0
        self._visual_pull.update((min(ndc[0] + 0.08, 0.95), ndc[1]))
        for _ in range(60):
            context.step(render=True)
            self._airflow.step()
            self._visual_pull.step()
            peak = max(peak, float(np.linalg.norm(_positions(stage, [body])[0] - start)))
        self._visual_pull.end()
        for _ in range(240):
            context.step(render=True)
            self._airflow.step()
        final = _positions(stage, [body])[0]
        residual = float(np.linalg.norm(final - start))
        finite = bool(np.isfinite(final).all())
        return {
            "visual_candidate": visual,
            "body": body,
            "peak_displacement_mm": peak * 1000.0,
            "residual_displacement_mm": residual * 1000.0,
            "finite": finite,
            "succeeded": bool(finite and 0.001 < peak < 0.5 and residual < 0.1),
        }

    def _cut(self, context) -> None:
        runtime = self._runtimes[self._vine]
        label = self._targets[self._vine][self._target]
        context.pause()
        try:
            record = runtime.severer.cut(label, trigger="debug_forced")
        except Exception as exc:
            self._status_label.text = str(exc)
        else:
            forced = {
                **dataclasses.asdict(record),
                "vine": runtime.name,
                "benchmark_valid": False,
            }
            self._report.setdefault("debug_forced_cuts", []).append(forced)
            if self._grasp_manager is not None:
                self._grasp_manager.notify_cut(forced)
                self._report["bimanual_task"] = self._grasp_manager.summary
            self._status_label.text = (
                f"DEBUG forced cut {runtime.name}/{label}: {record.grade}; "
                "not benchmark-valid"
            )
            _emit(self._report, self._report_path)
        finally:
            context.play()

    def poll_tears(self) -> None:
        for runtime in self._runtimes:
            records = runtime.severer.poll_tears()
            if records:
                self._report.setdefault("tears", []).extend(
                    dataclasses.asdict(record) for record in records
                )
                self._status_label.text = f"Tore {runtime.name}/{records[-1].organ_label}"
                _emit(self._report, self._report_path)

    def _refresh(self) -> None:
        targets = self._targets[self._vine]
        label = targets[self._target] if targets else "none"
        self._target_label.text = (
            f"Vine {self._vine + 1}/{len(self._runtimes)}: "
            f"{self._runtimes[self._vine].name} | target {label}"
        )
        if self._blade_cutting is not None and targets:
            self._blade_cutting.set_active_target(
                self._runtimes[self._vine].name,
                label,
            )
        if self._grasp_manager is not None and targets:
            self._grasp_manager.set_active_target(
                self._runtimes[self._vine].name,
                label,
            )
        self._report["interaction_target"] = {
            "vine": self._runtimes[self._vine].name,
            "organ": label,
        }

    def close(self) -> None:
        self._visual_pull.close()
        if self._keyboard_sub is not None:
            self._input.unsubscribe_to_keyboard_events(self._keyboard, self._keyboard_sub)
            self._keyboard_sub = None
        self._window.visible = False


class _TeleopCameraRecorder:
    """Read the latest rendered D405 RGB observations into an episode folder."""

    def __init__(self, camera_views, camera_names, resolution, frames_directory) -> None:
        import numpy as np
        import omni.replicator.core as rep
        from PIL import Image

        self._np = np
        self._rep = rep
        self._Image = Image
        self._frames_directory = pathlib.Path(frames_directory)
        self._streams = {}
        self._last_rgb = {}
        for name in camera_names:
            camera_path = camera_views.get(name)
            if camera_path is None:
                raise ValueError(f"teleop camera is unavailable: {name}")
            product = rep.create.render_product(camera_path, resolution)
            annotator = rep.AnnotatorRegistry.get_annotator("rgb")
            annotator.attach([product])
            self._streams[name] = (camera_path, product, annotator)
        for _ in range(8):
            rep.orchestrator.step(rt_subframes=4)

    def capture(self, sample_index: int) -> tuple[dict[str, str], dict[str, str]]:
        images = {}
        errors = {}
        for name, (_, _, annotator) in self._streams.items():
            path = self._frames_directory / f"{sample_index:06d}_{name}.png"
            try:
                rgba = self._np.asarray(annotator.get_data())
                if rgba.ndim != 3 or rgba.shape[2] < 3 or rgba.size == 0:
                    raise ValueError(f"unexpected RGB shape {rgba.shape}")
                rgb = rgba[:, :, :3].astype(self._np.uint8)
                if not self._np.any(rgb):
                    raise ValueError("renderer returned an all-black RGB sample")
                self._last_rgb[name] = rgb.copy()
                self._Image.fromarray(rgb).save(path)
                images[name] = str(path.relative_to(self._frames_directory.parent))
            except Exception as exc:
                previous = self._last_rgb.get(name)
                if previous is None:
                    errors[name] = str(exc)
                    continue
                self._Image.fromarray(previous).save(path)
                images[name] = str(path.relative_to(self._frames_directory.parent))
                errors[name] = f"{exc}; reused previous valid RGB sample"
        return images, errors

    def close(self) -> None:
        for _, product, annotator in self._streams.values():
            with contextlib.suppress(Exception):
                annotator.detach([product])
            with contextlib.suppress(Exception):
                product.destroy()
        self._streams.clear()


class SimulatorTeleop:
    """Rate-limited, watchdog-protected leader-arm input for the simulator."""

    def __init__(
        self,
        stage,
        args,
        camera_views,
        selected_target,
        report,
        report_path,
        teleop_module,
        robot_hardware,
        robot_kinematics,
        blade_monitor,
        grasp_manager,
        contact_diagnostics,
    ) -> None:
        import os
        import time

        import numpy as np
        from isaacsim.core.prims import Articulation
        from pxr import Usd
        from pxr import UsdGeom

        self._time = time
        self._np = np
        self._Usd = Usd
        self._UsdGeom = UsdGeom
        self._stage = stage
        self._args = args
        self._teleop = teleop_module
        self._report = report
        self._report_path = report_path
        self._blade_monitor = blade_monitor
        self._grasp_manager = grasp_manager
        self._contact_diagnostics = contact_diagnostics
        self._camera_views = dict(camera_views)
        self._mailbox = teleop_module.CommandMailbox(args.teleop_command_file)
        self._model = robot_kinematics.Rby1Kinematics()
        limits = {
            side: self._model.arm_limits_degrees(side) for side in ("left", "right")
        }
        self._gate = teleop_module.TeleopSafetyGate(
            limits,
            watchdog_s=args.teleop_watchdog_ms / 1000.0,
            maximum_joint_speed_deg_s=args.teleop_max_joint_speed,
            joint_group_limits_degrees={
                "torso": _RBY1_TORSO_LIMITS_DEGREES,
                "head": _RBY1_HEAD_LIMITS_DEGREES,
            },
            joint_group_maximum_speeds_deg_s={
                "torso": 120.0,
                "head": 175.0,
            },
        )
        self._articulation = Articulation(
            prim_paths_expr="/World/RBY1",
            name="greenhouse_teleop_rby1",
            reset_xform_properties=False,
        )
        self._articulation.initialize()
        self._joint_group_dof_names = {
            "left": [f"left_arm_{index}" for index in range(7)],
            "right": [f"right_arm_{index}" for index in range(7)],
            "torso": [f"torso_{index}" for index in range(6)],
            "head": [f"head_{index}" for index in range(2)],
        }
        missing_dofs = sorted(
            name
            for names in self._joint_group_dof_names.values()
            for name in names
            if name not in self._articulation.dof_names
        )
        if missing_dofs:
            raise RuntimeError(f"RB-Y1 articulation is missing DOFs: {missing_dofs}")
        self._joint_group_dof_indices = {
            group: [self._articulation.get_dof_index(name) for name in names]
            for group, names in self._joint_group_dof_names.items()
        }
        self._previous_blade_point = None
        self._last_process_time = time.monotonic()
        self._last_command_time = None
        self._last_record_time = -float("inf")
        self._last_publish_time = -float("inf")
        self._last_gripper_closed = None
        self._last_gripper_openness = None
        self._commanded_targets = None
        self._last_safe_targets = None
        self._hold_targets = None
        self._hold_captures = 0
        self._contact_recoveries = 0
        self._latest_error = None
        self._unsafe_contacts = []
        self._unsafe_latched = False
        self._accepted_commands = 0
        self._rejected_commands = 0
        self._rate_limited_commands = 0
        self._watchdog_holds = 0
        self._last_sequence = None
        self._latest_age_ms = None
        self._recording = False
        self._closed = False
        tracked_groups = ("left", "right", "torso", "head")
        self._latest_simulated_joint_state = {
            group: None for group in tracked_groups
        }
        self._latest_source_joint_degrees = {
            group: None for group in tracked_groups
        }
        self._latest_source_joint_degrees["left_gripper_openness"] = None
        self._latest_applied_target_degrees = {
            group: None for group in tracked_groups
        }

        self._drive_configuration = {
            side: _configure_arm_drives(stage, side) for side in ("left", "right")
        }
        self._drive_configuration["torso"] = _configure_joint_group_drives(
            stage,
            "torso",
            _RBY1_TORSO_EFFORT_LIMITS_NM,
            _RBY1_TORSO_STIFFNESS_NM_RAD,
            _RBY1_TORSO_DAMPING_NM_S_RAD,
        )
        self._drive_configuration["head"] = _configure_joint_group_drives(
            stage,
            "head",
            _RBY1_HEAD_EFFORT_LIMITS_NM,
            _RBY1_HEAD_STIFFNESS_NM_RAD,
            _RBY1_HEAD_DAMPING_NM_S_RAD,
        )
        self._recorder = None
        self._camera_recorder = None
        self._episode_directory = None
        if args.teleop_record_dir is not None:
            stamp = time.strftime("%Y%m%dT%H%M%SZ", time.gmtime())
            self._episode_directory = pathlib.Path(args.teleop_record_dir) / (
                f"episode_{stamp}_{os.getpid()}"
            )
            self._recorder = teleop_module.DemonstrationRecorder(
                self._episode_directory,
                {
                    "schema": "greenhouse.demonstration.v1",
                    "target": selected_target.key,
                    "episode_seed": selected_target.seed,
                    "command_schema": teleop_module.SCHEMA,
                    "command_file": str(pathlib.Path(args.teleop_command_file).resolve()),
                    "simulator_only": True,
                    "physical_robot_commanded": False,
                    "physics_hz": 240.0,
                    "record_hz": args.teleop_record_hz,
                    "camera_resolution": [args.teleop_width, args.teleop_height],
                    "cameras": list(args.teleop_cameras),
                    "watchdog_ms": args.teleop_watchdog_ms,
                    "maximum_joint_speed_deg_s": args.teleop_max_joint_speed,
                },
            )

        self._publish(force=True)

    def _joint_group_state(self, group: str) -> dict:
        indices = self._joint_group_dof_indices[group]
        expected = len(indices)
        positions = self._np.asarray(
            self._articulation.get_joint_positions(joint_indices=indices),
            dtype=self._np.float64,
        ).reshape(-1)
        velocities = self._np.asarray(
            self._articulation.get_joint_velocities(joint_indices=indices),
            dtype=self._np.float64,
        ).reshape(-1)
        if positions.size != expected or velocities.size != expected:
            raise RuntimeError(
                f"live PhysX state for {group} has unexpected shape "
                f"({positions.size}, {velocities.size})"
            )
        if not self._np.isfinite(positions).all() or not self._np.isfinite(velocities).all():
            raise RuntimeError(f"live PhysX state for {group} is non-finite")
        return {
            "position_degrees": self._np.degrees(positions).tolist(),
            "velocity_degrees_s": self._np.degrees(velocities).tolist(),
        }
    def _ee_matrix(self, side: str) -> list[list[float]]:
        matrix = self._UsdGeom.Xformable(
            self._stage.GetPrimAtPath(f"/World/RBY1/ee_{side}")
        ).ComputeLocalToWorldTransform(self._Usd.TimeCode.Default())
        return [[float(matrix[row][column]) for column in range(4)] for row in range(4)]

    def _current_unsafe_contacts(self) -> list[dict]:
        if self._contact_diagnostics is None:
            return []
        blade_geometry = self._blade_monitor.target_geometry
        grasp_geometry = self._grasp_manager.target_geometry
        if blade_geometry is None or grasp_geometry is None:
            return []
        return _probe_unsafe_contacts(
            self._contact_diagnostics.active_summary,
            blade_geometry,
            grasp_geometry,
        )

    def _set_blade_velocity(self, *, moving: bool, dt_s: float) -> None:
        point = self._blade_monitor.edge_centre_m
        velocity = self._np.zeros(3, dtype=self._np.float64)
        if moving and self._previous_blade_point is not None and dt_s > 0.0:
            velocity = (point - self._previous_blade_point) / dt_s
        self._previous_blade_point = point.copy()
        self._blade_monitor.set_commanded_edge_velocity(velocity)
    def _record(self, simulation_step: int, now_s: float, command, states) -> None:
        if self._recorder is None or not command.recording:
            return
        if now_s - self._last_record_time < 1.0 / self._args.teleop_record_hz:
            return
        if self._camera_recorder is None:
            self._camera_recorder = _TeleopCameraRecorder(
                self._camera_views,
                self._args.teleop_cameras,
                (self._args.teleop_width, self._args.teleop_height),
                self._recorder.frames_directory,
            )
        sample_index = self._recorder.samples
        images, camera_errors = self._camera_recorder.capture(sample_index)
        grasp_summary = self._grasp_manager.summary
        task = grasp_summary.get("task") or {}
        blade_summary = self._blade_monitor.summary
        self._recorder.append(
            {
                "schema": "greenhouse.demonstration.step.v1",
                "sample_index": sample_index,
                "simulation_step": simulation_step,
                "simulation_time_s": simulation_step / 240.0,
                "host_monotonic_time_s": now_s,
                "target": blade_summary.get("active_target"),
                "observation": {
                    "left_arm": states["left"],
                    "right_arm": states["right"],
                    "torso": states["torso"],
                    "head": states["head"],
                    "left_gripper_openness": command.left_gripper_openness,
                    "left_ee_world_matrix": self._ee_matrix("left"),
                    "right_ee_world_matrix": self._ee_matrix("right"),
                    "cameras": images,
                    "camera_errors": camera_errors,
                },
                "action": dataclasses.asdict(command),
                "task": {
                    "phase": task.get("phase"),
                    "grasp_active": task.get("grasp_active"),
                    "task_succeeded": self._grasp_manager.task_succeeded,
                    "active_grasp_body": grasp_summary.get("active_grasp_body"),
                    "physical_cuts": len(blade_summary.get("physical_cuts", ())),
                    "cut_feedback": self._blade_monitor.active_cut_feedback,
                },
                "safety": {
                    "blade_safety_clear": self._blade_monitor.safety_clear,
                    "unsafe_contact_count": len(self._unsafe_contacts),
                    "unsafe_latched": self._unsafe_latched,
                },
            }
        )
        self._last_record_time = now_s

    @property
    def summary(self) -> dict:
        now = self._time.monotonic()
        watchdog_age_ms = (
            None
            if self._last_command_time is None
            else (now - self._last_command_time) * 1000.0
        )
        return {
            "schema": self._teleop.SCHEMA,
            "simulator_only": True,
            "physical_robot_commanded": False,
            "command_file": str(pathlib.Path(self._args.teleop_command_file).resolve()),
            "watchdog_ms": self._args.teleop_watchdog_ms,
            "maximum_joint_speed_deg_s": self._args.teleop_max_joint_speed,
            "accepted_commands": self._accepted_commands,
            "rejected_commands": self._rejected_commands,
            "rate_limited_commands": self._rate_limited_commands,
            "watchdog_holds": self._watchdog_holds,
            "last_sequence": self._last_sequence,
            "latest_command_age_ms": self._latest_age_ms,
            "watchdog_age_ms": watchdog_age_ms,
            "watchdog_fresh": (
                watchdog_age_ms is not None
                and watchdog_age_ms <= self._args.teleop_watchdog_ms
            ),
            "unsafe_latched": self._unsafe_latched,
            "unsafe_contacts": self._unsafe_contacts,
            "contact_policy": self._args.teleop_contact_policy,
            "contact_recoveries": self._contact_recoveries,
            "recording": self._recording,
            "recorded_samples": self._recorder.samples if self._recorder is not None else 0,
            "episode_directory": (
                str(self._episode_directory) if self._episode_directory is not None else None
            ),
            "latest_error": self._latest_error,
            "hold_active": self._hold_targets is not None,
            "hold_captures": self._hold_captures,
            "hold_target_degrees": self._hold_targets,
            "simulated_joint_state": self._latest_simulated_joint_state,
            "source_joint_degrees": self._latest_source_joint_degrees,
            "applied_target_degrees": self._latest_applied_target_degrees,
            "drive_configuration": self._drive_configuration,
        }

    def _publish(self, *, force: bool = False) -> None:
        now = self._time.monotonic()
        if not force and now - self._last_publish_time < 1.0:
            return
        self._report["teleoperation"] = self.summary
        _emit(self._report, self._report_path)
        self._last_publish_time = now

    def _ensure_commanded_targets(self, states) -> None:
        if self._commanded_targets is None:
            self._commanded_targets = {
                group: list(state["position_degrees"])
                for group, state in states.items()
            }

    def _hold_joint_groups(self, states) -> None:
        """Hold one captured pose; never chase a gravity-driven falling state."""
        self._ensure_commanded_targets(states)
        if self._hold_targets is None:
            self._hold_targets = {
                group: list(state["position_degrees"])
                for group, state in states.items()
            }
            self._hold_captures += 1
        for group, target in self._hold_targets.items():
            _set_joint_group_drive_targets(self._stage, group, target)
        self._latest_applied_target_degrees = {
            group: list(target)
            for group, target in self._hold_targets.items()
        }

    def _rollback_to_last_safe(self, states) -> None:
        """Drive back one contact-free sample instead of freezing in contact."""
        self._ensure_commanded_targets(states)
        if self._hold_targets is None:
            source = self._last_safe_targets or {
                group: list(state["position_degrees"])
                for group, state in states.items()
            }
            self._hold_targets = {
                group: list(target) for group, target in source.items()
            }
            self._hold_captures += 1
        for group, target in self._hold_targets.items():
            _set_joint_group_drive_targets(self._stage, group, target)
        self._latest_applied_target_degrees = {
            group: list(target)
            for group, target in self._hold_targets.items()
        }
    def process(self, simulation_step: int) -> None:
        now = self._time.monotonic()
        dt_s = max(now - self._last_process_time, 1.0 / 240.0)
        self._last_process_time = now
        states = {
            group: self._joint_group_state(group)
            for group in ("left", "right", "torso", "head")
        }
        self._latest_simulated_joint_state = states
        self._ensure_commanded_targets(states)
        was_recovering = self._unsafe_latched
        self._unsafe_contacts = self._current_unsafe_contacts()
        if (
            self._unsafe_contacts
            and self._args.teleop_contact_policy == "rollback"
        ):
            if not was_recovering:
                self._contact_recoveries += 1
            self._unsafe_latched = True
            self._rollback_to_last_safe(states)
            self._blade_monitor.set_commanded_edge_velocity(self._np.zeros(3))
            self._latest_error = (
                "unsafe robot contact active; rolling back to the last "
                "contact-free pose"
            )
            self._publish()
            return

        if was_recovering:
            self._unsafe_latched = False
            self._hold_targets = None
            self._commanded_targets = {
                group: list(state["position_degrees"])
                for group, state in states.items()
            }
            self._latest_error = None
        if not self._unsafe_contacts:
            self._last_safe_targets = {
                group: list(state["position_degrees"])
                for group, state in states.items()
            }
        try:
            raw = self._mailbox.poll()
        except self._teleop.TeleopCommandError as exc:
            self._rejected_commands += 1
            self._latest_error = str(exc)
            self._hold_joint_groups(states)
            self._blade_monitor.set_commanded_edge_velocity(self._np.zeros(3))
            self._publish()
            return
        if raw is None:
            self._blade_monitor.set_commanded_edge_velocity(self._np.zeros(3))
            if (
                self._last_command_time is not None
                and now - self._last_command_time > self._args.teleop_watchdog_ms / 1000.0
            ):
                self._hold_joint_groups(states)
                self._recording = False
                self._watchdog_holds += 1
                self._latest_error = "teleop watchdog expired; measured pose is held"
            self._publish()
            return

        self._latest_source_joint_degrees = {
            "left": list(raw.left.joint_degrees),
            "right": list(raw.right.joint_degrees),
            "torso": (
                list(raw.torso.joint_degrees) if raw.torso is not None else None
            ),
            "head": (
                list(raw.head.joint_degrees) if raw.head is not None else None
            ),
            "left_gripper_openness": (
                raw.left_gripper.openness
                if raw.left_gripper is not None
                else None
            ),
        }
        try:
            command = self._gate.accept(
                raw,
                now_s=now,
                dt_s=dt_s,
                current_left_degrees=states["left"]["position_degrees"],
                current_right_degrees=states["right"]["position_degrees"],
                current_torso_degrees=states["torso"]["position_degrees"],
                current_head_degrees=states["head"]["position_degrees"],
            )
        except self._teleop.TeleopCommandError as exc:
            self._rejected_commands += 1
            self._latest_error = str(exc)
            self._hold_joint_groups(states)
            self._blade_monitor.set_commanded_edge_velocity(self._np.zeros(3))
            self._publish()
            return

        targets = {
            "left": command.left_target_degrees,
            "right": command.right_target_degrees,
            "torso": command.torso_target_degrees,
            "head": command.head_target_degrees,
        }
        apply = {
            "left": command.apply_left,
            "right": command.apply_right,
            "torso": command.apply_torso,
            "head": command.apply_head,
        }
        self._hold_targets = None
        for group in ("left", "right", "torso", "head"):
            target = targets[group]
            if apply[group] and target is not None:
                self._commanded_targets[group] = list(target)
            _set_joint_group_drive_targets(
                self._stage, group, self._commanded_targets[group]
            )
        self._latest_applied_target_degrees = {
            group: list(target)
            for group, target in self._commanded_targets.items()
        }

        if command.apply_left_gripper:
            if command.left_gripper_openness is not None:
                openness = float(command.left_gripper_openness)
                if (
                    self._last_gripper_openness is None
                    or abs(openness - self._last_gripper_openness) >= 1e-4
                ):
                    self._grasp_manager.request_openness(openness)
                    self._last_gripper_openness = openness
                self._last_gripper_closed = openness <= 0.10
            elif command.left_gripper_closed != self._last_gripper_closed:
                if command.left_gripper_closed:
                    self._grasp_manager.request_close()
                else:
                    self._grasp_manager.request_open()
                self._last_gripper_closed = command.left_gripper_closed
                self._last_gripper_openness = (
                    0.0 if command.left_gripper_closed else 1.0
                )

        self._set_blade_velocity(
            moving=command.apply_right or command.apply_torso,
            dt_s=dt_s,
        )
        self._accepted_commands += 1
        self._rate_limited_commands += int(command.rate_limited)
        self._last_sequence = command.sequence
        self._last_command_time = now
        self._latest_age_ms = command.age_s * 1000.0
        self._latest_error = None
        self._recording = bool(command.recording and self._recorder is not None)
        self._record(simulation_step, now, command, states)
        self._publish()
    def close(self) -> None:
        if self._closed:
            return
        self._blade_monitor.set_commanded_edge_velocity(self._np.zeros(3))
        if self._camera_recorder is not None:
            self._camera_recorder.close()
        if self._recorder is not None:
            self._recorder.close()
        self._recording = False
        self._closed = True
        self._publish(force=True)


def _run_headless_checks(stage, context, runtimes, selected_target, args, report: dict) -> bool:
    import numpy as np

    success = True
    stability = []
    for runtime in runtimes:
        paths = _base_link_paths(runtime.rig)
        now = _positions(stage, paths)
        moved = np.linalg.norm(now - runtime.rest_positions, axis=1)
        finite = bool(np.isfinite(now).all())
        runaways = int(np.sum(moved > 0.1))
        largest = np.argsort(moved)[::-1][:5]
        stability.append(
            {
                "vine": runtime.name,
                "finite": finite,
                "max_displacement_mm": float(np.nanmax(moved) * 1000.0),
                "runaway_organs": runaways,
                "organs_tracked": len(paths),
                "largest_displacements": [
                    {
                        "path": paths[int(index)],
                        "displacement_mm": float(moved[int(index)] * 1000.0),
                    }
                    for index in largest
                ],
            }
        )
        success = success and finite and runaways == 0
    report["stability"] = stability

    if report.get("robot_requested"):
        robot_stability = _robot_stability(stage, args)
        report["robot_stability"] = robot_stability
        success = success and bool(robot_stability["succeeded"])
        selected_runtime = next(
            runtime for runtime in runtimes if runtime.name == selected_target.vine_name
        )
        robot_precontact = _robot_precontact(
            stage,
            selected_runtime,
            selected_target.organ_label,
            args.robot_yaw,
        )
        robot_precontact["acceptance_required"] = False
        robot_precontact["diagnostic_reason"] = (
            "natural SDK-ready startup; task precontact is planned on demand"
        )
        report["robot_precontact"] = robot_precontact

    if args.airflow_probe_steps > 0:
        from greenhouse_sim import vine_interaction

        airflow = vine_interaction.Airflow(
            stage,
            runtimes,
            speed_m_s=args.airflow_speed,
            frequency_hz=args.airflow_frequency,
            direction_deg=args.airflow_direction,
        )
        report["airflow"] = airflow.summary
        airflow_probe = _airflow_probe(stage, context, airflow, args.airflow_probe_steps)
        report["airflow_probe"] = airflow_probe
        success = success and bool(airflow_probe["succeeded"])

    if args.pull_probe:
        pull = _pull_probe(stage, context, runtimes[0], args.pull_probe, args)
        report["pull_probe"] = pull
        success = success and bool(pull["succeeded"])
    if args.cut:
        cut = _cut_probe(stage, context, runtimes[0], args.cut, args.post_cut_steps)
        report["cut_probe"] = cut
        success = success and bool(cut["succeeded"])
    return success


def _robot_stability(stage, args) -> dict:
    import numpy as np
    from pxr import Gf
    from pxr import Usd
    from pxr import UsdGeom
    from pxr import UsdPhysics

    root_path = "/World/RBY1"
    rigid_paths = [
        str(prim.GetPath())
        for prim in stage.Traverse()
        if str(prim.GetPath()).startswith(f"{root_path}/") and prim.HasAPI(UsdPhysics.RigidBodyAPI)
    ]
    positions = _positions(stage, rigid_paths)
    base = stage.GetPrimAtPath(f"{root_path}/base")
    if not rigid_paths or not base.IsValid():
        return {"succeeded": False, "error": "fitted robot rigid bodies are missing"}

    base_matrix = UsdGeom.Xformable(base).ComputeLocalToWorldTransform(Usd.TimeCode.Default())
    base_position = np.asarray(base_matrix.ExtractTranslation(), dtype=np.float64)
    expected = np.asarray(args.robot_position, dtype=np.float64)
    displacement = base_position - expected
    up = np.asarray(base_matrix.TransformDir(Gf.Vec3d(0.0, 0.0, 1.0)), dtype=np.float64)
    up /= max(float(np.linalg.norm(up)), 1e-12)
    tilt_degrees = float(np.degrees(np.arccos(np.clip(up[2], -1.0, 1.0))))
    finite = bool(np.isfinite(positions).all() and np.isfinite(up).all())
    succeeded = bool(
        finite
        and len(rigid_paths) == 34
        and np.linalg.norm(displacement[:2]) < 0.05
        and abs(displacement[2]) < 0.10
        and tilt_degrees < 10.0
    )
    return {
        "rigid_bodies": len(rigid_paths),
        "finite": finite,
        "base_position_m": base_position.tolist(),
        "base_displacement_mm": (displacement * 1000.0).tolist(),
        "base_tilt_degrees": tilt_degrees,
        "succeeded": succeeded,
    }


def _robot_precontact(
    stage,
    runtime: VineRuntime,
    target_label: str,
    robot_yaw_degrees: float,
) -> dict:
    """Measure the settled knife pose against the selected physical petiole."""
    from greenhouse_sim import robot_hardware
    import numpy as np
    from pxr import Gf
    from pxr import Usd
    from pxr import UsdGeom

    target_position = runtime.cut_sites.get(target_label)
    if target_position is None:
        return {"succeeded": False, "error": f"missing cut site {target_label}"}

    knife_root_path = "/World/RBY1/ee_right/attachments/DeleafKnife"
    blade_path = f"{knife_root_path}/Blade"
    arc_path = f"{knife_root_path}/Arc"
    knife_root = stage.GetPrimAtPath(knife_root_path)
    blade = stage.GetPrimAtPath(blade_path)
    arc = stage.GetPrimAtPath(arc_path)
    if not knife_root.IsValid() or not blade.IsValid() or not arc.IsValid():
        return {"succeeded": False, "error": "fitted knife geometry is missing"}

    target = np.asarray(target_position, dtype=np.float64)
    cache = UsdGeom.BBoxCache(
        Usd.TimeCode.Default(), [UsdGeom.Tokens.default_, UsdGeom.Tokens.render]
    )

    def bounds_and_distance(prim):
        extent = cache.ComputeWorldBound(prim).ComputeAlignedRange()
        minimum = np.asarray(extent.GetMin(), dtype=np.float64)
        maximum = np.asarray(extent.GetMax(), dtype=np.float64)
        outside = np.maximum(np.maximum(minimum - target, target - maximum), 0.0)
        return minimum, maximum, float(np.linalg.norm(outside))

    blade_min, blade_max, blade_distance = bounds_and_distance(blade)
    arc_min, arc_max, arc_distance = bounds_and_distance(arc)
    knife_matrix = UsdGeom.Xformable(knife_root).ComputeLocalToWorldTransform(Usd.TimeCode.Default())
    blade_matrix = UsdGeom.Xformable(blade).ComputeLocalToWorldTransform(Usd.TimeCode.Default())
    blade_extension = np.asarray(
        blade_matrix.TransformDir(
            Gf.Vec3d(*robot_hardware.KNIFE_CUT_DIRECTION_LOCAL.tolist())
        ).GetNormalized(),
        dtype=np.float64,
    )
    arc_facing = np.asarray(
        blade_matrix.TransformDir(Gf.Vec3d(0.0, 0.0, 1.0)).GetNormalized(),
        dtype=np.float64,
    )
    finite = bool(
        np.isfinite(target).all()
        and np.isfinite(blade_min).all()
        and np.isfinite(blade_max).all()
        and np.isfinite(arc_min).all()
        and np.isfinite(arc_max).all()
        and np.isfinite(blade_extension).all()
        and np.isfinite(arc_facing).all()
    )
    # Both components must remain within the arm's conservative one-metre
    # approach envelope and outside a 5 mm no-spawn-contact margin. The wider
    # upper bound accommodates the lower-gutter-safe raised/rearward stow; the
    # full probe separately proves bounded IK, inter-arm clearance, contact
    # safety, and the physical cut. The blade points into the row and the U faces up.
    yaw_radians = np.radians(float(robot_yaw_degrees))
    robot_forward_xy = np.asarray(
        [np.cos(yaw_radians), np.sin(yaw_radians)], dtype=np.float64
    )
    blade_forward_alignment = float(np.dot(blade_extension[:2], robot_forward_xy))
    succeeded = bool(
        finite
        and 0.005 < blade_distance < 1.000
        and 0.005 < arc_distance < 1.000
        and blade_forward_alignment > 0.70
        and arc_facing[2] > 0.70
    )
    return {
        "vine": runtime.name,
        "target": target_label,
        "target_position_m": target.tolist(),
        "knife_root_position_m": list(knife_matrix.ExtractTranslation()),
        "blade_extension": blade_extension.tolist(),
        "blade_forward_alignment": blade_forward_alignment,
        "arc_facing": arc_facing.tolist(),
        "blade_distance_to_target_mm": blade_distance * 1000.0,
        "arc_distance_to_target_mm": arc_distance * 1000.0,
        "blade_bounds_m": {"min": blade_min.tolist(), "max": blade_max.tolist()},
        "arc_bounds_m": {"min": arc_min.tolist(), "max": arc_max.tolist()},
        "finite": finite,
        "succeeded": succeeded,
    }


