def _greenhouse_startup_arm_targets(
    initial_left_degrees=None,
    *,
    task_safe: bool = True,
) -> dict:
    """Return task-safe benchmark arms or neutral SDK teleop arms."""
    if not isinstance(task_safe, bool):
        raise ValueError("task_safe must be a boolean")
    left = (
        (
            _LEFT_GREENHOUSE_WAITING_DEGREES
            if task_safe
            else _LEFT_READY_DEGREES
        )
        if initial_left_degrees is None
        else tuple(float(value) for value in initial_left_degrees)
    )
    if len(left) != 7 or not all(math.isfinite(value) for value in left):
        raise ValueError("initial left arm must contain seven finite degrees")
    return {
        "left": tuple(float(value) for value in left),
        "right": (
            _RIGHT_SAFE_DEGREES if task_safe else _RIGHT_READY_DEGREES
        ),
    }


def _startup_task_stow_reached(
    measured_degrees,
    target_degrees,
    maximum_error_degrees: float = 0.5,
) -> bool:
    """Return whether a measured arm is already at its task-stow target."""
    import numpy as np

    measured = np.asarray(measured_degrees, dtype=np.float64)
    target = np.asarray(target_degrees, dtype=np.float64)
    tolerance = float(maximum_error_degrees)
    if (
        measured.shape != (7,)
        or target.shape != (7,)
        or not np.isfinite(measured).all()
        or not np.isfinite(target).all()
        or not math.isfinite(tolerance)
        or tolerance < 0.0
    ):
        raise ValueError("task-stow comparison must contain finite arm states")
    return bool(np.max(np.abs(measured - target)) <= tolerance)


